UDLText.Content:
/* a strict parser might ignore comments and white space
   but here I want to keep them so they can be represented in html
   */

Method.Implementation:
Set str=""
if wspace'=0,..whitespace {
	if wspace]"" {
		Set str=wspace
	} else {
		Set str=..whitespace.ToString("")
	}
}
Set str=str_..start
Set str=str_..value
Set str=str_..end
Quit str

i $$$debugIsON {
	$$$DEBUG(($j($l(indent),2))_indent_"type="_..type)
	;i $isobject(..whitespace) d ..whitespace.display(indent_"  ")
	$$$DEBUG(($j($l(indent),2))_indent_" "_$zconvert(..start_..value_..end,"O","JS"))
}

#dim a as PXW.DEV.Atom

Do ..processSpecificElement(element)

Set akey=""
For  {
	Set part=element.partsGetNext(.akey)
	Quit:akey=""

	If part.IsElement {
		Do ..checkElement(part)
	} 
}

; AFTER full analysis we can flag a couple of things
;If element.type="OneClassmember" {
;	Do ..checkOneClassMemeberFINAL(element)
;}
Do ..processSpecificElement(element,"POST")

If ..ClassServer.GetClassDetails(Classname,,,.primarysuper) {
	If primarysuper[("~"_SuperClass_"~") Quit 1
}
Quit 0

$$$DEBUGMethodBegin
Set commonClass="",depth=0,result=0
If Classname1="-null-" Quit 1 ; null is compatible with everything
If Classname2="-null-" Quit 1 ; 
If Classname1="%Library.Any" Quit 1 ; %Library.Any is compatible with everything
If Classname2="%Library.Any" Quit 1 ; 

Set cn1=..FullClassName(Classname1)
Set cn2=..FullClassName(Classname2)
; for checking compatibility ObjectHandle is like a RegisteredObject
Set cn1=$SELECT(cn1="%Library.ObjectHandle":"%Library.RegistedObject",1:cn1)
Set cn2=$SELECT(cn2="%Library.ObjectHandle":"%Library.RegistedObject",1:cn2)
If ..ClassServer.GetClassDetails(cn1,.classtype1,.prime1,.super1),..ClassServer.GetClassDetails(cn2,.classtype2,.prime2,.super2) {
	Set super1=super1_$SELECT($PIECE(prime1,",",2,*)'="":$TRANSLATE($PIECE(prime1,",",2,*),",","~")_"~",1:"")
	Set super2=super2_$SELECT($PIECE(prime2,",",2,*)'="":$TRANSLATE($PIECE(prime2,",",2,*),",","~")_"~",1:"")
	; maybe parameterise this check, sometimes we want to know numbers and strings are being confused, but mostly not
	If classtype1="datatype",classtype2="datatype" {
		; all ok
		Set result=1,commonClass="-datatype-",depth=1
	} Else {
		Set common1="",d1=0
		For i=2:1:$LENGTH(super1,"~")-1 {
			Set cls=$PIECE(super1,"~",i)
			If common1="",super2[("~"_cls_"~") Set common1=cls,d1=i-1
		}
		Set common2="",d2=0
		For i=2:1:$LENGTH(super2,"~")-1 {
			Set cls=$PIECE(super2,"~",i)
			If common2="",super1[("~"_cls_"~") Set common2=cls,d2=i-1
		}
		If d1>0,d1<d2 {
			Set commonClass=common1,depth=d1,result=1
		} ElseIf d2>0 {
			Set commonClass=common2,depth=d2,result=1
		}
	}
	$$$DEBUG($$$debugFormat("super1={super1}, super2={super2}"))
}
$$$DEBUGMethodEnd
Quit result

$$$DEBUGMethodBegin
If '..ShortCommand {
	Set directiveE=element.findFirstElementByType("CosDirective",0)
	; directives count as a command (is this right?) but start with a # atom so would end up being counted as short
	; therefore only check if its NOT a directive
	If '$ISOBJECT(directiveE) {
		Set a=element.FirstAtom()
		If $LENGTH(a.value)=1 {
			Set ..ShortCommand=element
		}
	}
}
If '..LongCommand {
	Set a=element.FirstAtom()
	If $LENGTH(a.value)>1 {
		Set ..LongCommand=element
	}
}
$$$DEBUGMethodEnd
Quit ""

$$$DEBUGMethodBegin
Set var=Variable
Set velement=VariableElement
Set derivedtype=..FullClassName(DerivedType)
Set dimmedtype=..FullClassName($GET(..DimmedTypes(var)))
Set currenttype=..FullClassName($GET(..VariablesTypes(var)))
Set listelementtype=..FullClassName(ListElementTypeClass) ; for LISTS etc that return a type
If dimmedtype'="",derivedtype'="",dimmedtype'=derivedtype {
	If ..IsCompatible(derivedtype,dimmedtype,.cls,.depth) {
		Do:depth>1 ..AddElementWarning(velement,"VTYPE","Derived type of "_var_" ("_derivedtype_") differs to dimmed type ("_dimmedtype_") but they are compatible via "_cls_" at depth "_depth)
	} Else {
		Do ..AddElementWarning(velement,"VTYPE","Derived type of "_var_" ("_derivedtype_") differs to dimmed type ("_dimmedtype_")")
	}
}
; assume the programmer is right, i.e. prefer the dimmed type
Set finaltype=..FullClassName($SELECT(dimmedtype'="":dimmedtype,1:derivedtype))

If currenttype'="",finaltype'="",currenttype'=finaltype {
	If ..IsCompatible(finaltype,currenttype,.cls,.depth) {
		Do:depth>2 ..AddElementWarning(velement,"VTYPE","Change of type on "_var_" from "_currenttype_" to "_finaltype_" but they are compatible via "_cls_" at depth "_depth)
	} Else {
		Do ..AddElementWarning(velement,"VTYPE","Change of type on "_var_" from "_currenttype_" to "_finaltype)
	}
}
; we have a type so remember it, dont bother storing when it went to null, thats normally not useful
If finaltype'="",finaltype'="-null-" {
	Set ..VariablesTypes(var)=finaltype
	Set ..VariablesTypesElement(+VariableElement)=finaltype
	Set ..ListVarElementType(var)=listelementtype
}
$$$DEBUGMethodEnd

$$$DEBUGMethodBegin
;  variable name part is the only bit we are interested in
Set varname=element.FirstAtom().ToString(0)
Set ..VariablesUsed(varname,+element)=element
; each time a variable is used record its current type, I think there are many places that might do this so only set once
;if '$d(..VariablesTypesElement(+element)) {
	Set ..VariablesTypesElement(+element)=$GET(..VariablesTypes(varname))
	; this does all sorts of things along the way (side effect, a bit nasty)
	Do ..DeriveTypeReturned(element)
;}
Set uvar=$$$UPPER(varname)
If $DATA(..BadVars(uvar)) {
	If '$DATA(..BadVarsUsed(uvar)) {
		Do ..AddElementWarning(element,"VBAD",varname_" bad variable name")
		Set ..BadVarsUsed(uvar)=element
	}
}
; ByRef variables are BEING set so dont check for undef, {var} are actually property names so skip those too
If element.type'="ByrefVariable",$EXTRACT(varname,1)'="%",$EXTRACT(varname,1)'="{",'$DATA(..VariablesSet(varname)),'$DATA(..ParameterVariables(varname)) {
	Do ..AddElementWarning(element,"VUNDEF",varname_" Possible UNDEF")
}
$$$DEBUGMethodEnd
Quit ""

$$$DEBUGMethodBegin
; Find direct variables, these 'could' be being set by the macro.
; We should look at the macro and work out what its doing to be really clever, for now just count them as being set so we avoid undef
Do element.findElementsXPath("MacroParameterList/MacroParameter/Expression/Factor/Primary/Variable",.variablelist)
If $ISOBJECT($GET(variablelist)) {
	For i=1:1:variablelist.Count() {
		Set varE=variablelist.GetAt(i)
		Set varname=varE.FirstAtom().ToString(0)
		Set ..VariablesSet(varname)=varE
	}
}
$$$DEBUGMethodEnd
Quit ""

$$$DEBUGMethodBegin
Set classele=element.findFirstElementByType("ClassReference",0)
Set classname=""
If $ISOBJECT(classele) {
	Set classname=classele.ToString(0)
	Do element.findElementsByType("VariableSet",.variablelist,0)
	For i=1:1:variablelist.Count() {
		Set var=variablelist.GetAt(i).ToString(0)
		Set ..DimmedTypes(var)=classname
	}
}
Set dimexprE=element.findFirstElementByType("DimExpression",0)
If $ISOBJECT(dimexprE) {
	Set derivedtype=..DeriveTypeReturned(dimexprE)
	; #dim x = ##class(object).method() 
	; it has no dimmed type so what ever we derive must be correct
	If classname="",derivedtype'="",derivedtype'="-null-" {
		Set classname=derivedtype
		Do element.findElementsByType("VariableSet",.variablelist,0)
		For i=1:1:variablelist.Count() {
			Set var=variablelist.GetAt(i).ToString(0)
			Set ..DimmedTypes(var)=classname
		}
	}
	Set fullret=..FullClassName(classname),fullder=..FullClassName(derivedtype)
	If ..IsCompatible(fullret,fullder,.cls,.depth) {
		Do:depth>1 ..AddElementWarning(element,"VTYPE","dimmed as "_fullret_" does not match derived "_fullder_" but they are compatible via "_cls_" at depth "_depth)
	} Else {
		Do ..AddElementWarning(element,"VTYPE","dimmed as "_fullret_" does not match derived "_fullder)
	}
}
$$$DEBUGMethodEnd
Quit ""

$$$DEBUGMethodBegin
Set classele=element.findFirstElementByType("ClassReference")
If $ISOBJECT(classele) {
	Set classname=classele.ToString(0)
	Do element.findElementsByType("VariableNodef",.variablelist,0)
	For i=1:1:variablelist.Count() {
		Set var=variablelist.GetAt(i).ToString(0)
		Set ..DimmedTypes(var)=classname
	}
}
$$$DEBUGMethodEnd
Quit ""

$$$DEBUGMethodBegin
; the variables on a for loop do not "need" to be used so we will not check for undef on them, but we will keep track of them being used
Do element.findElementsXPath("ForParameterList/ForParameter/LvalueExpression/VariableSet",.variablelist)
If $ISOBJECT($GET(variablelist)) {
	For i=1:1:variablelist.Count() {
		Set varE=variablelist.GetAt(i)
		Set varname=varE.FirstAtom().ToString(0)
		Set ..VariablesUsed(varname)=varE
	}
}
$$$DEBUGMethodEnd
Quit ""

	$$$DEBUGMethodBegin
    Set varE=element.findFirstElementByType("VariableSet",0)
    If $ISOBJECT(varE) {
		Set var=varE.ToString(0)
		; if its JUST a variable then we are interested in keeping track of it
		If varE.partsCount()=1 {
			Set ..VariablesUsed(var,+element)=varE
		} Else {
			; its an array or some sort of object.property, so its a var being used
			Set varname=varE.FirstAtom().ToString(0)
			Set ..VariablesUsed(varname,+element)=varE
		}        
    }
	$$$DEBUGMethodEnd
	Quit ""

$$$DEBUGMethodBegin
If element.type="QuitCommand" {
	Set quitexpE=element.findFirstElementByType("QuitExpression",1)	
} ElseIf element.type="ReturnCommand" {
	Set quitexpE=element.findFirstElementByType("ReturnExpression",1)
} Else {
	Set quitexpE=""
}
If $ISOBJECT(quitexpE) {
	Set derivedtype=..DeriveTypeReturned(quitexpE)
	If derivedtype="" {
		If quitexpE.ToString(0)="""""" {
			; if the return value is null ("") then this is always ok
			Set derivedtype=..ReturnType
		} Else {
			If ..ClassServer.GetClassDetails(..ReturnType,.classtype) {
				If $$$UPPER(classtype)="DATATYPE" {
					Set derivedtype=..ReturnType
				}
			}
		}
	}
	; return type is not set so try the origin if this is an override
	If ..ReturnType="",$ISOBJECT(..ClassServer) {
		If ..ClassServer.GetMethodDetails(..This,..ThisMethod,.rettype,.origin) {
			If rettype'="" {
				Set ..ReturnType=rettype
			} Else {
				If origin'="",..ClassServer.GetMethodDetails(origin,..ThisMethod,.rettype) {
					Set ..ReturnType=rettype
				}
			}
		}
	}
	If ..ReturnType="" {
		Do ..AddElementWarning(element,"RTYPE","return type is not set, derived type="_derivedtype)
	} ElseIf  ..FullClassName(..ReturnType)'=..FullClassName(derivedtype) {

		Set fullret=..FullClassName(..ReturnType),fullder=..FullClassName(derivedtype)
		;; special case for %Open etc, same thing happens in ClassDefinitionObject
		;if fullret="%Library.ObjectHandle" set fullret=..This
		If ..IsCompatible(fullret,fullder,.cls,.depth) {
			Do:depth>1 ..AddElementWarning(element,"RTYPE","return type="_fullret_", derived type="_fullder_" but they are compatible via "_cls_" at depth "_depth)
		} Else {
			Do ..AddElementWarning(element,"RTYPE","return type="_fullret_", derived type="_fullder)
		}
	}
	Set ..QuitFound=1
}
$$$DEBUGMethodEnd
Quit ""

$$$DEBUGMethodBegin
Set var=$CHAR($ASCII("%")+1) ; skip over % variables, we don't care if they are used they might be used in deeper, untrackable ways
For  {
	Set var=$ORDER(..VariablesSet(var))
	Quit:var=""
	; if its a parameter variable we count this as being used
	; {*} is special variable that is used on computed fields, ignore those
	If '$DATA(..VariablesUsed(var)),'$DATA(..ParameterVariables(var)),var'="{*}" {
		Set report=1
		If var="SQLCODE" {
			; SQLCODE is a special case, some people check SQLCODE, some check %ROWCOUND
			If $DATA(..VariablesUsed("%ROWCOUNT")) {
				Set report=0
			}
		}
		If report {
			Set vsetE=..VariablesSet(var)
			Do ..AddElementWarning(vsetE,"VUNUSED",var_" Set but not used")
		}
	}
}
$$$DEBUGMethodEnd
Quit ""

$$$DEBUGMethodBegin
/// I am not especially bothered by short or long commands, but they should be consistent
If ..ShortCommand,..LongCommand {
	Do ..AddElementWarning(..ShortCommand,"COMM","Mix of Short and Long commands")
}
$$$DEBUGMethodEnd
Quit ""

$$$DEBUGMethodBegin
/// Non abstract method where there is a return type but no quit to match it
If $$$LOWER(..CodeMode)'="expression",'..ClassIsAbstract,'..MethodIsAbstract,..ReturnType'="",..QuitFound=0 {
	If $$$LOWER(..CodeMode)["generator" {
		Do ..AddElementWarning(..ReturnTypeElement,"RTYPE","GeneratOR method should return %Status, even if the generatED code doesn't.")
	} Else {
		Do ..AddElementWarning(..ReturnTypeElement,"QMISS","No Quit for method that has a ReturnType")
	}
}
$$$DEBUGMethodEnd
Quit ""

UDLText.Content:
/*Method checkCDEFAttributePubliclist(element As PXW.DEV.BNF.Elements.ClassDefinition) As PXW.DEV.BNF.Compilers.elementHandler(Type="AttributePubliclist")
{
	$$$DEBUGMethodBegin
	set ..publicListList=$ListFromString($tr($piece(element.ToString(0),"=",2,*),"()",""))
	$$$DEBUGMethodEnd
	Quit ""
}
*/

Method.Implementation:
	#dim fpE,fparamsE as PXW.DEV.BNF.Elements.COS
	Set type=..FullClassName(StartClassName)
    Set classname=..FullClassName(StartClassName)
    Set objectchain=ParentElement.findFirstElementByType("ObjectChain",0)
	If '$ISOBJECT(objectchain) Set objectchain=ParentElement.findFirstElementByType("ObjectChainNoDot",0)
	Set collection="",elementtype=""
	If ElementTypeClassName'="" Set collection="yes"
	Set loopcount=0
	While $ISOBJECT(objectchain) {
		Set loopcount=loopcount+1
		Set fspecparsed=""
        ; the objectchain has the "." and the name
        Set propertyname=objectchain.ToStringAtomsOnly(0)
		Set propertyname=$SELECT($EXTRACT(propertyname,1)=".":$PIECE(propertyname,".",2),1:propertyname)
		If collection'="",propertyname?0.1"%"1"Get".AN {
			Set collection=""
			If ElementTypeClassName'="" {
				; special case for List.Get methods where we know the element type already
				Set type=ElementTypeClassName
			} Else {
				; or we might be able to derive it
				If ..ClassServer.GetParameterDetails(classname,"ELEMENTTYPE",,,.elementtype) {
					Set type=elementtype
				}
			}
		} Else {
			Set found=..ClassServer.GetPropertyDetails(classname,propertyname,.type,.collection,.ElementTypeClassName)
			If found {
				; we are only interesting in the type/ElementType distinction on a collection
				; where type="%collection.*" and element type is what it is a collection of
				; otherwise we want just what was defined in the class
				If collection="" Set type=ElementTypeClassName
			}
			If 'found {
				Set found=..ClassServer.GetMethodDetails(classname,propertyname,,,.stub)
				If found {
					; 
					If stub'="" {

					} Else {
						Set type=..ClassServer.GetMethodReturnType(classname,propertyname,.fspecparsed,.MYfspec)
						Set collection="",elementtype=""
					}
				}
			} 
			If 'found {
				; once on a dynamic object, stay there
				If $EXTRACT(classname,1,16)="%Library.Dynamic" {
					; check if it could be an array
					;i ..ClassServer.GetMethodDetails("%Library.DynamicArray",propertyname) {
					;	s classname="%Library.DynamicArray"
					;} elseif ..ClassServer.GetMethodDetails("%Library.DynamicObject",propertyname) {
					;	s classname="%Library.DynamicObject"
					;}
					Set type=classname
				}
			}
		}
		Set ..VariablesTypesElement(+objectchain)=type

		If fspecparsed'="" { 
			; if MYfspec exists, this was parsed by from the method definition and may not match the 
			; offical parsed fs

			; Walk through the parameters keeping count as we go.
			; Do not use xpath all the way to byref because that will skip the parameters that are not byref
			; and we won't be able to work out it's position in the formal spec.
			Set fparamlist=""
			Do objectchain.findElementsXPath("FunctionParameterList/FunctionParameter",.fparamlist)
			If fparamlist {
				For count=1:1:fparamlist.Count() {
					Set fpE=fparamlist.GetAt(count)
					Set byrefE=fpE.findFirstElementByType("ByrefVariable",0)
					If byrefE {
						Set var=byrefE.ToString(0)
						If var'="" {
							Set fsitem=$LISTGET(MYfspec,count)
							If fsitem="" Set fsitem=$LISTGET(fspecparsed,count)
							Set btype=$LISTGET(fsitem,2)
							If btype'="" {
								Set et=""
								; look to see if there is an element type parameter
								For i=5:2:$LISTLENGTH(fsitem) {
									Set pname=$LISTGET(fsitem,i)
									Set pvalue=$LISTGET(fsitem,i+1)
									If pname="ELEMENTTYPE" Set et=pvalue
								}
								Do ..checkAndRecordVariableType(byrefE,var,btype,et)
							}
						}
					}
				}
			} Else {
				;Do ..AddElementWarning(objectchain,"Looks like a method "_$GET(classname)_"."_$GET(propertyname)_" but no parameter list found")
				; Thats fine, eg %New() does not have parameter list
			}
		}			

        Set objectchain=objectchain.findFirstElementByType("ObjectChain",0)
        Set classname=type
    }
	Quit type

#dim element,functionE as PXW.DEV.BNF.Elements.COS
#dim nameA,specialA as PXW.DEV.Atom

; some kind of set with indirection so type cannot be derived
; S @x
If '$ISOBJECT(ValueElement) Quit ""
If 'ValueElement.IsElement Quit ""


If ValueElement.type="Expression" {
	Set expression=ValueElement
} Else {
	Set expression=ValueElement.findFirstElementByType("Expression",0)
}

// If we call from a DO then there is no expression
If $ISOBJECT(expression),expression.type="Expression" {
	Set simple=..SimplifyExpression(expression,.variableElement)
	If simple'="-" Quit $SELECT(simple="""""":"-null-",1:"%Library.DataType") ; it's null or a number or string
} Else {
	Set variableElement=ValueElement
}

If '$ISOBJECT(variableElement) Quit "" ; its something else we cannot deal with

Set finaltype=""
; some macros we know $$$OK, $$$ERROR
If variableElement.type="Macrocall" {
	Set nameA=variableElement.partsGetAt(2) ; second atom is the name
	If $ISOBJECT(nameA) {
		Set name=nameA.value
		If (name="OK") || (name="ERROR") {
			Set finaltype="%Library.Status"
		} ElseIf (name="NULLOREF") {
			Set finaltype="-null-"
		}
	}
} ElseIf variableElement.type="CosJson" {
	; s x={}
	Set objE=variableElement.findFirstElementByType("CosJsonObject",0)
	If $ISOBJECT(objE) {
		Set finaltype="%Library.DynamicObject"
	} Else {
		; s x=[]
		Set arrE=variableElement.findFirstElementByType("CosJsonArray",0)
		If $ISOBJECT(arrE) {
			Set finaltype="%Library.DynamicArray"
		}
	}
} ElseIf variableElement.type="Classexpr" {
	; looking for ##class
	Set hhclass=variableElement.findFirstElementByType("ClassExpression",0)
	If $ISOBJECT(hhclass) {
		Set classnameele=hhclass.findFirstElementByType("ClassReference",0)
		Set classname=classnameele.ToString(0)
		Set finaltype=..FollowObjectChainForType(hhclass,classname)
	} Else {
		Set super=variableElement.findFirstElementByType("SuperExpression",0)
		; ##super()
		If $ISOBJECT(super) {
			Set superclass=..ClassServer.GetMethodOverrides(..This_"||"_..ThisMethod)
			If superclass'="" {
				Set type=..ClassServer.GetMethodReturnType(superclass,..ThisMethod)
				Set finaltype=..FollowObjectChainForType(super,type)
			}
		}
	}
} ElseIf (variableElement.type="Variable") {
	; looking for variable eg obj.property
	Set finaltype=""
	Set variablename=variableElement.ToStringAtomsOnly(0)
	; when working out a type use the #DIM type if there is one
	; possible that name cannot be determined at this point eg {*}
	If variablename'="" {
		Set classname=$GET(..DimmedTypes(variablename))
		Set elementtype=$GET(..DimmedTypes(variablename,"ELEMENTTYPE"))
		If elementtype="" Set elementtype=$GET(..ListVarElementType(variablename))
		If classname="" Set classname=$GET(..VariablesTypes(variablename))
		If classname'=""	Set finaltype=..FollowObjectChainForType(variableElement,classname,elementtype)
	}
} ElseIf (variableElement.type="VariableSet") {
	; looking for variable eg obj.property
	Set finaltype=""
	Set variablename=variableElement.ToStringAtomsOnly(0)
	; when working out a type use the #DIM type if there is one
	; possible that name cannot be determined at this point eg {*}
	If variablename'="" {
		Set classname=$GET(..DimmedTypes(variablename))
		Set elementtype=$GET(..DimmedTypes(variablename,"ELEMENTTYPE"))
		If elementtype="" Set elementtype=$GET(..ListVarElementType(variablename))
		If classname="" Set classname=$GET(..VariablesTypes(variablename))
		If classname'=""	Set finaltype=..FollowObjectChainForType(variableElement,classname,elementtype)
	}
} ElseIf (variableElement.type="ObjectVariable") {
	; looking for variable eg obj.property
	Set finaltype=""
	Set variablename=variableElement.ToStringAtomsOnly(0)
	; when working out a type use the #DIM type if there is one
	; possible that name cannot be determined at this point eg {*}
	If variablename'="" {
		Set classname=$GET(..DimmedTypes(variablename))
		Set elementtype=$GET(..DimmedTypes(variablename,"ELEMENTTYPE"))
		If elementtype="" Set elementtype=$GET(..ListVarElementType(variablename))
		If classname="" Set classname=$GET(..VariablesTypes(variablename))
		If classname'=""	Set finaltype=..FollowObjectChainForType(variableElement,classname,elementtype)
	}
} ElseIf variableElement.type="ThisObject" {
	; this is not quite right but expressions are sooo complicated, need a generic
	; get "first thing in expression" method
	Set thisobjectselfE=variableElement.findFirstElementByType("ThisObjectSelf",0)
	; otherwise its ..property
	If $ISOBJECT(thisobjectselfE) {
		Set finaltype=..FollowObjectChainForType(thisobjectselfE,..This)
	} Else {
		; check for $this.property
		Set thisobjectthisE=variableElement.findFirstElementByType("ThisObjectThis",0)
		If $ISOBJECT(thisobjectthisE) {
			Set finaltype=..FollowObjectChainForType(thisobjectthisE,..This)
		}
	}
} ElseIf variableElement.type="ThisObjectSet" {
	; this is not quite right but expressions are sooo complicated, need a generic
	; get "first thing in expression" method
	Set thisobjectselfE=variableElement.findFirstElementByType("ThisObjectSelf",0)
	; otherwise its ..property
	If $ISOBJECT(thisobjectselfE) {
		Set finaltype=..FollowObjectChainForType(thisobjectselfE,..This)
	} Else {
		; check for $this.property
		Set thisobjectthisE=variableElement.findFirstElementByType("ThisObjectThis",0)
		If $ISOBJECT(thisobjectthisE) {
			Set finaltype=..FollowObjectChainForType(thisobjectthisE,..This)
		}
	}
} ElseIf variableElement.type="Intrinsicfncall" {
	Set specialE=variableElement.findFirstElementByType("SpecialIntrinsic",0)
	If $ISOBJECT(specialE) {
		Set functionE=specialE.partsGetAt(1)
		If $ISOBJECT(functionE) {
			If functionE.type="SelectFunctionCall" {
				Set finaltype=..DeriveTypeReturnedSelect(functionE)
			} ElseIf functionE.type="GetFunctionCall" {
				Set getExpE=functionE.findFirstElementByType("GetExpression",0)
				If $ISOBJECT(getExpE) {
					Set finaltype=..DeriveTypeReturned(getExpE)
				}
			}
		}
	}
} ElseIf variableElement.type="SpecialVariable" {
	Set specialElement=variableElement.findFirstElementByType("SpecialSystem",0) 
	If $ISOBJECT(specialElement) {
		Set classname="%SYSTEM"
		Set key="" 
		For  {
			Set specialA=specialElement.partsGetNext(.key)
			Quit:key=""
			If $PIECE(specialA.type,":",1)="ObjectMemberIdentifier" {
				Set classname=classname_"."_specialA.value
			} 
		}
		Set finaltype=..FollowObjectChainForType(specialElement,classname)
	}
}

Quit finaltype

Do Element.findElementsXPath("SelectClauseList/SelectClause/SelectClauseValue",.list)
Set finaltype=""
If $ISOBJECT($GET(list)) {
	Set finaltype=..DeriveTypeFromList(list)
}
Quit finaltype

Set finaltype=""
For i=1:1:list.Count() {
	Set valueE=list.GetAt(i)
	If $ISOBJECT(valueE) {
		Set type=..DeriveTypeReturned(valueE)
		If type'="" {
			If finaltype="" {
				Set finaltype=type
			} Else {
				Set compatible=..IsCompatible(finaltype,type,.common,.depth)
				If compatible {
					If common'="",common'="-datatype-" {
						Set finaltype=common
					}
				} Else {
					If common'="",common'="-datatype-" {
						Set finaltype=common
					}
				}
			}
		}
	}
}
Quit finaltype

If name="" Quit ""
If name="-null-" Quit name
If name="-datatype-" Quit name
If $ISOBJECT(..ClassServer) {
	Set package=$PIECE(..This,".",1,*-1)
	Set fullname=..ClassServer.FullClassName(name,package)
} Else {
	Set fullname=name
}

Quit fullname

Set simple=""
If (element.type="SubscriptParameterList") || (element.type="ArrayParameterList") {
	Set sep=""
	For i=1:1:element.partsCount() {
		Set exp=element.partsGetAt(i)
		If $ISOBJECT(exp),exp.type="Expression" {
			Set type=..SimplifyExpression(exp)
			Set simple=simple_sep_type,sep=":"
		}
	}

}
Quit simple

	#dim partE,factorE,primaryE,finalE,expressionE as PXW.DEV.BNF.Elements.COS
	Set stringElement=##class(PXW.DEV.Element).%New()
	If '$ISOBJECT(ValueElement) Quit ""
	If ValueElement.type="Expression" {
		Set expressionE=ValueElement
	} Else {
		Set expressionE=ValueElement.findFirstElementByType("Expression",0)
	}

	; sql_"Select * from table where x="_xx_" and y=2"      as an expression looks like this:
    ;Element=Expression PXW.DEV.BNF.Elements.COS @8724
    ;.Element=Factor PXW.DEV.BNF.Elements.COS @8640
    ;..Element=Primary PXW.DEV.BNF.Elements.COS @8256
    ;...Element=Variable PXW.DEV.BNF.Elements.COS @8916
    ;....type=Variable:/Expression/Factor/Primary/Variable
    ;.... sql
    ;.Element=Dyadicop PXW.DEV.BNF.Elements.COS @8939
    ;..type=punctuation:/Expression/Dyadicop
    ;.. _
    ;.Element=Factor PXW.DEV.BNF.Elements.COS @8410
    ;..Element=Primary PXW.DEV.BNF.Elements.COS @8273
    ;...Element=String PXW.DEV.BNF.Elements.COS @8784
    ;....type=String:/Expression/Factor/Primary
    ;.... "Select * from table where x="
    ;.Element=Dyadicop PXW.DEV.BNF.Elements.COS @8356
    ;..type=punctuation:/Expression/Dyadicop
    ;.. _
    ;.Element=Factor PXW.DEV.BNF.Elements.COS @9127
    ;..Element=Primary PXW.DEV.BNF.Elements.COS @8928
    ;...Element=Variable PXW.DEV.BNF.Elements.COS @8435
    ;....type=Variable:/Expression/Factor/Primary/Variable
    ;.... xx
    ;.Element=Dyadicop PXW.DEV.BNF.Elements.COS @8258
    ;..type=punctuation:/Expression/Dyadicop
    ;.. _
    ;.Element=Factor PXW.DEV.BNF.Elements.COS @8498
    ;..Element=Primary PXW.DEV.BNF.Elements.COS @8806
    ;...Element=String PXW.DEV.BNF.Elements.COS @8654
    ;....type=String:/Expression/Factor/Primary
    ;.... " and y=2"	

	Set string="",isString=1
	For i=1:1:expressionE.partsCount() {
		Set partE=expressionE.partsGetAt(i)
		If $ISOBJECT(partE) {
			If partE.type="Factor" {
				Set factorE=partE
				Set primaryE=factorE.partsGetAt(1)
				If $ISOBJECT(primaryE),primaryE.type="Primary" {
					Set finalE=primaryE.partsGetAt(1)
					If $ISOBJECT(finalE) {
						Set atom=finalE.FirstAtom()
						Set newatom=atom.%ConstructClone(0)
						Set newatom.start=""
						Set newatom.end=""
						Set newatom.type="String"
						If finalE.type="String" {
							Set newatom.value=$REPLACE(atom.value,"""""","""") ; store without encode quotes
							Set string=string_newatom.value
							Do stringElement.AddPart(newatom)
						} ElseIf finalE.type="Number" {
							Set string=string_atom.value
							Do stringElement.AddPart(newatom)
						} ElseIf finalE.type="SubExpression" {
							Set string=string_"?"
							Set newatom.value="?"
							Do stringElement.AddPart(newatom)
						} ElseIf finalE.type="Variable" {
							Set varname=atom.value
							Set string=string_$GET(..stringVars(varname))
							Set varElem=$GET(..stringVars(varname,"element"))
							Do:$ISOBJECT(varElem) stringElement.partsCopy(varElem)	
						} Else {
							If finalE.type="Intrinsicfncall" {
								Set char=$$$UPPER(finalE.ToString(0))
								If $EXTRACT(char,1,2)="$C" {
									; this is a $C() so do nothing
								} Else {
									Set string=string_"?"
									Set newatom.value="?"
									Do stringElement.AddPart(newatom)
								}
							} Else {
								Set string=string_"?"
								Set newatom.value="?"
								Do stringElement.AddPart(newatom)
							}
						}
					}
				} Else {
					Set isString=0 ; not primary thing
				}
			} ElseIf partE.type="Dyadicop",partE.ToString(0)="_" {
				; concat is ok
			} Else {
				Set isString=0
			}			
		}
	}
	If isString=0 Set string=""
	If string="?" Set string=""
	Quit string

	#dim a as PXW.DEV.Atom

    If element.type="Param" {
        Set param=element.ToString(0)
        If param'="" Set ..ParameterVariables(param)=1
    }

	Set allAtOnce=1
	If allAtOnce {
		Set akey=""
		For  {
			Set a=element.partsGetNext(.akey)
			Quit:akey=""

			If a.IsElement {
				Do ..checkElement(a)
			} 
		}
	}

If element.type="QuerySpecification" {
    Do ..SqlProgramCheck(element)
}
If element.type="WithCommand" {
    Do ..WithCommand(element)
}
If element.type="SelectCommand" {
    Do ..SelectCommand(element)
}
If element.type="InsertCommand" {
    Do ..InsertCommand(element)
}
If element.type="UpdateCommand" {
    Do ..UpdateCommand(element)
}
If element.type="DeleteCommand" {
    Do ..DeleteCommand(element)
}

    #dim a as PXW.DEV.Atom
    If element.type="WithCommand" {
        Do ..WithCommand(element)
    }
    If element.type="SelectCommand" {
        Set sqlanalyse=..%New(..ClassServer)
        Set sqlanalyse.This=..This
        Merge sqlanalyse.withReferences=..withReferences
        if $isobject(parentAnalyse) merge sqlanalyse.parentTableNames=parentAnalyse.tableNames
        Do sqlanalyse.checkElement(element)
        Set ..SelectCommandAnalysis(+element)=sqlanalyse
        set parentAnalyse=sqlanalyse
    }
    Set akey=""
	For  {
		Set part=element.partsGetNext(.akey)
		Quit:akey=""

	    If part.IsElement {
			Do ..SqlProgramCheck(part,parentAnalyse)
		} ElseIf part.IsAtom {
            ;
		}
	}

#dim from as PXW.DEV.Element
Set from=""
Set tableexpE=element.findFirstElementByType("TableExpression",0)
If $ISOBJECT(tableexpE) {
    Set from=tableexpE.findFirstElementByType("FromClause",0)
}
If $ISOBJECT(from) {
    Do ..findElementsByTypeNoSubQueries(from,"TableReference",.tableelements)
    Do ..findElementsByTypeNoSubQueries(from,"Join",.joins)
    If $ISOBJECT($GET(joins)) {
        For ji=1:1:joins.Count() {
            Do ..findElementsByTypeNoSubQueries(joins.GetAt(ji),"TableReference",.tableelements)
        }
    }
    If $ISOBJECT($GET(tableelements)) {
        For ti=1:1:tableelements.Count() {
            Set tablename="",tablealias=" "
            Set tref=tableelements.GetAt(ti)
            Set tablenameE=tref.findFirstElementByType("TableName")
            If $ISOBJECT(tablenameE) Set tablename=tablenameE.ToString(0)
            Set tablealiasE=tref.findFirstElementByType("AliasName")
            If $ISOBJECT(tablealiasE) Set tablealias=tablealiasE.ToString(0)
            Set tables(tablealias)=tablename
            Set ..tableReferences(tablealias)=tref
            Set ..tableNames(tablealias)=tablename
        }
    }

    ; Work out all the column references and which tables they are on.
    ; This includes all the joins and where clauses etc
    ; eg SELECT col1,col2,col1+col2 as total FROM table WHERE col3=1
    ; will index col1,col2 and col3, with col1 and col2 referenced several times
    Do ..findElementsByTypeNoSubQueries(element,"ColumnReference",.columnelements)
    If $ISOBJECT($GET(columnelements)) {
        For ci=1:1:columnelements.Count() {
            Set columnname="",tablealias="",columnjoin=""
            Set cref=columnelements.GetAt(ci)
            Set fulltable=..FindTable(cref,.tables)
            Set columnnameE=cref.findFirstElementByType("ColumnName",0)
            If $ISOBJECT(columnnameE) Set columnname=columnnameE.ToString(0)
            Set columnjoinE=cref.findFirstElementByType("ColumnReferenceImplicit",0)
            If $ISOBJECT(columnjoinE) Set columnjoin=columnjoinE.ToString(0)

            ; wrap the entire column up as a single thing and work out later what 
            ; it refers to if its clicked on. EG Race->Circuit->Name
            If fulltable'="" {
                Do ..SetColumnReference(cref,fulltable,columnname_columnjoin)
            } Else {
                Do ..SetColumnReference(cref,"",columnname_columnjoin)                        
            }
        }
    }

    ; Work out all the column references and which tables they are on.
    ; This includes all the joins and where clauses etc
    ; eg SELECT col1,col2,col1+col2 as total FROM table WHERE col3=1
    ; will index col1,col2,total with col1 and col2 having information about which table they relate to.
    Do ..findElementsByTypeNoSubQueries(element,"DerivedColumn",.derivedColumns)
    If $ISOBJECT($GET(derivedColumns)) {
        For ci=1:1:derivedColumns.Count() {
            Set colE=derivedColumns.GetAt(ci)
            Set colname="unknown"_ci
            Do ..GetDerivedColumnInfo(colE,.colname,.cref)
            Set fulltable=..FindTable(cref,.tables)
            Set ..SelectedColumnsByName(colname)=fulltable
        }
    }
}

Set ColName="unknown"
Set ColumnReference=""
; if the column is just a reference to another column
Do DerivedColumn.findElementsByType("ColumnReference",.colrefs,2)
If $ISOBJECT($GET(colrefs)),colrefs.Count()=1 {
    Set ColumnReference=colrefs.GetAt(1)
    Set colnameE=colrefs.GetAt(1).findFirstElementByType("ColumnName",0)
    If $ISOBJECT(colnameE) {
        Set ColName=$$$UPPER(colnameE.ToString(0))
    }
}

Set asclause=DerivedColumn.findFirstElementByType("AsClause",0)
If $ISOBJECT(asclause) {
    Set colnameE=asclause.findFirstElementByType("ColumnName",0)
    If $ISOBJECT(colnameE) {
        Set ColName=$$$UPPER(colnameE.ToString(0))
    }
} 
; remove quotes surrounding any names
Set ColName=$TRANSLATE(ColName,"""","")

#dim from as PXW.DEV.Element
Set tableE=element.findFirstElementByType("DirectTable",0)
If $ISOBJECT(tableE) {
    Set tablenameE=tableE.findFirstElementByType("TableName",0)
    Set table=tablenameE.ToString(0)
    Do element.findElementsXPath("InsertMethod/InsertValuesList/UpdateColumns/ColumnName",.columnelements)
    Do element.findElementsXPath("InsertMethod/InsertMultirow/UpdateColumns/ColumnName",.columnelements)
    If $ISOBJECT($GET(columnelements)) {
        For ci=1:1:columnelements.Count() {
            Set columnnameE=columnelements.GetAt(ci)
            Set columnname=columnnameE.ToString(0)
            Set fulltable=$SELECT($ISOBJECT(..ClassServer):..ClassServer.GetFullTableName(table,..This),1:table)
            Do ..SetColumnReference(columnnameE,fulltable,columnname,ci)

        }
    }
}

#dim from as PXW.DEV.Element
Set tableE=element.findFirstElementByType("DirectTable",0)
If $ISOBJECT(tableE) {
    Set tablenameE=tableE.findFirstElementByType("TableName",0)
    Set table=tablenameE.ToString(0)
    Do element.findElementsXPath("UpdateSet/ColumnReference/ColumnName",.columnelements)
    Set whereE=element.findFirstElementByType("WhereClause")
    If $ISOBJECT(whereE) {
        Do ..findElementsByTypeNoSubQueries(whereE,"ColumnName",.columnelements)
    }
    If $ISOBJECT($GET(columnelements)) {
        For ci=1:1:columnelements.Count() {
            Set columnnameE=columnelements.GetAt(ci)
            Set columnname=columnnameE.ToString(0)
            Set fulltable=$SELECT($ISOBJECT(..ClassServer):..ClassServer.GetFullTableName(table,..This),1:table)
            Do ..SetColumnReference(columnnameE,fulltable,columnname)              
        }
    }
}

#dim from as PXW.DEV.Element
Set tableE=element.findFirstElementByType("DirectTable",0)
If $ISOBJECT(tableE) {
    Set table=tableE.ToString(0)
    Do ..findElementsByTypeNoSubQueries(element,"ColumnName",.columnelements)
    If $ISOBJECT($GET(columnelements)) {
        For ci=1:1:columnelements.Count() {
            Set columnnameE=columnelements.GetAt(ci)
            Set columnname=columnnameE.ToString(0)
            Set fulltable=..ClassServer.GetFullTableName(table,..This)
            Do ..SetColumnReference(columnnameE,fulltable,columnname)          
        }
    }
}

    #dim ele as PXW.DEV.Element
    If Object.type=Type {
        If '$ISOBJECT($GET(OutputList)) { 
            Set OutputList=##class(%Library.ListOfObjects).%New()
        }
        Do OutputList.Insert(Object)				
    }
	For i=1:1:Object.partsCount() {
		Set ele=Object.partsGetAt(i)
		If ele.IsElement {
            Set derived=ele.findFirstElementByType("DerivedTable",0)
            Set subquery=ele.findFirstElementByType("SubquerySpecification",0)
			If $ISOBJECT(derived) || $ISOBJECT(subquery) {
				; do nothing for select
			} Else {
				Do ..findElementsByTypeNoSubQueries(ele,Type,.OutputList)
			}
		}
	}

If '$ISOBJECT(cref) Quit ""
Set table=..FindTableSub(cref,.tables)
If table="" {
    ; Here we are dealing with a query like this:
    ; SELECT res.Code ,
    ;        (select Code from f1_data.race where id=res.Race)
    ; FROM f1_data.result as res
    ; 
    ; this makes sure res.Race is identified correctly       
    Merge parenttables=..parentTableNames
    If $DATA(parenttables)=10 {
        Set table=..FindTableSub(cref,.parenttables)
    }
}
Quit table

Set columnname="",tablealias=""
Set tablealiasE=cref.findFirstElementByType("AliasName")
If $ISOBJECT(tablealiasE) Set tablealias=tablealiasE.ToString(0)
Set columnnameE=cref.findFirstElementByType("ColumnName",0)
If $ISOBJECT(columnnameE) Set columnname=columnnameE.ToString(0)

; if there is no alias and there is 1 table only then we can use that as the alias
; note than on SUB SELECTS the parent tables are available.
If tablealias="",$ORDER(tables(""))=$ORDER(tables(""),-1) {
    Set a2=$ORDER(tables(""),1,table) 
    ; confirme that this is a valid alias
    ; eg on a column that has a subquery it might be refering to something in the parent
    ; note that when there is just 1 table in the query * means all columns in that table so its a valid fieldname
    If a2'="",$ISOBJECT(..ClassServer){
        if columnname="*" {
            set tablealias=a2
        } else {
            Set class=..ClassServer.GetClassNameFromTableName(table,..This)   
            Set pname=..ClassServer.GetPropertyNameSQL(class,columnname)
            If pname'="" {
                Set tablealias=a2
            }     
        }       
    } 
}

; if still not found then try all the tables looking for one that has this field
; note the array will have " " as the first key, which means if this is a sub select then likely the first one will be the current table
; this solves solves the issue of sql like this:
; SELECT res.Code ,
;        (select Code from f1_data.race where id=res.Race)
; FROM f1_data.result as res
; we want the Code on the sub select to be from RACE rather than the parent "res"
;w !,"tabelalias="_tablealias_",columnname="_columnname_", coltext="_cref.ToString(0)
If tablealias="" {
    Set a2=""
    For  {
        Set a2=$ORDER(tables(a2))
        Quit:a2=""
        ;s class=$g(tables($$$UPPER(a2)))
        Set table=$GET(tables(a2))
        If table'="",$ISOBJECT(..ClassServer) {
            Set class=..ClassServer.GetClassNameFromTableName(table,..This)   
            Set pname=..ClassServer.GetPropertyNameSQL(class,columnname)
            If pname'="" {
                Set tablealias=a2
                Quit  
            }
        }
    }
}

Set fulltable=""
If tablealias'="" {
    Set fulltable=$GET(tables(tablealias))
    If fulltable="" {
        ; table not found by looking up the alias so maybe the alias is the table name:
        ; SELECT race.* FROM f1_data.race
        Set ta=""
        For  {
            Set ta=$ORDER(tables(ta),1,ft)
            Quit:ta=""

            If $PIECE(ft,".",*)=tablealias {
                Set fulltable=ft
                Set:$ISOBJECT(..ClassServer) fulltable=..ClassServer.GetFullTableName(fulltable,..This)
            }
        }
    } Else {
         If '$DATA(..withReferences(fulltable)) {
            Set:$ISOBJECT(..ClassServer) fulltable=..ClassServer.GetFullTableName(fulltable,..This)
        }
     }
}
Quit fulltable

#dim a as PXW.DEV.Atom

Do ..processSpecificElement(element,"PRE")

Set akey=""
For  {
	Set part=element.partsGetNext(.akey)
	Quit:akey=""

	If part.IsElement {
		Do ..checkElement(part)
	} 
}
Do ..processSpecificElement(element,"POST")

    Set sc=$$$OK 
    Set codetypes=..#CodeType
    If codetypes'="" {
		For i=1:1:$LENGTH(codetypes,",") {
			Set codetype=$PIECE(codetypes,",",i)
			Set:$$$ISOK(sc) sc=##class(PXW.DEV.Dictionary.CodeTypeIndex).RegisterType("Analyse:"_..#Language,codetype,..%ClassName(1))
		}
    }
    Quit sc

    #dim o as PXW.DEV.Atom

    $$$DEBUGMethodBegin
    Do:..needsWScheck ..skipWhiteSpaceAndComments()

	;$$$BNFPATH
	;;$$$DEBUG("%path="_%path)
    Set ok=1
    Set openquote=..peek(1)
    If openquote'="""",openquote'="'" {
        Set ok=0
    }

    If ok {
        $$$BNFSTART(subElement)

        Set start=..next()
        Set n=""
        Set instring=1
        While '..eof() && instring {
            Set chs=..peek(2)
            Set ch=$EXTRACT(chs,1),ch2=$EXTRACT(chs,2)
            ; embedded quotes or end of string?
            ; I am not sure how these get encoded so sticking with COS "" for quotes in quotes
            If ch=openquote {
                If ch2=openquote {
                    Set n=n_..next()_..next()
                } Else {
                    Set instring=0
                    Set end=..next()
                }
            } Else {
                Set n=n_..next()
            }
        }
        Set o=..newAtom("String",n)
        Set o.start=start,o.end=end
        Do subElement.AddPart(o)
        $$$BNFCOMMIT(subElement,ParentElement)
    }
    $$$DEBUGMethodEnd
    Quit ok

If ..isStringSingle("::=",.value)=0 Quit 0 ; q1 
$$$DEBUGMethodBegin
$$$BNFPATH
$$$BNFSTART(subElement)
Set done=0 ; t1 
; type=group, check=if, skip=1, skipall=1
Set getVal=..nextNotEOL($LENGTH(value)),atom=..newAtom(..#keywordAtomType,getVal) ; k1 
Do subElement.AddPart(atom) ; t3 
If 1	 {
	Set done=1 ; u1 

}
If done {
	$$$BNFCOMMIT(subElement,ParentElement)
	Set ok=1
} Else {
	$$$BNFROLLBACK(subElement)
	Set ok=0
}
$$$DEBUGMethodEnd
Quit ok

	; rules summary C&C&C
	$$$DEBUGMethodBegin
	$$$BNFPATH
	$$$BNFSTART(subElement)
	Set done=0 ; method start
	If ..Identifier(subElement,.addedElement)  {
		If ..Equals(subElement,.addedElement)  {
			If ..Rules(subElement,.addedElement)  {
				Set done=1 ; end compileRules
			}
		}
	}
	If done {
		$$$BNFCOMMIT(subElement,ParentElement)
		Set ok=1
	} Else {
		$$$BNFROLLBACK(subElement)
		Set ok=0 ; normal rollback
	}

    ;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
    If ok=0 {
        Set ok=..recover(ParentElement,.recSub,"",$LISTBUILD($CHAR(13)))
    }

	$$$DEBUGMethodEnd
	Quit ok

UDLText.Content:
/* 

    DIRECTLY COPIED METHODS 

*/

Method.Implementation:
; rules summary (?4?)*
$$$DEBUGMethodBegin
$$$BNFPATH
$$$BNFSTART(subElement)
Set done=0 ; method start
If ..File1RepZero(subElement,.addedElement)  {
	Set done=1 ; end compileRules
}
If done {
	$$$BNFCOMMIT(subElement,ParentElement)
	Set ok=1
} Else {
	$$$BNFROLLBACK(subElement)
	Set ok=0 ; normal rollback
}
$$$DEBUGMethodEnd
Quit ok

; rules summary ?4?
Set subElement=ParentElement
Set done=0 ; method start
While ..Definition(subElement,.addedElement)  {
	Set done=1
}
If done {
	Set ok=1
} Else {
	Set ok=1 /* nothing found is ok in RZ */
}
Quit ok

; rules summary P&C
; first rule summary P
If '(..isStringSingle("&",.value)) { Quit 0 /* normal */ }
$$$DEBUGMethodBegin
$$$BNFPATH
$$$BNFSTART(subElement)
Set done=0 ; method start
If ..addPunctuation(subElement,"&")  {
	If ..LookAheadRule(subElement,.addedElement)  {
		Set done=1 ; end compileRules
	}
}
If done {
	$$$BNFCOMMIT(subElement,ParentElement)
	Set ok=1
} Else {
	$$$BNFROLLBACK(subElement)
	Set ok=0 ; normal rollback
}
$$$DEBUGMethodEnd
Quit ok

; rules summary C|C|C
$$$DEBUGMethodBegin
$$$BNFPATH
$$$BNFSTART(subElement)
Set done=0 ; method start
If ..Keyword(subElement,.addedElement)  {
	Set done=1 ; or
} ElseIf ..Subrule(subElement,.addedElement)  {
	Set done=1 ; or
} ElseIf ..Call(subElement,.addedElement)  {
	Set done=1 ; end compileRules
}
If done {
	$$$BNFCOMMIT(subElement,ParentElement)
	Set ok=1
} Else {
	$$$BNFROLLBACK(subElement)
	Set ok=0 ; normal rollback
}
$$$DEBUGMethodEnd
Quit ok

; rules summary P&C
; first rule summary P
If '(..isStringSingle("!",.value)) { Quit 0 /* normal */ }
$$$DEBUGMethodBegin
$$$BNFPATH
$$$BNFSTART(subElement)
Set done=0 ; method start
If ..addPunctuation(subElement,"!")  {
	If ..NotableRule(subElement,.addedElement)  {
		Set done=1 ; end compileRules
	}
}
If done {
	$$$BNFCOMMIT(subElement,ParentElement)
	Set ok=1
} Else {
	$$$BNFROLLBACK(subElement)
	Set ok=0 ; normal rollback
}
$$$DEBUGMethodEnd
Quit ok

; rules summary C|C|C
$$$DEBUGMethodBegin
$$$BNFPATH
$$$BNFSTART(subElement)
Set done=0 ; method start
If ..Keyword(subElement,.addedElement)  {
	Set done=1 ; or
} ElseIf ..Subrule(subElement,.addedElement)  {
	Set done=1 ; or
} ElseIf ..Call(subElement,.addedElement)  {
