Export.Routine:
/// Write to the given method
#define WRITENOLINE(%method,%code) d %method.Implementation.Write(%code)

#define WRITELINE(%method,%code) d %method.Implementation.WriteLine(%code)

/// Create some tabs
#define Tab(%n) $e($c(9,9,9,9,9,9,9,9,9,9,9,9,9,9,9,9,9,9,9,9,9,9,9,9,9,9,9,9,9,9,9,9),1,%n)

/// curly bracket in quotes messes up VSCode
#define OpenCurly $c(123)

/// curly bracket in quotes messes up VSCode
#define CloseCurly $c(125)

Method.Implementation:
Set genclass=$GET(params("GenerateTo"),"UNDEF")
If genclass="UNDEF" Quit $$$ERROR(5001,"GenerateTo parameter is not set")

If genclass'="UNDEF" {
    If genclass'="" {
        If '$GET(^PXW.DEV.BNF("AUTOCOMPILE")) {
            Write !,"AUTOCOMPILE is OFF, Set sc=##class(PXW.DEV.BNF.Compilers.Compiler).goload("""_cls_""","""_genclass_""") " ;  manually"
            Set sc=$$$OK
        } Else {
            Set sc=##class(PXW.DEV.BNF.Compilers.Compiler).goload(cls,genclass)
        }
    } Else {
        Set sc=$$$OK
    }
}
Quit sc

