Export.Routine:
#; 
/// Get number of parts on the element.
#define ElementPartsCount(%e) $GET(%PXWparts(+%e))
#define ElementPartsCountInternal(%e) $GET(%PXWparts(+%e))

/// Check if there are any parts
#define ElementPartsExist(%e) $Data(%PXWparts(+%e))
#define ElementPartsExistInternal(%e) $Data(%PXWparts(+%e))


/// Get a specific part of an element
#define ElementPartsGetAt(%e,%n) $GET(%PXWparts(+%e,%n))
#define ElementPartsGetAtInternal(%e,%n) $GET(%PXWparts(+%e,%n))

/// 
#define ElementIsObject(%e) %e

/// Get the next element
#define ElementPartsNext(%e,%n,%d) $ORDER(%PXWparts(+%e,%n),1,%d)
#define ElementPartsNextInternal(%e,%n,%d) $ORDER(%PXWparts(+%e,%n),1,%d)

///
#define ELEMENTPARTADD(%e,%p) Set %PXWparts(+%e,$INCREMENT(%PXWparts(+%e)))=%p
#define ELEMENTPARTADDInternal(%e,%p) Set %PXWparts(+%e,$INCREMENT(%PXWparts(+%e)))=%p

#define ELEMENTPARTCOPY(%e,%src) Set src=+%src,this=+%e,c2=$GET(%PXWparts(this)) For i=1:1:%PXWparts(src) { Set %PXWparts(this,$INCREMENT(c2))=%PXWparts(src,i) } Set %PXWparts(this)=c2
#define ELEMENTPARTCOPYInternal(%e,%src) Set src=+%src,this=+%e,c2=$GET(%PXWparts(this)) For i=1:1:%PXWparts(src) { Set %PXWparts(this,$INCREMENT(c2))=%PXWparts(src,i) } Set %PXWparts(this)=c2

Method.Implementation:
    set akey=""
 	For  {
		Set part=element.partsGetNext(.akey)
		Quit:akey=""

	    If part.IsElement {
			Do ..resetAll(part)
		} ElseIf part.IsAtom {
            Set type=$$$UPPER($PIECE(part.type,":",1))
            ; this is the word "method" or "property" etc
            If type="KEYWORD" {
            }
            Do ..resetWhitespace(part)
		}
	}

If $ISOBJECT(Atom.whitespace) {
    If Atom.whitespace.value'="" {
        Set Atom.whitespace.value=" "
    }
    Do ..resetWhitespace(Atom.whitespace)
}

    #dim atom as PXW.DEV.Atom

    ;s type=element.type
    ;zw type,flags
    If element.type="XmlStartTag" {
        Do ..setWhitespaceNewLineElement(element,..indent)
        Set ..indent=..indent+1 
        set ..flags=""
    } elseIf element.type="XmlEndTag" {
        Set ..indent=..indent-1
        if ..flags="XmlContent" {
            ; the last thing was content so stay on same line
        } else {
            Do ..setWhitespaceNewLineElement(element,..indent)
        }
        set ..flags=""
   } elseif element.type="XmlContent" {
        set ..flags=element.type
    }


    set akey=""
   	For  {
		Set atom=element.partsGetNext(.akey)
		Quit:akey=""

	    If atom.IsElement {
			Do ..setAll(atom)
		} else {
            set atom.line=..currentLine
        }
	}

    set akey=""
 	For  {
		Set a=element.partsGetNext(.akey)
		Quit:akey=""

	    If a.IsElement {
			Do ..resetAll(a)
		} ElseIf a.IsAtom {
            Set type=$$$UPPER($PIECE(a.type,":",1))
            ; this is the word "method" or "property" etc
            If type="KEYWORD" {
            }
            Do ..resetWhitespace(a)     
		}
	}

If $ISOBJECT(Atom.whitespace) {
    If Atom.whitespace.value'="" {
        Set Atom.whitespace.value=" "
    }
    Do ..resetWhitespace(Atom.whitespace)
}

    If element.type="SelectCommand" {
        Do ..setWhitespaceNewLineElement(element,indent)
        ; need to do the froms and joins to the same indent?
        Set indent=indent+1 
    }

   If element.type="SelectInto" {
        Do ..setWhitespaceNewLineElement(element,indent)
    }

    If element.type="SqlCaseExpression" {
        Set indent=indent+1
    }

    If element.type="SqlCaseWhen" {
        Do ..setWhitespaceNewLineElement(element,indent)
    }
    If element.type="SqlCaseElse" {
        Do ..setWhitespaceNewLineElement(element,indent)
    }
    If element.type="SqlCaseEnd" {
        Do ..setWhitespaceNewLineElement(element,indent-1)
    }

    If element.type="FromClause" {
        Do ..setWhitespaceNewLineElement(element,indent)
    }
    If element.type="TableSubquery" {
        Set indent=indent+1
    }

    If element.type="Join" {
        Do ..setWhitespaceNewLineElement(element,indent)
        Set indent=indent+1
    }
    If element.type="JoinOn" {
        Do ..setWhitespaceNewLineElement(element,indent)
        Set flags="CONDITION"
    }

    If element.type="WhereClause" {
        Do ..setWhitespaceNewLineElement(element,indent)
        Set flags="CONDITION"
        Set indent=indent+1
    }

    ; put each AND on a new line, only applies to certain types of conditions (eg JOIN ON, WHERE)
    If flags["CONDITION" {
        If element.type="SqlDyadicop",$$$UPPER(element.ToString(0))="AND" {
            Do ..setWhitespaceNewLineElement(element,indent)
        }
    }

    If element.type="WithCommand" {
        Do ..setWhitespaceNewLineElement(element,indent)
        Set indent=indent+1
    }

    If element.type="WithClause" {
        Do ..setWhitespaceNewLineElement(element,indent)
        Set indent=indent+1
    }

    If element.type="SelectSublist" {
        Do ..setWhitespaceNewLineElement(element,indent)
    }

    If element.type="Union" {
        Do ..setWhitespaceNewLineElement(element,indent)
    }

    If element.type="GroupByClause" {
        Do ..setWhitespaceNewLineElement(element,indent)
    }
    If element.type="OrderByClause" {
        Do ..setWhitespaceNewLineElement(element,indent)
    }

    set akey=""
   	For  {
		Set a=element.partsGetNext(.akey)
		Quit:akey=""

	    If a.IsElement {
			Do ..setAll(a,indent,flags)
		} Else {
           ; set a.line=..currentLine
        }
	}

    ;i element.type="SelectCommand" {
     ;   s ..indent=..indent-1 
    ;}

