     s ..matcher.Text=..streaminput
 }
 Do:..needsWScheck ..skipWhiteSpaceAndComments()
 if ..matcher.LookingAt(..stream.pos)=1 {
     set pos=..matcher.End
     Set atom=..newAtom(ParentElement.type,..nextNotEOL(pos-..stream.pos))
     Do ParentElement.AddPart(.atom)
     Set ok=1
 } else {
