/*
/// This is left over from the initial build, the general purpose Identifier needs to be replaced by more specific
/// types for each case.
Method Identifier(ParentElement As PXW.DEV.BNF.Element, ByRef subElement As PXW.DEV.BNF.Element) As %Boolean
{
    $$$DEBUGMethodBegin
    ;$$$BNFPATH
	;;$$$DEBUG("%path="_%path)

    ;d ..skipWhiteSpaceAndComments()
    Do:..needsWScheck ..skipWhiteSpaceAndComments()

    Set value=""
    Set ok=0
    If $$$peek(..stream,2)="i%" {
        Set value=value_..next(2)
        If $$$peek(..stream,1)="""" {
            Set value=value_..nextNotEOL(1)
            While $$$peek(..stream,1)'="""" {
                Set value=value_..nextNotEOL(1)
            }
            Set value=value_..nextNotEOL(1)
            Set atom=..newAtom(ParentElement.type,value)
            Do ParentElement.AddPart(atom)
            Set ok=1
        }
    } Else {
        If $$$peek(..stream,1)="%" Set value=..nextNotEOL(1)
        If $$$peek(..stream,1)="%" Set value=..nextNotEOL(1)
        ; not a letter (or number)
        Set ch=$$$peek(..stream,1)
        ; no % so must start with a letter
        If value="",ch?1A Set value=..nextNotEOL(1)

        Set ok=1    
        If value="" {
            $$$DEBUG("checking identifier, ok=0")
            Set ok=0
        }
    }
    If ok {

        Set ch=$$$peek(..stream,1)
        While (ch?1A) || (ch?1N) || (ch=".")  {
            Set value=value_..nextNotEOL(1)
            Set ch=$$$peek(..stream,1)
        }

        Set atom=..newAtom("identifier",value)
        Do ParentElement.AddPart(atom)
    }
    ;$$$DEBUG("checking identifier, ok=1")
    ;zw atom
    $$$DEBUGMethodEnd
    Quit ok
}
*/

Method.Implementation:
	$$$DEBUGMethodBegin
	$$$BNFPATH
    Do:..needsWScheck ..skipWhiteSpaceAndComments()
    Set ch50=..stream.PeekToEol()
    Set i=1,hasDigits=0
    ; -
    While ($EXTRACT(ch50,i)="-") || ($EXTRACT(ch50,i)="+") {
        Set i=i+1
    }

    ; -123
    While ($EXTRACT(ch50,i)?1N) {
        Set i=i+1,hasDigits=1
    }

    ; start with a .
    If $EXTRACT(ch50,i,i+1)?1"."1N {
        Set i=i+2 ; . and number
        Set hasDigits=1
    }
    ; WE ARE NOT DEALING WITH "1." or "1.E10" or "1.*10" WHICH ARE ALL VALID BUT RARE

    If hasDigits {
    	$$$BNFSTART(subElement)

        ; -123.456
        While ($EXTRACT(ch50,i)?1N) {
            Set i=i+1
        }

        ; -123.456E
        If ($EXTRACT(ch50,i)="E") || ($EXTRACT(ch50,i)="e") {
            Set i=i+1
            ; 123.456E-
            If $EXTRACT(ch50,i)="-"{
                Set i=i+1
            }

            ; -123.456E-789
            While ($EXTRACT(ch50,i)?1N) {
                Set i=i+1
            }
        }

        Set atom=..newAtom("Number",..nextNotEOL(i-1))
        Do subElement.AddPart(atom)
        $$$BNFCOMMIT(subElement,ParentElement)
        Set retok=1
    } Else {
        Set retok=0
    }
	$$$DEBUGMethodEnd
	Quit retok

    $$$DEBUGMethodBegin
    Do:..needsWScheck ..skipWhiteSpaceAndComments()
	#dim o as PXW.DEV.Atom
    Set ok=0
    If $$$peek(..stream,1)="""" {
        Set ok=0
        $$$BNFSTART(subElement)

        ; consume the quotes
        Set q1=..nextNotEOL(1)
        Set ch50=..stream.PeekToEol()
        Set pos=1
        Set instring=1
        While $EXTRACT(ch50,pos)'="" && instring {
            Set ch=$EXTRACT(ch50,pos),ch2=$EXTRACT(ch50,pos+1)
            ; embedded quotes or end of string?
            If ch="""" {
                If ch2="""" {
                    Set pos=pos+2 ; both sets of quotes
                } Else {
                    Set instring=0
                }
            } Else {
                Set pos=pos+1
            }
        }
        Set o=..newAtom("String",..nextNotEOL(pos-1))
        Set o.start=q1
        Set o.end=..nextNotEOL(1) ; final quote
        Do subElement.AddPart(o)
        $$$BNFCOMMIT(subElement,ParentElement)
        Set ok=1

    }
    $$$DEBUGMethodEnd
    Quit ok

$$$DEBUGMethodBegin
Do:..needsWScheck ..skipWhiteSpaceAndComments()
If $$$peek(..stream,1)="""" {
    $$$BNFSTART(subElement)

    Set q1=..nextNotEOL(1)
    Set ch50=..stream.PeekToEol()
    Set pos=1
    Set instring=1
    While $EXTRACT(ch50,pos)'="" && instring {
        If $EXTRACT(ch50,pos,pos+1)="\""" {
            ; embedded quotes
            Set pos=pos+2
        } ElseIf $EXTRACT(ch50,pos)="""" {
            ; last quote
            Set instring=0
        } Else {
            Set pos=pos+1
        }
    }
    Set atom=..newAtom("String",..nextNotEOL(pos-1))
    Set atom.start=q1
    Set atom.end=..nextNotEOL(1) ; q2
    Do subElement.AddPart(atom)
    $$$BNFCOMMIT(subElement,ParentElement)
    Set ok=1
} Else {
    Set ok=0
}
$$$DEBUGMethodEnd
Quit ok

	#dim atom as PXW.DEV.Atom
    #dim c as %CSP.Documatic

    Do:..needsWScheck ..skipWhiteSpaceAndComments()
    Set peek=$$$peek(..stream,2)
    If $EXTRACT(peek,1)'="?",peek'="'?" Quit 0

	$$$DEBUGMethodBegin
    $$$BNFPATH
    $$$BNFSTART(subElement)

    If peek="'?" {
        Set atom=..newAtom("punctuation",..nextNotEOL(2))
    } Else {
        Set atom=..newAtom("punctuation",..nextNotEOL(1))
    }
    Do subElement.AddPart(atom)

    ; allowed spaces directly after ?
    Do ..skipWhiteSpaceAndComments()

	Set ok=1,bracket=0,instring=0,indirection=0,retok=1

    ; ?@indirect is special case
    If $$$peek(..stream,1)="@" Set ok=0,indirection=1

    Set ch50=..stream.PeekToEol()
    Set pos=1
	While $EXTRACT(ch50,pos)'="" && ok {
		Set ok=0
		Set peek=$EXTRACT(ch50,pos)

        If peek="""" {
            If instring {
                Set peek2=$EXTRACT(ch50,pos,pos+1)
                If peek2="""""" {
                    Set pos=pos+2
                } Else {
                    Set pos=pos+1
                    Set instring=0
                }
            } Else {
                Set instring=1
                Set pos=pos+1
            }
            Set ok=1
            Continue
        }
        If instring {
            Set pos=pos+1
            Set ok=1
            Continue
        }

		If peek="(" {
			Set bracket=bracket+1
			Set pos=pos+1
			Set ok=1
			Continue
		}
		If bracket>0,peek=")" {
			Set bracket=bracket-1
			Set pos=pos+1
			Set ok=1
			Continue
		}

		If bracket=0,peek=")" {
			Set ok=0
			Continue
		}

		If bracket>0,peek="," {
			Set pos=pos+1
			Set ok=1
			Continue
		}

		If bracket=0,peek="," {
			Set ok=0
			Continue
		}

        If $LISTFIND($LISTBUILD(":","|","&","{"," ",$CHAR(9)),peek) {
            Set ok=0
            Continue
        } 

        ; anything else (eg 1 or A)
        Set pos=pos+1
        Set ok=1
        Continue  
    }
    If pos>1 {
        Set atom=..newAtom("PatternMatch",..nextNotEOL(pos-1))
        Do subElement.AddPart(atom)
        $$$BNFCOMMITCOPY(subElement,ParentElement)
    } 

    If indirection {
        Set retok=..SimpleIndirection(subElement,.indirectSubElement)
        $$$BNFCOMMITCOPY(subElement,ParentElement)
        $$$DEBUG("pattern indirection result="_retok)
    }

	$$$DEBUGMethodEnd
	Quit retok

    $$$DEBUGMethodBegin
	$$$BNFPATH
	$$$BNFSTART(subElement)

    ; for recovery we need a way of stopping, so end of file or end of code block means no statement
    If ..eof()  Quit 0 
    If $$$peek(..stream,1)="}" Quit 0

    Set label=..LabelDefinition(subElement)
    ; check to see if the label is on a line on its own
    Do:..needsWScheck ..skipWhiteSpaceAndComments()

    ; only allow dots after whitespace
    ; if there is a label then we can have dots (not sure if thats true, or wise)
    ; if there is no label then the dots must be first thing on the line (ie whitespace contains cr)
    Set dots=0,invaliddot=0
   If $ISOBJECT(..whitespace) {
        Set newline=(..whitespace.value[$CHAR(13))
        If label || newline {
   	        While (..isString(subElement,".")) { Set dots=1 }
        } Else {
            If $$$peek(..stream,1)="." {
                Set invaliddot=1
            }
        } 
    } Else {
        If $$$peek(..stream,1)="." {
               Set invaliddot=1
        }
    }

    If invaliddot {
        ; this is messy, there must be a cleaner bit of logic for all this invalid dot stuff!
        Do ..recover(ParentElement,.recElement,"{}",$LISTBUILD($CHAR(32),$CHAR(9),$CHAR(160),$CHAR(13)))
        Set retok=1
    } Else {
        Set directive=0,command=0
        If ..stream.col=0 {
            Set directive=..CosDirective(subElement)
        } Else {
            If ..stream.col>0 Set command=..CosCommandOrMacro(subElement)
        }
        If label || dots || directive || command {
            $$$BNFCOMMIT(subElement,ParentElement)
            Set retok=1
        } Else {
            Do ..recover(ParentElement,.recElement,"{}",$LISTBUILD($CHAR(32),$CHAR(9),$CHAR(160),$CHAR(13)))
            Set retok=1
        }
    }

    $$$DEBUGMethodEnd
    Quit retok

$$$DEBUGMethodBegin
Do:..needsWScheck ..skipWhiteSpaceAndComments()
$$$DEBUG("Naked peek:"_$$$peek(..stream,20))
$$$DEBUG("Naked whitespace:"_..whitespace)
If ..whitespace $$$DEBUG("Naked whitespace:"_$TRANSLATE(..whitespace.value,$CHAR(32,9,13),"stc"))
; in single line mode and no white space found then we must be at the end of line
; eg: f x=1:1:10 d
; and therefore IS naked
If ..stopAtEOL,'$ISOBJECT(..whitespace) {
    $$$DEBUG("Naked 1")
    Set retok=1
} ElseIf  ..stopAtEOL,$ISOBJECT(..whitespace),$$$peek(..stream,1)=$CHAR(13) {
    $$$DEBUG("Naked 2")
    Set retok=1
} ElseIf $$$peek(..stream,1)="{" {
    $$$DEBUG("Naked 3")
    ; code block does not count as naked
    Set retok=0
} ElseIf $$$peek(..stream,1)="}" {
    $$$DEBUG("Naked 4")
    ; immediate end to code block does count as naked
    Set retok=1
} Else {
    $$$DEBUG("Naked 6")
    Set ch=$EXTRACT(..whitespace.value,1,2)
    Set chspc=$TRANSLATE(ch,$CHAR(9)," ") ; turn tabs into spaces for checking
    Set retok=0
    If chspc="  " {
        Set retok=1 ; is naked
    } ElseIf chspc=(" "_$CHAR(13)) {
        Set retok=1 ; is naked
    } Else {
        If $EXTRACT(ch,1)=$CHAR(13) Set retok=1 ; naked
    }
}
$$$DEBUG("Naked="_retok)
$$$DEBUGMethodEnd
Quit retok

    $$$DEBUGMethodBegin
	$$$BNFPATH
    $$$BNFSTART(subElement)
    Do:..needsWScheck ..skipWhiteSpaceAndComments()

    Set ch50=..stream.PeekToEol()
    Set pos=1
    Set ok=1
    Set bracket=1
    While $EXTRACT(ch50,pos)'="" && (bracket>0) {
        Set ch=$EXTRACT(ch50,pos)
        If ch="(" {
            Set pos=pos+1
            Set bracket=bracket+1
        } ElseIf ch=")" {
            If bracket>1 {
                Set pos=pos+1
            }
            Set bracket=bracket-1
        } Else {
            Set pos=pos+1
        }
    }
    Set o=..newAtom(subElement.type,..nextNotEOL(pos-1))
    Do subElement.AddPart(o)
    $$$BNFCOMMIT(subElement,ParentElement)
    $$$DEBUGMethodEnd
    Quit ok

	Set retok=##super(ParentElement,.subElement)

   If retok=0 {
       If ..codemode="DEFINE" {
           ; in DEFINE mode, just let it fail, do not attempt recovery
       } ElseIf ..codemode["STORAGE" {
           ; in storge we want to stop at the end tag (<) or if in a cdata:]]> 
           ; we can only allow 1 letter in each item in the list
           Set retok=..recover(ParentElement,.recSub,"{}",$LISTBUILD($CHAR(13),"<","]"))
       } Else {
           ;$$$DEBUG("RECOVERING "_..stream.PeekToEol())
           ;Set retok=..recover(ParentElement,.recSub,"{}",$LISTBUILD($CHAR(9)," ",$CHAR(13)))
           ;$$$DEBUG("RECOVERED ("_retok_")"_..stream.PeekToEol())
       }
   }
   ;i retok=0 break
   Quit retok

Set keyword=..peekKeyword()
If keyword'="" {
    Set next=..nextNotEOL($LENGTH(keyword))
    Do ParentElement.AddPart(..newAtom("keyword",next))
    Set retok=1
} Else {
    Set retok=0
}
Quit retok

	; rules summary K
	;if '(..isKeywordInList($lb("ZZ"),.value)) { quit 0 /* normal */ }
    Do:..needsWScheck ..skipWhiteSpaceAndComments()
    Set keyword=..peekKeyword()
    Set UPP=$$$UPPER(keyword)
    $$$DEBUG("keyword="_keyword)
	If UPP'?1"ZZ".AN Quit 0

	$$$DEBUGMethodBegin
	$$$BNFPATH
	$$$BNFSTART(subElement)
	Set done=0 ; method start
	If ..addKeyword(.subElement,UPP) {
		Set done=1 ; end compileRules
	}

	If done {
		$$$BNFCOMMIT(subElement,ParentElement)
		Set ok=1
	} Else {
		$$$BNFROLLBACK(subElement)
		Set ok=0 ; normal rollback
	}
	$$$DEBUGMethodEnd
	Quit ok

    $$$DEBUGMethodBegin
	Do:..needsWScheck ..skipWhiteSpaceAndComments()
    If $$$peek(..stream,1)="," {
        Set ok=1 
    } Else {
        Set ok=0
    }
    If ok {
        $$$BNFSTART(subElement)
        ; commit checks that the sub element has something in it, so forcing here
        ;$$$BNFCOMMIT(subElement,ParentElement)
        Do ParentElement.AddPart(subElement)
        $$$DEBUG("EmptyParameter committed")
    }
    $$$DEBUG("Empty="_ok)
    $$$DEBUGMethodEnd
    Quit ok

    $$$DEBUGMethodBegin
    $$$BNFSTART(subElement)
    Do:..needsWScheck ..skipWhiteSpaceAndComments()

    ; reached a mismatched > so at the end?
    If ..peek(1)=">" Quit 0

	;$$$BNFPATH
	;;$$$DEBUG("%path="_%path)
    Set ok=0,n=""
    While ('..eof()) && (..peek(1)'="<") && (..peek(1)'=">") {
        Set cos=0
        While ('..eof()) && (..peek(1)'="<") && (..peek(1)'=">") && ('cos) {
            Set ch2=..peek(2)
            If ch2="#(" {
                Set cos=1
            } Else {
                Set n=n_..next()
            }
            Set ok=1
        }
        Set o=..newAtom(subElement.type,n)
        Set n=""
        Do subElement.AddPart(o)
        If cos {
            Do ..CosExpression(subElement,.cosSubElement)
        }
    }
    $$$BNFCOMMIT(subElement,ParentElement)
    $$$DEBUGMethodEnd
    Quit ok

    $$$DEBUGMethodBegin
    $$$BNFSTART(subElement)
    Do:..needsWScheck ..skipWhiteSpaceAndComments()

    If $ISOBJECT(..whitespace) Quit 0

    ; reached a mismatched > so at the end?
    If ..peek(1)=">" Quit 0

	;$$$BNFPATH
	;;$$$DEBUG("%path="_%path)
    Set ok=0,n=""
    While ('..eof()) && (..peek(1)'="<") && (..peek(1)'=">")  && (..peek(1)'=" ") {
        Set cos=0
        While ('..eof()) && (..peek(1)'="<") && (..peek(1)'=">") && (..peek(1)'=" ") && ('cos) {
            Set ch2=..peek(2)
            If ch2="#(" {
                Set cos=1
            } Else {
                Set n=n_..next()
            }
            Set ok=1
        }
        Set o=..newAtom(subElement.type,n)
        Do subElement.AddPart(o)
        If cos {
            Do ..CosExpression(subElement,.cosSubElement)
        }
    }
    $$$BNFCOMMIT(subElement,ParentElement)
    $$$DEBUGMethodEnd
    Quit ok

$$$DEBUGMethodBegin $$$BNFSTART(subElement) $$$BNFPATH ;$$$DEBUG("%path="_%path)
;d ..skipWhiteSpaceAndComments() Do:..needsWScheck ..skipWhiteSpaceAndComments()
Set value="" Set ok=0 ;i ..peek(1)="%" s value=..next() ;i ..peek(1)="%" s value=..next() ; not a letter (or number) Set ch=..peek(1) ; no % so must start with a letter If value="",ch?1A Set value=..next()
Set ok=1 If value="" { $$$DEBUG("checking identifier, ok=0") Set ok=0 } If ok {
Set ch=..peek(1) While (ch?1A) || (ch?1N) || (ch=".") || (ch="-") { Set value=value_..next() Set ch=..peek(1) }
Set atom=..newAtom(subElement.type,value) Do subElement.AddPart(atom) Do ParentElement.AddPart(subElement) } ;$$$DEBUG("checking identifier, ok=1") ;zw atom $$$DEBUGMethodEnd Quit ok

    $$$DEBUGMethodBegin
    $$$BNFSTART(subElement)
    $$$BNFPATH
	;$$$DEBUG("%path="_%path)

    ;d ..skipWhiteSpaceAndComments()
    Do:..needsWScheck ..skipWhiteSpaceAndComments()
    Set ok=0
    Set char=..peek(1)
    If char="""" Set ok=1
    If char="'" Set ok=1

    Set instring=1 ; 1 means started, 2=continuation (after code expression)
    If ok {
        While '..eof() && instring {
            Set o=..newAtom("String")
            If instring=1 {
                Set o.start=..next()
                Set n=""
                Set marker=o.start
                Set instring=2
            }
            Set cos=0
            While '..eof() && instring && 'cos {
                Set ch=..peek(1),ch2=$EXTRACT(..peek(2),2)

                If ch="\" {
                    ; escaped marker (' or ")
                    If ch2=marker {
                        Set n=n_..next(2) ; \"
                    } ElseIf ch2="\" {
                        Set n=n_..next(2) ; \\
                    } Else {
                        Set n=n_..next()
                    }
                } ElseIf ch="#",ch2="(" { 
                    Set cos=1                
                } ElseIf ch=marker {
                    Set instring=0
                    Set o.end=..next()
                } Else {
                    Set n=n_..next()
                }
            }
            Set o.value=n
            Do subElement.AddPart(o)
            If cos {
                Do ..CosExpression(subElement,.cosSubElement) 
            }
        }
    }
    If ok {

        Do ParentElement.AddPart(subElement)
    }

    ;$$$DEBUG("checking identifier, ok=1")
    ;zw atom
    $$$DEBUGMethodEnd
    Quit ok

If ..nextStage=0 {
     Set ok=..UdlStatement(element)
     Set ..nextStage=1
} ElseIf ..nextStage=1 {
    Set ok=..OneClassmember(element)
    ; when we get past the memebers ok=0 so THEN move on
    If ok=0 {
        Set ok=..addPunctuation(element,"}")
        If ok {
            Do:..needsWScheck ..skipWhiteSpaceAndComments()
            Set ..nextStage=2
        }
    } 
} Else {
    Set ok=0
}

Quit ok

	If ..isStringSingle("{",.value)=0 Quit 0
	$$$DEBUGMethodBegin
	$$$BNFPATH
	$$$BNFSTART(subElement)
	Set done=0
	; type=group, check=if, skip=1, skipall=0
	Set gotVal=..next($LENGTH(value)),atom=..newAtom("punctuation",gotVal)
	Do subElement.AddPart(atom)

    If ..lowmem { 
        Set done=1
    } Else {
        If $SELECT(..ClassMemberList(subElement,.addedElement):1,1:1) {
            If ..addPunctuation(subElement,"}")	 {
                Set done=1
            }
        }
    }
	If done {
		$$$BNFCOMMIT(subElement,ParentElement)
		Set ok=1
	} Else {
		$$$BNFROLLBACK(subElement)
		Set ok=0
	}
	$$$DEBUGMethodEnd
	Quit ok

If ..commentMode="XML" {
    If $EXTRACT(ch10,1,4)="<!--" Set ..comment=..readBlockComment("<!--","-->") Quit 1
} Else {
    If $EXTRACT(ch10,1,3)="///" Set ..comment=..readLineComment("///") Quit 1
    If $EXTRACT(ch10,1,2)="//" Set ..comment=..readLineComment("//") Quit 1
    If $EXTRACT(ch10,1,2)="/*" Set ..comment=..readBlockComment("/*","*/") Quit 1
}
Quit 0

    $$$DEBUGMethodBegin
    If ..keyword="" {
        Set word=""
        ;Set ch50=$$$peek(..stream,50)
        Set ch50=$EXTRACT(..streaminput,..stream.pos,..stream.pos+50)
        ; starts with a letter
        If $EXTRACT(ch50,1)?1A {
            Set i=2
            ; carries on with a letter or number or /
            While ($EXTRACT(ch50,i)?1AN) || ($EXTRACT(ch50,i)="/")  {
                Set i=i+1
            }
            Set word=$EXTRACT(ch50,1,i-1)
        } 
        Set ..keyword=" "_word ; so that even null counts as being found
    } Else {
        Set word=$EXTRACT(..keyword,2,*) ; remove the space from the start so null is null
    }
    $$$DEBUGMethodEnd
	Quit word

    Set ..language=..classLanguage
    Set ..codemode=""

	Set ok=##super(ParentElement,.subElement)

    If ok=0 {
        Set peek=$$$peek(..stream,1)
        ; not eol or end of block
        If peek'=$CHAR(13),peek'="}" {
            Set ok=..recover(ParentElement,.recSub,"{}",$LISTBUILD($CHAR(13)))
        }
    }

    Quit ok

Set ok=##super(ParentElement,.subElement)

If ok=0 {
    Set ok=..recover(ParentElement,.recSub,"{}","")
}

Quit ok

#dim atom as PXW.DEV.Atom $$$BNFPATH $$$BNFSTART(subElement) Set atom=..newAtom("SQLCodeBlock Begin","") Do ParentElement.AddPart(atom)
Set parser=##class(PXW.DEV.BNF.Run.SQL).%New() Set parser.stream=..stream Do parser.skipWhiteSpaceAndComments() ;$$$DEBUG("COS CODE BLOCK peeked "_parser.peek(1)) If parser.peek(1)="}" { ; its empty Set ..comment=parser.GetCurrentComment() Set atom=..newAtom("SQLCodeBlock Empty","") Do ParentElement.AddPart(atom) Set ..whitespace=parser.whitespace Quit 1 } If parser.QuerySpecification(subElement) { Set ..comment=parser.GetCurrentComment() Set atom=..newAtom("SQLCodeBlock End","") Do subElement.AddPart(atom) $$$BNFCOMMIT(subElement,ParentElement) Set ..whitespace=parser.whitespace If $$$peek(..stream,1)'="}" { Do ..recover(ParentElement,.recsub,"{}","") }
Quit 1 } Else { $$$BNFROLLBACK(subElement) Quit 0 }

	#dim atom as PXW.DEV.Atom
	;$$$BNFPATH
	$$$BNFSTART(subElement)
    Set atom=..newAtom("CosCodeBlock Begin","")
    Do ParentElement.AddPart(atom)

    If $$$UPPER(..language)="PYTHON" {
        ;$$$DEBUGNew("")
        Set subElement.type="PythonBody"
        Set pyparser=##class(PXW.DEV.BNF.Run.Python).%New()
        Set pyparser.stream=..stream
        Do pyparser.skipWhiteSpaceAndComments()
        If pyparser.peek(1)="}" {
            ; its empty 
            Set ..comment=pyparser.GetCurrentComment()
            Set atom=..newAtom("CosCodeBlock Empty","")
            Do ParentElement.AddPart(atom)
            Set ..whitespace=pyparser.whitespace
            Quit 1
        }
        If pyparser.File(subElement) {
             $$$BNFCOMMIT(subElement,ParentElement)
            Set ..comment=pyparser.GetCurrentComment()
            Set atom=..newAtom("CosCodeBlock End","")
            Do ParentElement.AddPart(atom)
            Set ..whitespace=pyparser.whitespace
 		    Quit 1
        } Else {
            Do ..recover(ParentElement,.subElement,"{}","") ; NOT WORKING AS EXPECTED!
            ;;$$$BNFROLLBACK(subElement)
            ;Quit 1
        }
    }

    If $$$UPPER(..language)="MVBASIC" {
        ; NOT CODED YET
            Do ..recover(ParentElement,.subElement,"{}","") ; NOT WORKING AS EXPECTED!
            Quit 1
    }

	Set parser=##class(PXW.DEV.BNF.Run.COS).%New()
	Set parser.stream=..stream
    Do parser.skipWhiteSpaceAndComments()
    ;$$$DEBUG("COS CODE BLOCK peeked "_parser.peek(1))
	If parser.peek(1)="}" {
		; its empty 
		Set ..comment=parser.GetCurrentComment()
		Set atom=..newAtom("CosCodeBlock Empty","")
		Do ParentElement.AddPart(atom)
		Set ..whitespace=parser.whitespace
		Quit 1
	}

    ; the only example of a call I have seen looked like an expression and not what was documented
    ; 
	If (..codemode="expression") || (..codemode="call") {
        $$$DEBUG("COS language EXPRESSION")
        If parser.Expression(subElement) {
            ; maybe its codemode=expression (need to check specifically)
            Set ..comment=parser.GetCurrentComment()
            Set atom=..newAtom("CosCodeBlock End","")
            Do subElement.AddPart(atom)
            $$$BNFCOMMIT(subElement,ParentElement)
