                Set instring=2
            }
            Set cos=0
            While '..eof() && instring && 'cos {
                Set ch=..peek(1),ch2=$EXTRACT(..peek(2),2)

                If ch="\" {
                    ; escaped marker (' or ")
                    If ch2=marker {
                        Set n=n_..next(2) ; \"
                    } ElseIf ch2="\" {
                        Set n=n_..next(2) ; \\
                    } Else {
                        Set n=n_..next()
                    }
                } ElseIf ch="#",ch2="(" { 
                    ; what if we have '#(' ? thats annoying
                    If $EXTRACT(..peek(3),3)=marker {
                        ; not in cos!
                        Set n=n_..next(2)
                    } Else {
                        Set cos=1
                    }
                } ElseIf ch=marker {
                    Set instring=0
                    Set o.end=..next()
                } Else {
                    Set n=n_..next()
                }
            }
            Set o.value=n
            Do subElement.AddPart(o)
            If cos {
                Do ..CosExpression(subElement,.cosSubElement) 
            }
        }
    }
    If ok {

        Do ParentElement.AddPart(subElement)
    }

    ;$$$DEBUG("checking identifier, ok=1")
    ;zw atom
    $$$DEBUGMethodEnd
    Quit ok

    $$$DEBUGMethodBegin
    $$$BNFSTART(subElement)
    $$$BNFPATH
	;$$$DEBUG("%path="_%path)

    ;d ..skipWhiteSpaceAndComments()
    Do:..needsWScheck ..skipWhiteSpaceAndComments()
    Set ok=0
    Set char=..peek(1)
    If char="""" Set ok=1
    If char="'" Set ok=1
    If char="`" Set ok=1

    Set instring=1 ; 1 means started, 2=continuation (after code expression)
    If ok {
        While '..eof() && instring {
            Set o=..newAtom("String")
            Set n=""
            If instring=1 {
                Set o.start=..next()
                ;Set n=""
                Set marker=o.start
                Set instring=2
            }
            Set cos=0
            While '..eof() && instring && 'cos {
                Set ch=..peek(1),ch2=$EXTRACT(..peek(2),2)

                If ch="\" {
                    ; escaped marker (' or ")
                    If ch2=marker {
                        Set n=n_..next(2) ; \"
                    } ElseIf ch2="\" {
                        Set n=n_..next(2) ; \\
                    } Else {
                        Set n=n_..next()
                    }
                } ElseIf ch=marker {
                    Set instring=0
                    Set o.end=..next()
                } Else {
                    Set n=n_..next()
                }
            }
            Set o.value=n
            Do subElement.AddPart(o)
            If cos {
                Do ..CosExpression(subElement,.cosSubElement) 
            }
        }
    }
    If ok {

        Do ParentElement.AddPart(subElement)
    }

    ;$$$DEBUG("checking identifier, ok=1")
    ;zw atom
    $$$DEBUGMethodEnd
    Quit ok

	#dim o as PXW.DEV.Atom

    $$$DEBUGMethodBegin
	;$$$BNFPATH
	;;$$$DEBUG("%path="_%path)
    Do:..needsWScheck ..skipWhiteSpaceAndComments()

    Set ok=0
    If ..peek(1)'="","/"[..peek(1) {
        Set ok=1
    }

    If ok {
        $$$BNFSTART(subElement)

        Set q1="/"
        Set n=..nextNotEOL(1)
        Set instring=1
        While '..eof() && instring {
            Set chs=..peek(2)
            Set ch=$EXTRACT(chs,1),ch2=$EXTRACT(chs,2)
            ; embedded quotes
            If ch="/" {
                If ch2=q1 {
                    Set n=n_..nextNotEOL(2)
                } Else {
                    Set instring=0
                    Set n=n_..nextNotEOL(1)
                } 
            }  ElseIf ch="\",ch2="\" {
                Set n=n_..nextNotEOL(2)   
            } ElseIf ch="\",ch2="/" {
                Set n=n_..nextNotEOL(2)   
            } Else {
                Set n=n_..nextNotEOL(1)
            }
        }
        ; reg ex can end with an extra letter on the end "/abc/i"
        While ..peek(1)?1a {
            Set n=n_..nextNotEOL(1)
        }
        Set o=..newAtom("RegEx",n)

        Do subElement.AddPart(o)
        $$$BNFCOMMIT(subElement,ParentElement)
    }
    $$$DEBUGMethodEnd
    Quit ok

	Set ok=##super(ParentElement,Punctuation,.foundString)
    ; stuff in ( ) can span more than 1 line
    If ok {
        If foundString="(" {
            Set ..bracketDepth=..bracketDepth+1,..stopAtEOL=0
        } ElseIf foundString=")" {
            Set ..bracketDepth=..bracketDepth-1
        } ElseIf foundString="[" {
            Set ..sqDepth=..sqDepth+1,..stopAtEOL=0 
        } ElseIf foundString="]" {
            Set ..sqDepth=..sqDepth-1
        } ElseIf foundString="{" {
            Set ..curlyDepth=..curlyDepth+1,..stopAtEOL=0
        } ElseIf foundString="}" {
            Set ..curlyDepth=..curlyDepth-1
        }
        If ..bracketDepth=0,..curlyDepth=0,..sqDepth=0 {
            Set ..stopAtEOL=1
        }
    }
    Quit ok

	Set ok=##super(ParentElement,.subElement)
    If ok=0 {
        Set ok=..recover(ParentElement,.recsub,"{}",$LISTBUILD())
        Set ok=1 ; recovered so continue
    }
    Quit ok

		#dim o as PXW.DEV.Atom

    $$$DEBUGMethodBegin
	;$$$BNFPATH
	;;$$$DEBUG("%path="_%path)
    Do:..needsWScheck ..skipWhiteSpaceAndComments()

    Set ok=0

    If (..peek(3)="'''") || (..peek(3)="""""""")  
    || ($$$LOWER(..peek(4))="r'''") || ($$$LOWER(..peek(4))="r""""""") {
        $$$BNFSTART(subElement)
        Set r1=""
        If $$$LOWER(..peek(1))="r" Set r1=..nextNotEOL(1)
        Set q1=..nextNotEOL(3),n="",instring=1
        While '..eof() && instring {
            Set chs=..peek(3),ch=$EXTRACT(chs,1),ch2=$EXTRACT(chs,2)
            ; what do embedded quotes look like here?
           If chs=q1 {
                    Set instring=0
                    Set q2=..next(3)
            } Else {
                Set n=n_..next(1)
            }
        }
        Set o=..newAtom("String",n)
        Set o.start=r1_q1,o.end=q2
        Do subElement.AddPart(o)
        $$$BNFCOMMIT(subElement,ParentElement)
        Set ok=1
    } ElseIf ..peek(1)'="","""'"[..peek(1) {
        ; single or double quote start
        Set ok=1
        $$$BNFSTART(subElement)

        Set q1=..nextNotEOL(1),n="",instring=1
        While '..eof() && instring {
            Set chs=..peek(2),ch=$EXTRACT(chs,1),ch2=$EXTRACT(chs,2)
            ; embedded quotes (\') or escaped \ (\\)
            If ch="\" {
                If ch2=q1 {
                    Set n=n_..nextNotEOL(2)
                } ElseIf ch2="\" {
                    Set n=n_..nextNotEOL(2)
                } Else {
                    Set n=n_..nextNotEOL(1)
                }
            } ElseIf ch=q1 {
                    Set instring=0
                    Set q2=..nextNotEOL(1)
            } Else {
                Set n=n_..nextNotEOL(1)
            }
        }
        Set o=..newAtom("String",n)
        Set o.start=q1,o.end=q2
        Do subElement.AddPart(o)
        $$$BNFCOMMIT(subElement,ParentElement)
    } ElseIf ..peek(1)'="",$LISTFIND($LISTBUILD("R""","R'","B'","B"""),$$$UPPER(..peek(2))) {
        ; r' r" start (raw string)
        ; b strings ??
        Set ok=1
        $$$BNFSTART(subElement)

        Set rq1=..nextNotEOL(2),q1=$EXTRACT(rq1,2),n="",instring=1
        While '..eof() && instring {
            Set chs=..peek(2),ch=$EXTRACT(chs,1),ch2=$EXTRACT(chs,2)
            ; embedded quotes - in raw string -NOT SURE
            If ch="\" {
                If ch2=q1 {
                    Set n=n_..nextNotEOL(2)
                } Else {
                    Set n=n_..nextNotEOL(1)
                }
            } ElseIf ch=q1 {
                    Set instring=0
                    Set q2=..nextNotEOL(1)
            } Else {
                Set n=n_..nextNotEOL(1)
            }
        }
        Set o=..newAtom("String",n)
        Set o.start=rq1,o.end=q2
        Do subElement.AddPart(o)
        $$$BNFCOMMIT(subElement,ParentElement)
    }
    $$$DEBUGMethodEnd
    Quit ok

	$$$DEBUGMethodBegin
	$$$BNFPATH
	;$$$DEBUG("%path="_%path)
	$$$BNFSTART(subElement)
	Set done=0

    ; hex number
    If $$$LOWER(..peek(2))="0x" {
        Set n=..nextNotEOL(2)
        While (..peek(1)'="") && ("01234567890ABCDEFabcdef_"[..peek(1)) {
            Set n=n_..nextNotEOL(1)
        }
        If n'="" {
            Set atom=..newAtom("Number",n)
            Do subElement.AddPart(atom)
            $$$BNFCOMMITCOPY(subElement,ParentElement)
            Set ok=1
        }
    ; binary number
    } ElseIf $$$LOWER(..peek(2))="0b" {
        Set n=..nextNotEOL(2)
        While (..peek(1)'="") && ("01_"[..peek(1)) {
            Set n=n_..nextNotEOL(1)
        }
        If n'="" {
            Set atom=..newAtom("Number",n)
            Do subElement.AddPart(atom)
            $$$BNFCOMMITCOPY(subElement,ParentElement)
            Set ok=1
        }
        $$$DEBUG("number binary:"_n_", ok="_ok)
    ; octal?
    } ElseIf $$$LOWER(..peek(2))="0o" {
        Set n=..nextNotEOL(2)
        While (..peek(1)'="") && ("01234567_"[..peek(1)) {
            Set n=n_..nextNotEOL(1)
        }
        If n'="" {
            Set atom=..newAtom("Number",n)
            Do subElement.AddPart(atom)
            $$$BNFCOMMITCOPY(subElement,ParentElement)
            Set ok=1
        }
    } Else {

        Set n=""
        ; -
        While (..peek(1)="-") || (..peek(1)="+") {
            Set n=n_..nextNotEOL(1)
        }

        ; -123
        While (..peek(1)?1N) {
            Set n=n_..nextNotEOL(1)
        }

        ; start with a .
        If ..peek(2)?1"."1N {
            Set n=n_..next(2)
        }
        If n'="" {

            ; -123.456
            While (..peek(1)?1N) || (..peek(1)="_"){
                Set n=n_..nextNotEOL(1)
            }

            ; -123.456E
            If (..peek(1)="E") || (..peek(1)="e") {
                Set n=n_..nextNotEOL(1)
                ; 123.456E-
                If ..peek(1)="-"{
                    Set n=n_..nextNotEOL(1)
                }

                ; -123.456E-789
                While (..peek(1)?1N) || (..peek(1)="_") {
                    Set n=n_..nextNotEOL(1)
                }
            }

            If n'="" {
                Set atom=..newAtom("Number",n)
                Do subElement.AddPart(atom)
                Set done=1
            }

            If done {
                $$$BNFCOMMITCOPY(subElement,ParentElement)
                Set ok=1
            } Else {
                $$$BNFROLLBACK(subElement)
                Set ok=0
            }
        } Else {
            Set ok=0
        }
    }
	$$$DEBUGMethodEnd
	Quit ok

$$$DEBUGMethodBegin
Set subElement=ParentElement
Set done=0 ; method start
If ..FstringReplacementField(subElement,.addedElement)  {
	Set done=1 ; or
} ElseIf ..FstringMiddleText(subElement,.addedElement)  {
	Set done=1 ; end compileRules
}
If done {
	Set ok=1
} Else {
	Set ok=0 ; normal rollback
}
$$$DEBUGMethodEnd
Quit ok

#dim o as PXW.DEV.Atom
$$$DEBUGMethodBegin
;$$$BNFPATH
;;$$$DEBUG("%path="_%path)
Set n=""
Set endf=..fStringEndChar
Set endfLen=$LENGTH(endf)
Set embeddedf="\"_..fStringEndChar
Set embeddedfLen=$LENGTH(embeddedf)
While ..peek(1)'="{",..peek(endfLen)'=endf {
    If ..peek(embeddedfLen)=embeddedf {
        Set n=n_..next(embeddedfLen)
    } Else {
        Set n=n_..next(1)
    }
}
If n'="" {
    Set o=..newAtom("String",n)
    Do ParentElement.AddPart(o)
    Set ok=1
} Else {
    Set ok=0
}
$$$DEBUGMethodEnd
Quit ok

Set old=..stopAtEOL Do:..needsWScheck ..skipWhiteSpaceAndComments() Set ..stopAtEOL=1
; Until I sort out the whole skipWhiteSpaceAndComment issue: ; The superclass happily skips whitespaces but in Python they are important! ; I will have to track indents here Set ok=1 If $ISOBJECT(..whitespace) { Set indent=$PIECE(..whitespace.value,..stream.eolChar,*) ; have we moved back a level, if so then treat this as a FAILURE ; which should fall back into the block and allow it to continue again later If $LENGTH(indent)<$LENGTH(..currentIndent) { Set ok=0 } Set ..currentIndent=indent }
If ok { Set ok=##super(ParentElement,.subElement) } Set ..stopAtEOL=old Quit ok

UDLText.Content:
/*
