    $$$DEBUGMethodBegin
    i ..stopAtEOL { 
        s ws=$c(32,9,160)
    } else {
        s ws=$c(32,9,13,10,160)
    }
    s spaces=""
    do {
        s spaces=spaces_..stream.NextChars(ws)
        ; \ at end of line means we can continue to the next
        i ..peek(2)=("\"_..stream.eolChar) s spaces=spaces_..next(2)
    } while '..eof() && (ws[..peek(1))

    s o=..newAtom("whitespace",spaces)
    $$$DEBUGMethodEnd
