    i '..eof(),ws[ch s ..whitespace=..readWhitespace() g readNextLoop
    i '..eof(),($e(ch10,1,2)="\"_..stream.eolChar) s ..whitespace=..readWhitespace() g readNextLoop
    i '..eof(),..skipComments(ch10) g readNextLoop
    s ..needsWScheck=0
readExit
    $$$DEBUGMethodEnd 
