Method.Implementation:
	$$$DEBUGMethodBegin
	$$$BNFPATH
	;$$$DEBUG("%path="_%path)
	$$$BNFSTART(subElement)
	Set done=0
	If ..Identifier(subElement,.addedAtom) {
        Set string=$$$UPPER(subElement.ToString(0))
        ; an alias must not be any of the following
        $$$DEBUG("Alias name found:"_string)
        If $LISTFIND($LISTBUILD("LEFT","RIGHT","INNER","OUTER","CROSS","JOIN","FROM","WHERE","UNION","ON","INTO","SET","HAVING"),string)>0 {
            Set done=0
        } Else {
            ; it may be ORDER unless its followed by BY
            If $LISTFIND($LISTBUILD("ORDER","GROUP"),string) {
                Do ..skipWhiteSpaceAndComments()
                Set peek=$$$UPPER(..peek(2))
                If peek="BY" {
                    Set done=0
                } Else {
                    Set done=1
                }
            } Else {
		        Set done=1
            }
        }
	}
	If done {
		$$$BNFCOMMIT(subElement,ParentElement)
		Set ok=1
	} Else {
		$$$BNFROLLBACK(subElement)
		Set ok=0
	}
	$$$DEBUGMethodEnd
	Quit ok

	$$$DEBUGMethodBegin
	$$$BNFPATH
	;$$$DEBUG("%path="_%path)
	$$$BNFSTART(subElement)
	Set done=0
    If ..addPunctuation(subElement,"*") {
        Set done=1
    } ElseIf ..Identifier(subElement,.addedElement)	 {
        Set string=$$$UPPER(subElement.ToString(0))
        ; an alias must not be any of the following
        If $LISTFIND($LISTBUILD("LEFT","RIGHT","INNER","OUTER","CROSS","JOIN","FROM","WHERE","UNION","ON","INTO"),string)>0 {
            Set done=0
        } Else {
            ; it may be ORDER unless its followed by BY
            If string="ORDER" {
                Do ..skipWhiteSpaceAndComments()
                Set peek=$$$UPPER(..peek(2))
                If peek="BY" {
                    Set done=0
                } Else {
                    Set done=1
                }
            } Else {
		        Set done=1
            }
        }
    }
	If done {
		$$$BNFCOMMIT(subElement,ParentElement)
		Set ok=1
	} Else {
		$$$BNFROLLBACK(subElement)
		Set ok=0
	}
	$$$DEBUGMethodEnd
	Quit ok

    $$$DEBUGMethodBegin
    $$$BNFPATH
	;$$$DEBUG("%path="_%path)

    ;d ..skipWhiteSpaceAndComments()
    Do:('..whitespace&&'..comment) ..skipWhiteSpaceAndComments()

    Set value=""
    Set ok=0

    ; identifiers in SQL can be in ""
    If ..peek(1)="""" {

        Set q1=..next()
        Set ok=1
        While ok {
            Set ch2=..peek(2)
            If ch2="""""" {
                Set value=value_..next(2)
            } ElseIf ..peek(1)'="""" {
                Set value=value_..next()
            } Else {
                Set ok=0
            }
        }
        Set q2=..next()
        Set atom=..newAtom(ParentElement.type,value)
        Set atom.start=q1
        Set atom.end=q2
        Do ParentElement.AddPart(atom)
        Set ok=1
    } Else {

        If ..peek(1)="%" Set value=..next()
        If ..peek(1)="%" Set value=..next()
        If ..peek(1)="_" Set value=..next()
        ; not a letter (or number)
        Set ch=..peek(1)
        ; no % so must start with a letter
        If value="",ch?1A Set value=..next()

        Set ok=1    
        If value="" {
            $$$DEBUG("checking identifier, ok=0")
            Set ok=0
        }

        If ok {

            Set ch=..peek(1)
            While (ch?1A) || (ch?1N) || (ch="_")  {
                Set value=value_..next()
                Set ch=..peek(1)
            }

            Set atom=..newAtom(ParentElement.type,value)
            Do ParentElement.AddPart(atom)
        }
    }
    ;$$$DEBUG("checking identifier, ok=1")
    ;zw atom
    $$$DEBUGMethodEnd
    Quit ok

	$$$DEBUGMethodBegin
	$$$BNFPATH
	;$$$DEBUG("%path="_%path)
    Set digits="01234567890."
	Set n="",done=0
	While ('..eof()) && (digits[..peek(1)) {
		Set n=n_..next()
        Set done=1
	}
    ; -123.456E
    If done,((..peek(1)="E") || (..peek(1)="e")) {
        Set n=n_..nextNotEOL(1)
        ; 123.456E-
        If ..peek(1)="-"{
            Set n=n_..nextNotEOL(1)
        }

        ; -123.456E-789
        While (..peek(1)?1N) {
            Set n=n_..nextNotEOL(1)
        }
    }

	If done {
        Set atom=..newAtom("Number",n)
        Do ParentElement.AddPart(atom)
		Set ok=1
	} Else {
		Set ok=0
	}
	$$$DEBUGMethodEnd
	Quit ok

    $$$DEBUGMethodBegin
	$$$BNFPATH
	;$$$DEBUG("%path="_%path)
    Do:('..whitespace&&'..comment) ..skipWhiteSpaceAndComments()

    Set ok=1
    Set quote=..peek(1)
    If quote'="'" {
        Set ok=0
    }

    If ok {
        $$$BNFSTART(subElement)

        Set n=..next()
        Set instring=1
        While '..eof() && instring {
            Set chs=..peek(2)
            Set ch=$EXTRACT(chs,1),ch2=$EXTRACT(chs,2)
            ; embedded quotes or end of string?
            If ch=quote {
                If ch2=quote {
                    Set n=n_..next()_..next()
                } Else {
                    Set instring=0
                    Set n=n_..next()
                }
            } Else {
                Set n=n_..next()
            }
        }
        Set o=..newAtom("String",n)
        Do subElement.AddPart(o)
        $$$BNFCOMMIT(subElement,ParentElement)
    }
    $$$DEBUGMethodEnd
    Quit ok

	#dim atom as PXW.DEV.Atom
    $$$DEBUGMethodBegin
	$$$BNFPATH
 	$$$BNFSTART(subElement)
    Set ok=0

    Set parser=##class(PXW.DEV.BNF.Run.COS).%New()
    Set parser.stream=..stream
    Set parser.codemode="COSSQL" ; not really true, should only be set for TRIGGERS but at this point we don't know where we are! and we should treat these as field names
    Set parser.whitespace=..whitespace
    Set parser.comment=..comment
    ;d parser.skipWhiteSpaceAndComments()
    if parser.ThisObjectDirectProperty(subElement) {
        set ok=1
    } elseIf parser.Variable(subElement) {
        Set ok=1
    } 
    If ok=1 {
        Set ..whitespace=parser.whitespace
        Set ..comment=parser.comment
        $$$BNFCOMMIT(subElement,ParentElement)
    } Else {
        $$$BNFROLLBACK(subElement)
    }
    $$$DEBUGMethodEnd
    Quit ok

If ..eof() Quit 0

$$$DEBUGMethodBegin
Do:..needsWScheck ..skipWhiteSpaceAndComments()

If ..StartedNewLine {    
    Set depth=..NewLineIndent
    Set %ForEachDepth=depth
    $$$DEBUG("Set %ForEachDepth="_depth_", peek="_..peek(30))
} Else {
    $$$DEBUG("Indent not on new line")
}
$$$DEBUGMethodEnd
Quit 1

    $$$DEBUGMethodBegin
    Do:..needsWScheck ..skipWhiteSpaceAndComments()
	#dim o as PXW.DEV.Atom
    Set ok=0
    If ..peek(1)="""" {
        Set ok=0
        $$$BNFSTART(subElement)

        ; consume the quotes
        Set q1=..nextNotEOL(1)
        Set ch50=..stream.PeekToEol()
        Set pos=1
        Set instring=1
        While $EXTRACT(ch50,pos)'="" && instring {
            Set ch=$EXTRACT(ch50,pos),ch2=$EXTRACT(ch50,pos+1)
            ; embedded quotes or end of string?
            If ch="""" {
                If ch2="""" {
                    Set pos=pos+2 ; both sets of quotes
                } Else {
                    Set instring=0
                }
            } Else {
                Set pos=pos+1
            }
        }
        Set o=..newAtom("String",..nextNotEOL(pos-1))
        Set o.start=q1
        Set o.end=..nextNotEOL(1) ; final quote
        Do subElement.AddPart(o)
        $$$BNFCOMMIT(subElement,ParentElement)
        Set ok=1

    }
    $$$DEBUGMethodEnd
    Quit ok

Export.Routine:
#include PXW.DEV.BNF.ElementMacros 

/// start a parser section "transaction"
#define BNFSTART(%sub) set %sub=..newElement(##Expression(""""_%methodname_"""")) d ..getBookmark(.##SAFEExpression("%sub"_"BM")) /* $$$DEBUG("BNFSTART:"_%subElement)*/

/// commit the transaction to the parent
///#define BNFCOMMIT(%sub,%parent) do:%sub.partsCount()>0 %parent.AddPart(.%sub) 
///#define BNFCOMMIT(%sub,%parent) Do:$$$ElementPartsExist(%sub) %parent.AddPart(.%sub) 
#define BNFCOMMIT(%sub,%parent) if $$$ElementPartsExist(%sub) { $$$ELEMENTPARTADD(%parent,%sub) }

/// commit the transaction to the parent, by copying the data rather than creating a new node
///#define BNFCOMMITCOPY(%sub,%parent) do:$$$ElementPartsExist(%sub) %parent.partsCopy(.%sub) 
#define BNFCOMMITCOPY(%sub,%parent) If $$$ElementPartsExist(%sub) { $$$ELEMENTPARTCOPY(%parent,%sub) }

/// rollback the transaction 
/// define BNFROLLBACK(%sub) $$$DEBUG("BNFROLLBACK:"_$p($g(%path),"/",*)) s:%sub.partsCount() rbcount=$i(%RBCOUNT(##Expression(""""_%methodname_""""))) d:%sub.partsCount() ..gotoBookmark(.##SAFEExpression("%sub"_"BM")) kill %sub
///#define BNFROLLBACK(%sub) $$$DEBUG("BNFROLLBACK:"_$p($g(%path),"/",*)) s:$$$ElementPartsCount(%sub) rbcount=$i(%RBCOUNT(##Expression(""""_%methodname_""""))) d:$$$ElementPartsCount(%sub) ..gotoBookmark(.##SAFEExpression("%sub"_"BM")) kill %sub
#define BNFROLLBACK(%sub) $$$DEBUG("BNFROLLBACK:"_$p($g(%path),"/",*)) if $$$ElementPartsExist(%sub) { set rbcount=$i(%RBCOUNT(##Expression(""""_%methodname_""""))) do ..gotoBookmark(.##SAFEExpression("%sub"_"BM")) kill %sub }

/// keep track of the path
#define BNFPATH i $d(%path) set currentpath=%path new %path set %path=currentpath_$c(47)_##expression(""""_%methodname_"""") $$$DEBUG("%path="_%path) $$$DEBUG("%path at "_$zconvert(..peek(20),"O","JSON"))


/// MEMO storage is used as a cache a method's result, used for recursive
/// See if there is an item in the cache at the given position
#DEFINE BNFMEMOExists(%pos) $d(..memo(##safeexpression(""""_%classname_":"_%methodname_""""),%pos))

/// Set a memo is the storage
#DEFINE BNFMEMOSET(%pos,%obj) d ..getBookmark(.bma) s ..memo(##safeexpression(""""_%classname_":"_%methodname_""""),%pos)=%obj m ..memo(##safeexpression(""""_%classname_":"_%methodname_""""),%pos,"bm")=bma

/// Get a memo from storage
#DEFINE BNFMEMOGET(%pos,%obj) s %obj=..memo(##safeexpression(""""_%classname_":"_%methodname_""""),%pos) m bma=..memo(##safeexpression(""""_%classname_":"_%methodname_""""),%pos,"bm") d ..gotoBookmark(.bma)

/// Kill a memo from storage
#DEFINE BNFMEMOKILL(%pos,%obj) k ..memo(##safeexpression(""""_%classname_":"_%methodname_""""),%pos)

#DEFINE UPPER(%s) $zconvert(%s,"U")

#define peek(%stream,%number) $e(%stream.input,%stream.pos,%stream.pos+%number-1)

Method.Implementation:
$$$DEBUGMethodBegin
do ..processSpecificElement(element,"PRE")
set partkey=""
For  {
	Set part=element.partsGetNext(.partkey)
	Quit:partkey=""

	If part.IsElement {
		Do ..processElement(part)
	} Else {
		Do ..processAtom(part)
	}
}
do ..processSpecificElement(element,"POST")
$$$DEBUGMethodEnd

If $ISOBJECT(val) {
    Set i%stream=val
    Set ..streamlen=$LENGTH(val.input)
    Set ..streaminput=val.input 
}
Quit $$$OK

New %path Set %path=""
If debuggerObject="" {
    Set debugger="PXW.Debuggers.Basic"
    If debugToFile {
        Set debugger="PXW.Debuggers.BasicToFile"
    }
} Else {
    Set debugger=debuggerObject
}
$$$DEBUGNew(debugger)
$$$DEBUG("Testing="_text)
$$$DEBUG("method="_method)
Set element=##class(PXW.DEV.Element).%New()
Set %section=element
Set x=..%New()
;s x.element=element
Set x.stream=##class(PXW.DEV.InputStream).NewString(text)
Set ok=$METHOD(x,method,element)
$$$DEBUG("ok="_ok)
$$$DEBUG("x.element.ToString()="_element.ToString())
$$$DEBUG("Testing complete")
$$$DEBUG("")
If debugToFile {
    Set debug=$$$debugObject
    Write !,"Debug file "_debug.file
}

UDLText.Content:
/*
Method peek(number As %Integer) As %String [ CodeMode = expression ]
{
$EXTRACT(..streaminput,..stream.pos,..stream.pos+number-1)
    ;Set p=..stream.pos
    ;Quit $EXTRACT(..streaminput,p,p+number-1)
    ;Quit $EXTRACT(..streaminput,..stream.pos,..stream.pos+number-1)
    ;Quit ..peeked

}
*/

Method.Implementation:
;$$$DEBUGMethodBegin  
Do:..needsWScheck ..skipWhiteSpaceAndComments()

Set len=$LENGTH(String)
Set foundString=$$$peek(..stream,len)
If $$$UPPER(foundString)=String {
    Set found=1
} Else {
    Set found=0
}
;$$$DEBUGMethodEnd
Quit found

//#define UPPER(%x) $zconvert(%x,"U")
$$$DEBUGMethodBegin
;d ..skipWhiteSpaceAndComments()
Do:..needsWScheck ..skipWhiteSpaceAndComments()

Set ok=0
Set len=$LENGTH(StringToCheck)
Set peeked=$$$peek(..stream,len)
If $$$UPPER(peeked)=$$$UPPER(StringToCheck) {
    If $$$ElementIsObject(ParentElement) {
        Set value=..next(len)
        If value?1.P {
            Set atom=..newAtom("punctuation",value)
        } Else {
            Set atom=..newAtom(..#keywordAtomType,value)
        }
        Do ParentElement.AddPart(atom)
    }
    Set ok=1
}
$$$DEBUGMethodEnd
 Quit ok

$$$DEBUGMethodBegin
Do:..needsWScheck ..skipWhiteSpaceAndComments()

$$$DEBUG("checking string '"_StringToCheck_"' found '"_$ZCONVERT($$$peek(..stream,10),"O","JS")_"'")
Set ok=0
Set len=$LENGTH(StringToCheck)
Set peeked=$$$peek(..stream,len)
If $$$UPPER(peeked)=$$$UPPER(StringToCheck) {
    Set value=..next(len)
    If value?1.P {
        Set atom=..newAtom("punctuation",value)
    } Else {
        Set atom=..newAtom(..#keywordAtomType,value)
    }
    Do ParentElement.AddPart(atom)
    Set ok=1
}
$$$DEBUG("checking string '"_StringToCheck_"' ok="_ok)
$$$DEBUGMethodEnd
 Quit ok

$$$DEBUGMethodBegin
Set ok=0
If ..isStringInList(ListOfStrings,longestLen,.value) {
    If value?1.P {
        Set atom=..newAtom("punctuation",value)
    } Else {
        Set atom=..newAtom(..#keywordAtomType,value)
    }
    Do ParentElement.AddPart(atom)
    Set ok=1
    Set foundString=value
}
$$$DEBUGMethodEnd
Quit ok

$$$DEBUGMethodBegin
Do:..needsWScheck ..skipWhiteSpaceAndComments()

Set ch50=..stream.PeekToEol()
Set locate=$LOCATE(ch50,Regex,1,end)
If locate=1 {
    Set atom=..newAtom(ParentElement.type,..nextNotEOL(end-1))
    Do ParentElement.AddPart(atom)
    Set ok=1
} Else {
    Set ok=0
}
$$$DEBUGMethodEnd
Quit ok

$$$DEBUGMethodBegin Do:..needsWScheck ..skipWhiteSpaceAndComments()
Set len=$LENGTH(Punctuation) Set peeked=$$$peek(..stream,len) $$$DEBUG($$$debugFormat("addPunctuation looking for {Punctuation} found {$zconvert(peeked,""O"",""JSON"")}")) If $$$UPPER(peeked)=$$$UPPER(Punctuation) { Set foundString=..next(len) Set atom=..newAtom("punctuation",foundString) Do ParentElement.AddPart(atom) Set ok=1 } Else { Set ok=0 }
$$$DEBUGMethodEnd Quit ok

$$$DEBUGMethodBegin
Set next50=$$$peek(..stream,Length)
Set UPP50=$$$UPPER(next50)
If $LISTFIND(ListOfStrings,UPP50) {
    Set foundString=..next(Length)
    Set atom=..newAtom("punctuation",foundString)
    Do ParentElement.AddPart(atom)
    Set ok=1
} Else {
    Set ok=0
}
$$$DEBUGMethodEnd
Quit ok

    #define isWS(%x) $c(32,9,13,10,160)[%x
    $$$DEBUGMethodBegin

    If '..stopAtWhitespace {
        If ..stopAtEOL { 
            Set ws=$CHAR(32,9,160)
        } Else {
            Set ws=$CHAR(32,9,13,10,160)
        }
        ; leading whitespace and comments end up embedded in the next real object
        ; so you could end up with a returned object like this
        ; object={ 
        ;          type:"variable",
        ;         value:111,
        ;       comment:{
        ;                type:"comment",
        ;               value:"a comment",
        ;          whitespace:{
        ;                      type:"whitespace",
        ;                     value:"  "
        ;                     }
        ;          }                
        ;
        ;        
readNextLoop		
        ;Set ch10=$$$peek(..stream,10),ch=$EXTRACT(ch10,1)
        Set ch10=$EXTRACT(..streaminput,..stream.pos,..stream.pos+9),ch=$EXTRACT(ch10,1)
        ;If '..eof(),ws[ch Set ..whitespace=..newAtom("whitespace",..nextChars(.ws)) Goto readNextLoop
        If ws[ch,ch'="" Set ..whitespace=..newAtom("whitespace",..nextChars(.ws)) Goto readNextLoop
        If ..skipComments(.ch10) Set ..keyword="" Goto readNextLoop
        Set ..needsWScheck=0
    }

    $$$DEBUGMethodEnd 
    Quit

	$$$DEBUGMethodBegin
    $$$BNFPATH
    #dim a as %CSP.Broker
	Set subElement=##class(PXW.DEV.Element).%New()
	Set subElement.type="recover"

    Set matchcount=0 
	Set ok=0
	Set r=""
    $$$DEBUG("RECOVER START AT:"_$$$peek(..stream,20))
    ; find where we are now (pos) up to the point of failure (lastPos)
    While '..eof(),..stream.pos<..stream.lastPos,matchcount>=0 {
        If Match'="" {
            If $$$peek(..stream,1)=$EXTRACT(Match,1) Set matchcount=matchcount+1
            If $$$peek(..stream,1)=$EXTRACT(Match,2) Set matchcount=matchcount-1
            If matchcount>=0 {
                Set r=r_..next()
                Set ok=1
            }
        } Else {
            Set r=r_..next()
            Set ok=1
        }
    }
	If ok {
		Set atom=..newAtom("ERROR",r)
		Do subElement.AddPart(atom)
	}
    $$$DEBUG("RECOVER MID AT:"_$$$peek(..stream,20))


    ; now find from the point of failure up to the next recovery point (a mismatch of {}  or a specific char)
    Set ok=0,r=""
	While '..eof(),'..recoverStopAt(StopAtList),matchcount>=0 {
        If $$$peek(..stream,1)=$EXTRACT(Match,1) Set matchcount=matchcount+1
        If $$$peek(..stream,1)=$EXTRACT(Match,2) Set matchcount=matchcount-1
        If matchcount>=0 {
            Set r=r_..next()
            Set ok=1
        }
	}
	If ok {
		Set atom=..newAtom("ERROR",r)
		Do subElement.AddPart(atom)
		Do ParentElement.AddPart(subElement)
	}	
    $$$DEBUG("RECOVER END AT:"_$$$peek(..stream,20))
	$$$DEBUGMethodEnd
    ; recover always is true?
	Quit ok

Set stop=0
For i=1:1:$LISTLENGTH(StopAtList) {
    Set stopitem=$LISTGET(StopAtList,i)
    Set peek=$$$peek(..stream,$LENGTH(stopitem))
    If $$$UPPER(peek)=$$$UPPER(stopitem) {
        Set stop=1
    }
}
Quit stop

Set comment=""
If $$$ElementIsObject(..comment) {
    Set comment=..comment
    Set ..comment=""
} ElseIf $$$ElementIsObject(..whitespace) {
    If $$$ElementIsObject(..whitespace.comment) {
        Set comment=..whitespace.comment
        Set ..whitespace.comment=""
    }
}
Quit comment

	If ..%Iterator.%GetNext(.key,.value) {
        Set ..%Value=value
        Quit 1
    } Else { 
        Set ..%Value=""
        Quit 0
    }

    Set cls=ClassWild,escape=""
	If cls["%" {
		Set escape="\"
		Set cls=$REPLACE(cls,"%",escape_"%")
	}
	If cls["_" {
		Set escape=$GET(escape,"\")
		Set cls=$REPLACE(cls,"_",escape_"_")
	}
	Set cls=$REPLACE(cls,"*","%") ; make the selection a LIKE compatible thing

    Quit ..ListClassDetailsLike(cls,escape,listHidden,listGenerated)

    $$$DEBUGMethodBegin
    Kill parameters
	Set server=..AtelierSettings.ServerName 
	Set sql=""
	Set sql=sql_"SELECT cc.ClassType,cc.Name,to_char($piece(cd.TimeChanged,'.',1),'YYYY-MM-DD HH24:MI:SS') as TimeChanged"
    Set sql=sql_",cc.Super,cc.PrimarySuper,cc.ClassType as SubType "
	Set sql=sql_"	FROM %Dictionary.CompiledClass AS cc"
    Set sql=sql_" INNER JOIN %Dictionary.ClassDefinition AS cd ON cd.ID=cc.ID"
	Set sql=sql_"	WHERE 1=1"
	If $DATA(ClassLike) {
        Set sql=sql_"	  AND cc.name LIKE ?"
        Set parameters($INCREMENT(parameters))=ClassLike
	    If escape'="" {
            Set sql=sql_" ESCAPE ?"
            Set parameters($INCREMENT(parameters))=escape
	    }
    }
    If listHidden {
        ; 
    } Else {
        Set sql=sql_" AND cc.Hidden!=1"
    }

    If listGenerated {
        ; 
    } Else {
        Set sql=sql_" AND cc.GeneratedBy IS NULL"
    }

    For i=1:1:$LISTLENGTH(..ExcludeClassesLike) {
        Set exlike=$LISTGET(..ExcludeClassesLike,i)
        If exlike'="" {
            Set sql=sql_" AND (cc.name NOT LIKE ?"
            Set parameters($INCREMENT(parameters))=exlike
       	    If exlike["\" {
    		    Set sql=sql_" ESCAPE '\'"
            }
            Set sql=sql_")"
        }
    }

    Set qsc=##class(PXW.DEV.Dictionary.AtelierClient).query(server,sql,.obj,parameters...)
	If $$$ISERR(qsc) $$$ThrowStatus(qsc)
	Set rs=##class(PXW.DEV.Dictionary.AtelierRS).%New(obj)
    $$$DEBUGMethodEnd
	Quit rs

$$$DEBUGMethodBegin
;New %NS Set %NS=..Namespace.Name
Set NS=..Namespace.Name
Set fcn=..FullClassName(ClassName)
Set TimeStamp=$PIECE(TimeStamp,".",1) ; no dp
If (Parts="") || (Parts["GCD") {
    Set docache=0
    Set timechanged=$GET(^PXW.Cache("CDEF",NS,$$$UPPER(fcn),"GCD"))
    If timechanged="" Set docache=1
    If TimeStamp'="",TimeStamp]timechanged Set docache=1
    If docache {
        ;$$$LOG("Building "_ClassName_", "_TimeStamp_", "_timechanged)
        $$$DEBUG("Fetching from GCD DB_"_ClassName_" timechanged="_timechanged_" TimeStamp="_TimeStamp)
        Do ..CacheListClassDetails(fcn)
        Set ^PXW.Cache("CDEF",NS,$$$UPPER(fcn),"GCD")=$SELECT(TimeStamp'="":TimeStamp,1:1)
    }
}
If (Parts="") || (Parts["GMD") {
    Set docache=0
    Set timechanged=$GET(^PXW.Cache("CDEF",NS,$$$UPPER(fcn),"GMD"))
    If timechanged="" Set docache=1
    If timechanged="no kill" set docache=2,timechanged=""
    If TimeStamp'="",TimeStamp]timechanged Set docache=1
    If docache {
        $$$DEBUG("Fetching from GMD DB_"_ClassName_" timechanged="_timechanged_" TimeStamp="_TimeStamp)
        Kill:docache=1 ^PXW.Cache("CDEF",NS,$$$UPPER(fcn),"GMD")
        Do ..CacheListMethodDetails(fcn)
        Set ^PXW.Cache("CDEF",NS,$$$UPPER(fcn),"GMD")=$SELECT(TimeStamp'="":TimeStamp,1:1)
    }
}
If (Parts="") || (Parts["GPD") {
    Set docache=0
    Set timechanged=$GET(^PXW.Cache("CDEF",NS,$$$UPPER(fcn),"GPD"))
    If timechanged="" Set docache=1
    If TimeStamp'="",TimeStamp]timechanged Set docache=1
    If docache {
        Kill ^PXW.Cache("CDEF",NS,$$$UPPER(fcn),"GPD")
        $$$DEBUG("Fetching from GPD DB_"_ClassName_" timechanged="_timechanged_" TimeStamp="_TimeStamp)
        Do ..CacheListProperyDetails(fcn)
        Set ^PXW.Cache("CDEF",NS,$$$UPPER(fcn),"GPD")=$SELECT(TimeStamp'="":TimeStamp,1:1)
    }
}
If (Parts="") || (Parts["GAD") {
    Set docache=0
    Set timechanged=$GET(^PXW.Cache("CDEF",NS,$$$UPPER(fcn),"GAD"))
    If timechanged="" Set docache=1
    If TimeStamp'="",TimeStamp]timechanged Set docache=1
    If docache {
        Kill ^PXW.Cache("CDEF",NS,$$$UPPER(fcn),"GAD")
        $$$DEBUG("Fetching from GAD DB_"_ClassName_" timechanged="_timechanged_" TimeStamp="_TimeStamp)
        Do ..CacheListParameterDetails(fcn)
        Set ^PXW.Cache("CDEF",NS,$$$UPPER(fcn),"GAD")=$SELECT(TimeStamp'="":TimeStamp,1:1)
    }
}
If (Parts="") || (Parts["GID") {
    Set docache=0
    Set timechanged=$GET(^PXW.Cache("CDEF",NS,$$$UPPER(fcn),"GID"))
    If timechanged="" Set docache=1
    If TimeStamp'="",TimeStamp]timechanged Set docache=1
    If docache {
        $$$DEBUG("Fetching from GID DB_"_ClassName_" timechanged="_timechanged_" TimeStamp="_TimeStamp)
        Kill ^PXW.Cache("CDEF",NS,$$$UPPER(fcn),"GID")
        Do ..CacheListIndexDetails(fcn)
        Set ^PXW.Cache("CDEF",NS,$$$UPPER(fcn),"GID")=$SELECT(TimeStamp'="":TimeStamp,1:1)
    }
}
If (Parts="") || (Parts["GQD") {
    Set docache=0
    Set timechanged=$GET(^PXW.Cache("CDEF",NS,$$$UPPER(fcn),"GQD"))
    If timechanged="" Set docache=1
    If TimeStamp'="",TimeStamp]timechanged Set docache=1
    If docache {
        $$$DEBUG("Fetching from GQD DB_"_ClassName_" timechanged="_timechanged_" TimeStamp="_TimeStamp)
        Kill ^PXW.Cache("CDEF",NS,$$$UPPER(fcn),"GQD")
        Do ..CacheListQueryDetails(fcn)
        Set ^PXW.Cache("CDEF",NS,$$$UPPER(fcn),"GQD")=$SELECT(TimeStamp'="":TimeStamp,1:1)
    }
}
$$$DEBUGMethodEnd

; builds an array ^PXW.Cache("CDEF",%NS,classname,methodname,parentclassname)
Set classname=$PIECE(MethodId,"||",1)
Set methodname=$PIECE(MethodId,"||",2)

Set overrides=""
If ..GetClassDetails(classname,,.supers) {
    ; supers=,"~PXW.DEV.COS.Parser~PXW.DEV.Parser~%Library.RegisteredObject~%Library.Base~%Library.SystemBase~"
    For i=1:1:$LENGTH(supers,",") {
        Set scn=$PIECE(supers,",",i)
        If ..GetMethodDetails(scn,methodname,,.origin),origin'="" {
            Set overrides=origin
            Quit
        }
    }
}
Quit overrides

; builds an array ^PXW.Cache("CDEF",%NS,classname,methodname,parentclassname)
Set classname=$PIECE(PropertyId,"||",1)
Set propertyname=$PIECE(PropertyId,"||",2)

Set overrides=""
If ..GetClassDetails(classname,,.supers) {
    ; supers=,"~PXW.DEV.COS.Parser~PXW.DEV.Parser~%Library.RegisteredObject~%Library.Base~%Library.SystemBase~"
    For i=1:1:$LENGTH(supers,",") {
        Set scn=$PIECE(supers,",",i)
        If ..GetPropertyDetails(scn,propertyname,,,,.origin),origin'="" {
            Set overrides=origin
            Quit
        }
    }
}
Quit overrides

Set fslist=""
Set pos=1
Set ok=(FormalSpec'="")
While ok {
    Set mode="",name="",type="",typeparams="",default=""

    ; mode
    If $EXTRACT(FormalSpec,pos)?1P {
        Set mode=$EXTRACT(FormalSpec,pos)
        Set pos=pos+1
    }

    ; name
    Set start=pos
    If $EXTRACT(FormalSpec,pos)="%" { Set pos=pos+1 }
    While $EXTRACT(FormalSpec,pos)?1AN { 
        Set pos=pos+1 
    }
    Set name=$EXTRACT(FormalSpec,start,pos-1)

    ; type
    If $EXTRACT(FormalSpec,pos)=":" {
        Set pos=pos+1,start=pos
        If $EXTRACT(FormalSpec,pos)="%" { Set pos=pos+1 }
        While ($EXTRACT(FormalSpec,pos)?1AN) || ($EXTRACT(FormalSpec,pos)=".") { 
            Set pos=pos+1 
        }
        Set type=$EXTRACT(FormalSpec,start,pos-1)
        Set type=..FullClassName(type,$p(ThisClass,".",1,*-1))
        If $EXTRACT(FormalSpec,pos)="(" {
            Set pos=pos+1
            ; type parameters
            Set tpok=1
            While tpok {
                Set start=pos
                Set tpname="",tpvalue=""
                While $EXTRACT(FormalSpec,pos)'="", $EXTRACT(FormalSpec,pos)'="=" {
                    Set pos=pos+1
                }
                Set tpname=$EXTRACT(FormalSpec,start,pos-1)
                Set dok=1,instring=0
                Set pos=pos+1,start=pos
                While dok {
                    If instring=0,$EXTRACT(FormalSpec,pos)="""" {
                        Set instring=1
                        Set pos=pos+1
                    } ElseIf instring=1,$EXTRACT(FormalSpec,pos)="""" {
                        Set pos=pos+1
                        If $EXTRACT(FormalSpec,pos)="""" {
                            Set pos=pos+1
                        } Else {
                            Set instring=0
                        }
                    } Else {
                        Set pos=pos+1
                    }
                    ; end of default
                    Set dok=1
                    If $EXTRACT(FormalSpec,pos)="" Set dok=0
                    If instring=0,$EXTRACT(FormalSpec,pos)=")" Set dok=0
                    If instring=0,$EXTRACT(FormalSpec,pos)="," Set dok=0
                }
                Set tpvalue=$EXTRACT(FormalSpec,start,pos-1)                    
                Set typeparams=typeparams_$LISTBUILD(tpname)_$LISTBUILD(tpvalue)

                If $EXTRACT(FormalSpec,pos)="," Set pos=pos+1
                Set tpok=0
                If $EXTRACT(FormalSpec,pos)'=")" Set tpok=1
            }
            Set pos=pos+1 ; move past the )
        }
    }

    ; default
    If $EXTRACT(FormalSpec,pos)="=" {
        Set pos=pos+1,start=pos
        Set dok=1,instring=0
        While dok {
            If instring=0,$EXTRACT(FormalSpec,pos)="""" {
                Set instring=1
                Set pos=pos+1
            } ElseIf instring=1,$EXTRACT(FormalSpec,pos)="""" {
                Set pos=pos+1
                If $EXTRACT(FormalSpec,pos)="""" {
                    Set pos=pos+1
                } Else {
                    Set instring=0
                }
            } Else {
                Set pos=pos+1
            }
            ; end of default
            Set dok=1
            If $EXTRACT(FormalSpec,pos)="" Set dok=0
            If instring=0,$EXTRACT(FormalSpec,pos)="," Set dok=0
        }
        Set default=$EXTRACT(FormalSpec,start,pos-1)
    }

    Set fslist=fslist_$LISTBUILD($LISTBUILD(name,type,mode,default)_typeparams)

    ; next
    Set ok=0
    If $EXTRACT(FormalSpec,pos)="," {
        Set ok=1
        Set pos=pos+1
    }
}
Quit fslist

If ClassName="" Quit 0
If PropertyName="" Quit 0

Set found=0
; find the type of the property
If ..GetPropertyDetails(ClassName,PropertyName,,,.propertytype) {
    ; find if that class has a parameter that matches
    If ..GetParameterDetails(propertytype,ParameterName,,.parameterorigin) {
        Set found=1
        Set SourceClass=parameterorigin
    } Else {
        ; look to the propertyclass of the main class
        If ..GetClassDetails(ClassName,,,,,,,.propertyclass) {
            If ..GetParameterDetails(propertyclass,ParameterName,,.parameterorigin) {
                Set found=1
                Set SourceClass=parameterorigin                           
            }
        }
    }
} 

Quit found

    If ClassName="" Quit ""
    If Name="" Quit ""

	Set ufield=$$$UPPER(Name)
	; sometimes fields have quotes around
	If $EXTRACT(ufield,1)="""",$EXTRACT(ufield,*)="""" Set ufield=$EXTRACT(ufield,2,*-1)

	Set found=..GetMethodDetails(ClassName,Name,.returntype,.origin,.stub,.FormalSpecParsed,.codemode,.FormalSpec)

    ; if the return type is not set see if this was derived from some other thing
    If found,returntype="" {
        ; stub is undocumented but it seems to be "SourceName.MethodName.SourceType (i=index,a=property)"
        Set stype=$PIECE(stub,".",3)
        Set smethod=$PIECE(stub,".",2)
        Set sname=$PIECE(stub,".",1)
        If stype="i" {
            Do ..GetIndexDetails(ClassName,sname,.typeclass)
            If typeclass="" Set typeclass="%Compiler.Type.Index"
            Do ..GetMethodDetails(typeclass,smethod,.returntype,.sorigin)
            If returntype="%Library.ObjectHandle",sorigin="%Compiler.Type.Index" {
                Set returntype=ClassName
            }
        } If stype="q" {
            Do ..GetQueryDetails(ClassName,sname,.typeclass)
            Do ..GetMethodDetails(typeclass,smethod,.returntype)
        }
    } 

    ; if the method returns the type of its origin then this method returns itself
    ; eg, classmethod OpenNamespace returns PXW.DEV.Dictionary.CodeInterface 
    ;     then ##class(PXW.DEV.Dictionary.ClassDefintionObject).OpenNamespace(x) can be considered returning a ClassDefintionObject
    If origin'="",returntype=origin Set returntype=ClassName

    ; if the method returns an object handle its probably %Open or %New or an IndexOpen or something that returns itself
    If returntype="%Library.ObjectHandle" {
        If origin="%Library.SystemBase" { 
            Set returntype=ClassName
        } ElseIf origin="%Library.Persistent" {
            Set returntype=ClassName
        }
    }

    If Name="%ConstructClone" Set returntype=ClassName
    Quit returntype

    ;New %NS Set %NS=..Namespace.Name
    Set NS=..Namespace.Name
    Set table=SQLTableName
    ;i table'[".",'$d(OwningClassName) break
    If table'[".",OwningClassName'="" {
        Set schema=$PIECE(OwningClassName,".",1,*-1)
        Set schema=$TRANSLATE(schema,".","_")
        Set table=schema_"."_table
    } 

    ; use a local var as a cache, so that the next time a different process looks at
    ; for the table name it might have been set up
    If '$DATA(%PXWSQLName($$$UPPER(table))) {
        Set classname=$GET(^PXW.Cache("CDEFSQL",NS,$$$UPPER(table)))
        If classname="" {
            Do ..CacheListClassDetails(,table)
          	Set classname=$GET(^PXW.Cache("CDEFSQL",NS,$$$UPPER(table)))
        }
        Set %PXWSQLName($$$UPPER(table))=classname
    } Else {
        Set classname=%PXWSQLName($$$UPPER(table))
    }
	Quit classname


    ; simple formula to start with
    ;Set cn=$PIECE(SQLProcName,"_",1,*-1)
    ;Set cn=$TRANSLATE(cn,"_",".")
    ;Set classname=..GetClassNameFromTableName(cn) ; might not be a table but we can treat as such
    ;Set mn=$PIECE(SQLProcName,"_",*)
    ;Set method=mn

    ;New %NS Set %NS=..Namespace.Name
    Set NS=..Namespace.Name
    Set schema=$$$UPPER($PIECE(SQLProcName,".",1))
    Set name=$$$UPPER($PIECE(SQLProcName,".",2))
    If schema'="",name'="" {
        ; use a local var as a cache, so that the next time a different process looks
        ; for the table name it might have been set up
        If '$DATA(%PXWSQLProc(schema,name)) {
            Set data=$GET(^PXW.Cache("CDEFPROC",NS,schema,name))
            If data="" {
                ; when can we refresh cache? 
                ; tricky since we can guess the class its in but not really be sure
                Set classname=..GetClassNameFromTableName(schema_"."_$PIECE(name,"_",1),"")
                If classname'="" {
                    Do ..CacheIfNecessary(classname,"")
                    Set data=$GET(^PXW.Cache("CDEFPROC",NS,schema,name))
                }
            }
            Set classname=$LISTGET(data,1),method=$LISTGET(data,2)
            Set %PXWSQLProc(schema,name)=$LISTBUILD(classname,name)
        } Else {
            Set data=$GET(^PXW.Cache("CDEFPROC",NS,schema,name))
            Set classname=$LISTGET(data,1),method=$LISTGET(data,2)
        }
    } Else {
        Set classname="",method=""
    }
	Quit classname

