	If $$$UPPER(..type)=uType {
		If '$ISOBJECT($GET(OutputList)) { 
			Set OutputList=##class(%Library.ListOfObjects).%New()
		}
		Do OutputList.Insert($THIS)
	}
	For i=1:1:..partsCount() {
