	Set pos=..pos
	Set found=$EXTRACT(..input,pos,pos+number-1)
	Set ..pos=pos+number
	Set ..col=..col+number
	If $FIND(found,..eolChar) {
		Set crcount=$LENGTH(found,..eolChar)
		Set ..line=..line+crcount-1
		Set ..col=$LENGTH($PIECE(found,..eolChar,*))
