    For i=1:1:max {
        Set cookie=array(i)
        Do %session.Set(key_i,cookie)
    }
    Do %session.Set(key,max)
} Else {
    Set max=..NetRequest.GetFullCookieList(.array)
    For i=1:1:max {
        Set cookie=array(i)
        Set ^||session(key_i)=cookie
    }
    Set ^||session(key)=max
}
; must be a good request so don't need password any more
