/********************************
  THE SHOW PLANS SECTION, most of this is just stripping out the XML from the "XML"
********************************/

Method.Implementation:
#dim attE,nameE as PXW.DEV.BNF.Element
Set modname=..GetAttributeValue(element,"name")
If modname'="" {
    Set aname="module_"_modname
    Do ..wrapElementHTML(element,"<hr><h3 id='"_aname_"'>Module "_modname_"</h3>","")
    Set ..modules(aname)=""
    Do ..ClearAllButContent(element)
} Else {
    Do ..wrapElementHTML(element,"<hr><pre>","</pre>")
}
Quit ""

#dim attE,nameE as PXW.DEV.BNF.Element
Set modname=..GetAttributeValue(element,"name")
If modname'="" {
    ;do element.write()
    Set aname="subquery_"_modname
    Do ..wrapElementHTML(element,"<hr><h3 id='"_aname_"'>Subquery "_modname_"</h3>","")
    Set ..modules(aname)=""
    Do ..ClearAllButContent(element)
} Else {
    Do ..wrapElementHTML(element,"<hr><pre>","</pre>")
}
Quit ""

Set key="",val=""
For {
    Set attE=element.findNextElement(.key)
    Quit:key=""

    If attE.IsElement,$PIECE(attE.type,":",1)="Attribute" {
        Set nameE=attE.partsGetAt(1)
        Set valueE=attE.partsGetAt(3)
        If nameE.ToString(0)=name {
            Set val=valueE.ToString(0)
        }
    }
}
Set val=$TRANSLATE(val,"'""","") ; attribute values are wrapped in quotes
Quit val

#dim part as PXW.DEV.Particle
#dim atom as PXW.DEV.Atom
#dim ele as PXW.DEV.Element
Set akey=""
For {
    Set part=element.partsGetNext(.akey)
    Quit:akey=""

    If part.IsAtom {
        Do element.partsRemove(akey)
    } Else {
        Set ele=part
        If $PIECE(ele.type,":",1)'="Content" {
            Do element.partsRemove(akey)
        }
    }        
}

/*
Element=TableIndex PXW.DEV.BNF.Element @80
.Element=SchemaName PXW.DEV.BNF.Element @18
..type=SchemaName:/Plan/ReadIndex/TableIndex/SchemaName
.. Data_Assets
.type=punctuation:/Plan/ReadIndex/TableIndex
. .
.Element=TableName PXW.DEV.BNF.Element @160
..type=TableName:/Plan/ReadIndex/TableIndex/TableName
.. Asset
.type=punctuation:/Plan/ReadIndex/TableIndex
. .
.Element=IndexName PXW.DEV.BNF.Element @205
..type=IndexName:/Plan/ReadIndex/TableIndex/IndexName
.. Code
*/
$$$DEBUGMethodBegin

Set schemaE=element.findFirstElementByType("SchemaName",0)
Set tableE=element.findFirstElementByType("TableName",0)
Set indexE=element.findFirstElementByType("IndexName",0)
If $ISOBJECT(schemaE),$ISOBJECT(tableE) {
    Set table=schemaE.ToString(0)_"."_tableE.ToString(0)
    Do ..wrapElementHTML(schemaE,"<a class="_$$$classProgramName_" href="""_..HREFToClass(table)_""">","</a>")
    Do ..wrapElementHTML(tableE,"<a class="_$$$classProgramName_" href="""_..HREFToClass(table)_""">","</a>")
}
If $ISOBJECT(schemaE),$ISOBJECT(tableE),$ISOBJECT(indexE) {
    Set table=schemaE.ToString(0)_"."_tableE.ToString(0)
    Set index=indexE.ToString(0)
    Do ..wrapElementHTML(indexE,"<a class='"_$$$classObjectMember_"' href="""_..HREFToClass(table,index)_""">","</a>")
    Set class=..ClassServer.GetClassNameFromTableName(table)
    If ..ClassServer.GetIndexDetails(class,index,,,.properties) {
        Set list=""
        Do element.findElementsXPath("IndexKeys/IndexKeysGiven/IndexKey/IndexKeyName/PropertyName",.list)
        Do element.findElementsXPath("IndexKeys/IndexKeysGiven/IndexKey/IndexKeyName/AliasProperty/PropertyName",.list)
        If $ISOBJECT(list) {
            For i=1:1:list.Count() {
                Set item=list.GetAt(i).ToString(0)
                If item'="" {
                    Set givenidents($$$UPPER(item))=2 ; GIVEN = 
                }
            }
        }
        Set list=""
        Do element.findElementsXPath("IndexKeys/IndexKeysLooping/IndexKeyWithRange/IndexKey/IndexKeyName/PropertyName",.list)
        Do element.findElementsXPath("IndexKeys/IndexKeysLooping/IndexKeyWithRange/IndexKey/IndexKeyName/AliasProperty/PropertyName",.list)
        If $ISOBJECT(list) {
            For i=1:1:list.Count() {
                Set item=list.GetAt(i).ToString(0)
                If item'="" {
                    Set givenidents($$$UPPER(item))=1 ; GIVEN RANGE
                }
            }
        }

        If $DATA(givenidents) {
           ; for all the keys on the index work out which ones are given and highlight them
           Set html="",sep=""
           For i=1:1:$LENGTH(properties,",") {
               Set item=$PIECE(properties,",",i)
               If item'="",$GET(givenidents($$$UPPER(item)))=2 {
                   Set html=html_sep_"<b>"_$$$HTMLENCODE(item)_"</b>"
               } ElseIf item'="",$GET(givenidents($$$UPPER(item)))=1 {
                   Set html=html_sep_"<u>"_$$$HTMLENCODE(item)_"</u>"
               } Else {
                   Set html=html_sep_$$$HTMLENCODE(item)
               }
               Set sep=","
           }
           If html'="" {
               Do ..wrapElementHTML(indexE,"","<span class="_$$$classNarrative_"> /* "_html_" */ </span>")
           }
       } Else {
           If properties'="" {
               Do ..wrapElementHTML(indexE,"","<span class="_$$$classNarrative_"> /* "_$$$HTMLENCODE(properties)_" */ </span>")
           }
       }
    }
}

$$$DEBUGMethodEnd
Quit ""

$$$DEBUGMethodBegin
If '$DATA(..xrefCounts(..This)) {
    ; I think that in most cases its faster to call this once and
    ; gather all the counts in one go rather than many smaller calls
    ; to the getcount method
    Do ##class(PXW.Xref.Queries).GetCountsSummary(%NS,..ThisType,..This,.results)
    Merge ..xrefCounts(..This)=results
} 
If ItemKey2="",CallType="" {
    Set count=+$GET(..xrefCounts(..This))
} ElseIf CallType="" {
    Set ik2=$$$SQLUPPER(ItemKey2)
    Set count=+$GET(..xrefCounts(..This,ik2))
} Else {
    Set ik2=$$$SQLUPPER(ItemKey2),ct=$$$SQLUPPER(CallType)
    Set count=+$GET(..xrefCounts(..This,ik2,ct))
}
$$$DEBUGMethodEnd
Quit count

$$$DEBUGMethodBegin
Set input=element.ToString()
If input["::=" {
   	Set parser=##class(PXW.DEV.BNF.Compilers.BNF1safe).%New()
} Else {
    ; try different parser
    Set parser=##class(PXW.DEV.BNF.Compilers.BNF2safe).%New()
}    
Set parser.stream=##class(PXW.DEV.InputStream).NewString(element.ToString())
Set subElement=##class(PXW.DEV.Element).%New()
If parser.File(subElement) {
	Do ..wrapElementBNF1Loop(subElement)
    Do element.partsClear()
    Do element.AddPart(subElement)
} Else {

}
$$$DEBUGMethodEnd

 $$$DEBUGMethodBegin
 If element.type="Definition" {
     Set labatom=element.FirstAtom()
     Set lab=labatom.value
     If lab=..HiliteLabel {
         Do ..wrapAtomHTML(labatom,"<a name='Bookmark' class="""_$$$classHilite_""">","</a>")
         If ..HilitePlus'="" Set ..HiLiteLine=labatom.line+..HilitePlus
     } Else {
         Set labname=$TRANSLATE("LAB"_..ThisMethod_lab,"$^%_","")
         Do ..wrapAtomHTML(labatom,"<a id="""_labname_""" class="""_$$$classLabelDef_""" name="""_labname_""">","</a>")
         Do ..AddToIndex(..ThisMethod_" : "_lab,"XDataName",labname)
     }
 }

If element.type="Call" {
     Set atom=element.FirstAtom()
     Set lab=atom.value
     Set labname=$TRANSLATE("LAB"_..ThisMethod_lab,"$^%_","")
     Do ..wrapAtomHTML(atom,"<a onclick='HiliteElement("""_labname_""");'  class="""_$$$classLabel_""" href=""#"_labname_""">","</a>")
 }
 Set akey=""
 For  {
     Set a=element.partsGetNext(.akey)
     Quit:akey=""

     If a.IsElement {
         Do ..wrapElementBNF1Loop(a)
     }
 }
 $$$DEBUGMethodEnd

