/*
method writeCDEF(element As PXW.DEV.BNF.Elements.ClassDefinition) AS PXW.DEV.BNF.Compilers.elementHandler(Type="")
{

    q ""
}
*/

Method.Implementation:
; known variable
$$$DEBUGMethodBegin 
Set variablename=element.ToStringAtomsOnly(0)

; variable could be something like {*} or {field}  so the name above (using atoms only) will not find anything
; don't worry about that at the moment!
If variablename'="",$ISOBJECT(..Analyser) {        
    ; when working out a type use the #DIM type if there is one
    ;Set classname=$GET(..Analyser.DimmedTypes(variablename))
    ;If classname="" Set classname=$GET(..Analyser.VariablesTypes(variablename))
    Set classname=$GET(..Analyser.VariablesTypesElement(+element))
    If classname'="" Do ..FollowObjectChainForType(element,classname)

    ; treat %parameter("xxx") as a parameter
    If ..Analyser.CodeMode="OBJECTGENERATOR",variablename="%parameter" {
        Set arrayE=element.findFirstElementByType(("ArrayParameterList"),0)
        If $ISOBJECT(arrayE) {
            Set parameter=..Analyser.SimplifySubscripts(arrayE)
            ; is the paremeter a string
            If parameter?1"""".AN1"""" {
                Do ..wrapElementHTML(arrayE,"<a href="""_..HREFToClass(..This,$TRANSLATE(parameter,"""",""))_""">","</a>")
            }
        }
    }
}
$$$DEBUGMethodEnd
Quit ""

#dim strElement as PXW.DEV.Element
#dim atom as PXW.DEV.Atom

$$$DEBUGMethodBegin
Set variablename=element.ToStringAtomsOnly(0)
; add the hiliting function to the first atom only
Set atom=element.FirstAtom()
Set cssclass=$$$classVariableSet
If $ISOBJECT(..Analyser),..Analyser.IsParameterVariable(variablename) Set cssclass=$$$classVariableParameterSet

if $ISOBJECT(..Analyser),$d(..Analyser.VariablesTypesElement(+element)) {
    ; don't overwrite any previous warnings tool tip
    set atom=element.FirstAtom()
    if '$d(..Analyser.ElementWarnings(+atom)) {
        Do ..wrapAtomHTML(atom,"<span title=""Type is "_..Analyser.VariablesTypesElement(+element)_""" class="""_cssclass_""" varid="""_variablename_""" onclick=""HiliteSets('"_variablename_"');"">","</span>")
    }
} else {
    Do ..wrapAtomHTML(atom,"<span class="""_cssclass_""" varid="""_variablename_""" onclick=""HiliteSets('"_variablename_"');"">","</span>")
}

If $ISOBJECT(..Analyser),$DATA(..Analyser.stringVarsElement(+element)) {
    Set value=..Analyser.stringVarsElement(+element)
    If value'="" {
        Set strElement=..Analyser.stringVarsElement(+element,"element")
        ; try and format it so its similar to the format in the source code
        Set formatted="",line=0
        For i=1:1:strElement.partsCount() {
            Set atom=strElement.partsGetAt(i)
            If atom.line>line {
                If line>0 {
                    Set formatted=formatted_$CHAR(13)
                }
            }
            Set line=atom.line ; always update the line, its possible to go backwards!
            Set formatted=formatted_atom.value
        }
        Do ..wrapElementHTML(element,"","<span title="""_$ZCONVERT(formatted,"O","HTML")_""" class='hiddencopy' onclick=""copyTextToClipboard('"_$ZCONVERT($ZCONVERT(formatted,"O","JS"),"O","HTML")_"');"">copy</span>")
    }
}
$$$DEBUGMethodEnd
Quit ""

#dim a as %Dictionary.ClassDefinition
$$$DEBUGMethodBegin
Set macroatom=element.partsGetAt(2)
If $ISOBJECT(macroatom) {
    Set name=macroatom.ToString(0)
    If name'="" {
        If $ISOBJECT(..Analyser) {
            ;zw ..Analyser,name
            If '$DATA(..Analyser.DefinedMacros(name)) {
                Do ..wrapAtomHTML(macroatom,"<a class="""_$$$classProgramLabel_""" href="""_..HREFToInclude(,element.ToString(0))_""">","</a>")
            } Else {
                Do ..wrapAtomHTML(macroatom,"<span class="""_$$$classProgramLabel_""" title'Local macro'>","</span>")
            }
        } Else {
            Do ..wrapAtomHTML(macroatom,"<a class="""_$$$classProgramLabel_""" href="""_..HREFToInclude(,element.ToString(0))_""">","</a>")
        }
    }
}
$$$DEBUGMethodEnd
Quit ""

$$$DEBUGMethodBegin
;#define
Set keywordatom=element.FirstAtom()
Set defineE=element.findFirstElementByType("CosDirectiveDefine",0)
If '$ISOBJECT(defineE) {
    Set defineE=element.findFirstElementByType("CosDirectiveDefonearg",0)
}
If $ISOBJECT(defineE) {
    If ..ThisType="INC" {
        Set nameE=defineE.findFirstElementByType("CosDirectiveDefineName",0)
        If $ISOBJECT(nameE) {
            Set name=nameE.ToString(0)
            ;Set count=##class(PXW.Xref.Queries).GetCount(%NS,"INC",..This,name)
            Set count=..GetXrefCount(name,"")
            Set anchor="anchor"_name_nameE.type
            ;Set ..ThisMethod=name
            If ..BookMark'="",$$$UPPER(name)=$$$UPPER(..BookMark) {
                ;d ..wrapElementHTML(element,"<a name='bookmark'>","</a>")
                Set anchor="bookmark" ;
                Do ..wrapElementHTML(nameE,"<span class="""_$$$classHilite_""">","</span>")
            } Else {
                Do ..wrapElementHTML(nameE,"<span class="""_$$$classProgramLabel_""">","</span>")
            }
            Do ..AddToIndex(name,"MAC",anchor)
            Do ..wrapElementHTML(element,"<a name="""_anchor_""">","</a>") ; anchor goes before the member (ie before the comment)

            Set menu="<div class="""_$$$classLensMenu_"  nocopy"">"
            Set menu=menu_"<a class="""_$$$classLensOption_""" href="""_##class(PXW.Tools.DEV.Xref).HREFTo("INC",..This,name)_""">Xref ("_count_") </a>"
            Set menu=menu_"</div>"
            Do ..wrapAtomHTML(keywordatom,menu,"")
        }
    } Else {
        Set nameE=defineE.findFirstElementByType("CosDirectiveDefineName",0)
        If $ISOBJECT(nameE) {
            Do ..wrapElementHTML(nameE,"<span class="""_$$$classProgramLabel_""">","</span>")
        }
    }
}
$$$DEBUGMethodEnd
Quit ""

#dim chainE as PXW.DEV.Element
#dim atom as PXW.DEV.Atom
$$$DEBUGMethodBegin  
Set classname="%SYSTEM"
Set key="",firstAtomOfClass="",lastAtomOfClass="",chainE=""
For  {
    Set atom=element.partsGetNext(.key)
    Quit:key=""
    If $PIECE(atom.type,":",1)="ObjectMemberIdentifier" {
        Set:firstAtomOfClass="" firstAtomOfClass=atom
        Set lastAtomOfClass=atom
        Set classname=classname_"."_atom.value
    } ElseIf atom.type="ObjectChain" {
        Set chainE=atom
    }
}
If $ISOBJECT(firstAtomOfClass),$ISOBJECT(lastAtomOfClass) {
    Do ..wrapAtomHTML(firstAtomOfClass,"<a class="""_$$$classProgramName_""" href="""_..HREFToClass(classname)_""">","")
    Do ..wrapAtomHTML(lastAtomOfClass,"","</a>")
}
Do:$ISOBJECT(chainE) ..FollowObjectChainForType(chainE,classname)
$$$DEBUGMethodEnd
Quit ""

#dim labatom,anchorAtom as PXW.DEV.Atom

$$$DEBUGMethodBegin
Set labatom=element.FirstAtom()
Set lab=labatom.value
Set ..ThisLabel=lab
Set anchorAtom=labatom.getComment()
If anchorAtom="" Set anchorAtom=labatom
If lab=..HiliteLabel {
    If anchorAtom=labatom {
        Do ..wrapAtomHTML(anchorAtom,"<a name='Bookmark' class="""_$$$classHilite_""">","</a>")
    } Else {
        Do ..wrapAtomHTML(anchorAtom,"<a name='Bookmark'>","</a>")
        Do ..wrapAtomHTML(labatom,"<a class="""_$$$classHilite_""">","</a>")
    }
    If ..HilitePlus'="" Set ..HiLiteLine=labatom.line+..HilitePlus
} Else {
    Set labname=..ThisMethod_lab
    Set anchor=$TRANSLATE("LAB"_labname,"$^%_","")
    Do ..wrapAtomHTML(labatom,"<span class="""_$$$classLabelDef_""" id="""_anchor_"SPAN"" >","</span>") ; not sure why the ID needs SPAN on the end...
    Do ..wrapAtomHTML(anchorAtom,"<a name="""_anchor_""" >","</a>") 
    Do ..AddToIndex(labname,"Label",anchor)
    /*
    */
}
$$$DEBUGMethodEnd
Quit ""

$$$DEBUGMethodBegin
Set lab=element.ToString(0)
If lab["^" {
    Do ..wrapElementHTML(element,"<a class="""_$$$classLabel_""" href="""_..HREFToRoutine(lab)_""">","</a>")
} Else {
    Set labname=$TRANSLATE("LAB"_..ThisMethod_lab,"$^%_","")
    Do ..wrapElementHTML(element,"<a class="""_$$$classLabel_""" href=""#"_labname_""">","</a>")
}
$$$DEBUGMethodEnd
Quit ""

$$$DEBUGMethodBegin
Set stringE=element.findFirstElementByType("String")
If $ISOBJECT(stringE) {
    Set atom=stringE.FirstAtom()
    If $ISOBJECT(atom) {
        Do ..wrapAtomHTML(atom,"<a class="_$$$classProgramName_" href="""_..HREFToPython(atom.value)_""">","</a>")
        Set atom.type="pythonimport"
    }
}       
$$$DEBUGMethodEnd
Quit ""

$$$DEBUGMethodBegin
If $ISOBJECT(..Analyser) {
    Set expressionE=element.findFirstElementByType("Expression")
    If $ISOBJECT(expressionE) {
        Set simple=..Analyser.SimplifyExpression(expressionE) 
        ; its a string, so its a hard coded method name
        If $EXTRACT(simple,1)="""",$EXTRACT(simple,*)="""" {
            Set mname=$TRANSLATE(simple,"""","")
            Do ..wrapElementHTML(expressionE,"<a href="""_##class(PXW.Tools.DEV.Xref).HREFTo("CLS","*",mname)_""">","</a>")
        }
    }
}
$$$DEBUGMethodEnd
Quit ""

$$$DEBUGMethodBegin
Set setting=0
If element.type="GlobalRefSet" Set setting=1
Set fullrefE=element.findFirstElementByType("GlobalRefFull",0)
If fullrefE="" Set fullrefE=element.findFirstElementByType("GlobalRefSpecial",0)
If $ISOBJECT(fullrefE) {
    ; On a global clicking on the ^ will take directly to the XREF since we don't
    ; have any other details about the global at the moment.
    ; Clicking on the name of the global highlights it like a regular variable
    Set globalElement=fullrefE.findFirstElementByType("GlobalName",0)
    Set upa=fullrefE.FirstAtom() ; ^ is always at the start
    Set namea=globalElement ;.ToStringAtomsOnly() 
    Set subsE=fullrefE.findFirstElementByType("SubscriptParameterList",0),subs=""
    If $ISOBJECT(subsE),$ISOBJECT(..Analyser) Set subs=..Analyser.SimplifySubscripts(subsE)
    If $ISOBJECT(namea) {
        Do ..wrapAtomHTML(upa,"<a class="""_$$$classGlobalSet_""" href="""_##class(PXW.Tools.DEV.Xref).HREFTo("GBL",namea.ToStringAtomsOnly(0),subs)_""">","</a>")
        Set varname="GLOBAL"_namea.ToStringAtomsOnly(0)
        If setting {
            Do ..wrapAtomHTML(namea,"<span class="""_$$$classGlobalSet_""" varid="""_varname_""" onclick=""HiliteSets('"_varname_"');"">","</span>")
                } Else {
            Do ..wrapAtomHTML(namea,"<span class="""_$$$classGlobal_""" fetchid="""_varname_""" onclick=""HiliteSets('"_varname_"');"">","</span>")
        }
    }
} Else {
    ; not sure what we can do with naked refs here (other than make them stand out as a bad thing)
}
$$$DEBUGMethodEnd
Quit ""

$$$DEBUGMethodBegin
Set method=element.ToString(0)
; method in ..this class
If method?1".."1.E {
    Do ..wrapElementHTML(element,"<a class="_$$$classProgramLabel_" href="""_..HREFToClass(..This,$PIECE(method,"..",2))_""">","</a>")
} Else {
    Do ..wrapElementHTML(element,"<a class="_$$$classProgramLabel_" href="""_..HREFToClass($PIECE(method,".",1,*-1),$PIECE(method,".",*))_""">","</a>")
}
$$$DEBUGMethodEnd
Quit ""

