UDLText.Content:
/*
Method writeSQLWithClause(element As PXW.DEV.BNF.Elements.SQL) As PXW.DEV.BNF.Compilers.elementHandler(Type="WithClause")
{
    $$$DEBUGMethodBegin
    Do ..wrapElementHTML(element,"<span class='SQLSection'>","</span>")
    $$$DEBUGMethodEnd
    Quit ""
}
*/

Method.Implementation:
#define colname(%cn) $TR($$$UPPER(%cn),$c(34),"")
; work out what this column is called
; either from the AS clause or if its just referencing 
; a single column, that column is the name
; then create an ID for it so it can be highlighted
#dim col as PXW.DEV.Element
$$$DEBUGMethodBegin
Set col=element
Set classtxt="class='SQLSection'"
Set colname="colxxxx"

Set asclause=col.findFirstElementByType("AsClause",0)
If $ISOBJECT(asclause) {
    Set colnameE=asclause.findFirstElementByType("ColumnName",0)
    If $ISOBJECT(colnameE) {
        Set colname="col"_$$$UPPER(colnameE.ToString(0))
        Do ..wrapElementHTML(colnameE,"<span varid="""_$$$colname(colname)_""" onclick=""HiliteSets('"_$$$colname(colname)_"');"">","</span>")
    }
} Else {
    Kill colrefs
    ; if the column is just a reference to another column
    Do col.findElementsByType("ColumnReference",.colrefs,2)
    If $ISOBJECT($GET(colrefs)),colrefs.Count()=1 {
        Set colnameE=colrefs.GetAt(1).findFirstElementByType("ColumnName",0)
        If $ISOBJECT(colnameE) {
            Set colname="col"_$$$UPPER(colnameE.ToString(0))
        }
    }
}
If ..BookMark'="",$$$colname(colname)=$$$colname("col"_..BookMark) {
    Set classtxt="class="""_$$$classHilite_""""
}
Do ..wrapElementHTML(col,"<span "_classtxt_" defid="""_$$$colname(colname)_""">","</span>")        
$$$DEBUGMethodEnd
Quit ""

$$$DEBUGMethodBegin
; find the alias name of the entire join
Do ..findElementsSkipSub(element,"AliasName",.list)
If $ISOBJECT(list) {
    Set aliasname="alias"_list.GetAt(1).ToString(0)
    Do ..wrapElementHTML(element,"<span  defid="""_$$$UPPER(aliasname)_""" class='SQLSection'>","</span>")    
} Else {
    Do ..wrapElementHTML(element,"<span class='SQLSection'>","</span>")
}
$$$DEBUGMethodEnd
Quit ""

    #dim ele as PXW.DEV.Element
    If Object.type=Type {
        If '$ISOBJECT($GET(OutputList)) { 
            Set OutputList=##class(%Library.ListOfObjects).%New()
        }
        Do OutputList.Insert(Object)				
    }
	For i=1:1:Object.partsCount() {
		Set ele=Object.partsGetAt(i)
		If ele.IsElement {
            If ele.type="SelectCommand" || ele.type="WithCommand" {
				; do nothing for select
			} Else {
				Do ..findElementsSkipSub(ele,Type,.OutputList)
			}
		}
	}

#dim sqlanalyse as PXW.DEV.BNF.Analyse.SQL
#define colname(%cn) $TR($$$UPPER(%cn),$c(34),"")

$$$DEBUGMethodBegin
If $ISOBJECT(..SqlProgramAnalyser) {
    Set sqlanalyse=$GET(..SqlProgramAnalyser.SelectCommandAnalysis(+element))
} Else {
    Set sqlanalyse=""
}
If sqlanalyse="" {
    ; certain types of subquery are not being covered by the program analyse yet, so treat separately for now
    Set sqlanalyse=##class(PXW.DEV.BNF.Analyse.analyser).NewForLanguage(..ThisType,"SQL")
    Set sqlanalyse.ClassServer=..ClassServer
    Set sqlanalyse.This=..This
    Do sqlanalyse.checkElement(element)
}
Set cref=""
While sqlanalyse.NextColumnReference(.cref,.fulltable,.fieldname) {
    Set aliasNameE=cref.findFirstElementByType("AliasName",1) ; hmm, in a group, can we promote in bnf?
    Set columnNameE=cref.findFirstElementByType("ColumnName",0)
    If $ISOBJECT(..SqlProgramAnalyser) {
        If fulltable'="",$DATA(..SqlProgramAnalyser.withReferences(fulltable)) {
            Set fulltable=""
        }
    }
    If fulltable'="" {
        Do ..FollowImplicitJoins(cref,fulltable)
    } Else {
        Set colname="col"_$$$UPPER(fieldname)
        If fulltable'="" {
            Do ..FollowImplicitJoins(cref,fulltable)
        } Else {
            Do ..wrapElementHTML(columnNameE,"<span class="""_$$$classObjectMember_""" title='still unable to determine class, possibly because of subquery' fetchid="""_$$$colname(colname)_""" onclick=""HiliteSets('"_$$$colname(colname)_"');"">","</span>")
        }
    }
    If $ISOBJECT(aliasNameE) {
        Set aliasname="alias"_aliasNameE.ToString(0)
        Set atom=aliasNameE.FirstAtom()
        Do ..wrapAtomHTML(atom,"<span class='SQLTableAlias' title='show alias usage' fetchid="""_$$$UPPER(aliasname)_""" onclick=""HiliteSets('"_$$$UPPER(aliasname)_"');"">","</span>")
    }
}    
$$$DEBUGMethodEnd
Quit ""

;Set sqlanalyse=##class(PXW.DEV.BNF.Analyse.SQL).%New(..ClassServer)
#dim sqlanalyse as PXW.DEV.BNF.Analyse.SQL
$$$DEBUGMethodBegin
Set sqlanalyse=##class(PXW.DEV.BNF.Analyse.analyser).NewForLanguage(..ThisType,"SQL")
Set sqlanalyse.ClassServer=..ClassServer
Set sqlanalyse.This=..This
Do sqlanalyse.checkElement(element)
Set columnNameE=""
While sqlanalyse.NextColumnReference(.columnNameE,.fulltable,.fieldname,.colnum) {
    If fulltable'="" {
        Do ..wrapElementHTML(columnNameE,"<a title=""Col "_colnum_""" class="""_$$$classObjectMember_""" href="""_..HREFToSQLTable(fulltable,columnNameE.ToString(0))_""">","</a>")
        Set colidx(colnum)=columnNameE.ToString(0)
    } Else {
        ; should always be a name
    }
}  
; only one of these xpath searches will find anything
; if they do find something it attempts to map to the columns above
Kill values
Do element.findElementsXPath("InsertMethod/InsertValuesList/UpdateValues/SqlExpression",.values)
Do element.findElementsXPath("InsertMethod/InsertMultirow/SelectCommand/SelectList/SelectSublist/DerivedColumn/SqlExpression",.values)
If $ISOBJECT(values) {
    For i=1:1:values.Count() {
        Set valueE=values.GetAt(i)
        Do ..wrapElementHTML(valueE,"<span class=""SQLSection"" title=""Col "_i_" ("_$GET(colidx(i))_")"">","</span>")
        ;do ..wrapElementHTML(valueE,"<span class="""_$$$classLensOption_""">"_$g(colidx(i))_"=</span><span class=""SQLSection"" title=""Col "_i_" ("_$g(colidx(i))_")"">","</span>")
    }
}
$$$DEBUGMethodEnd
Quit ""

;Set sqlanalyse=##class(PXW.DEV.BNF.Analyse.SQL).%New(..ClassServer)
#dim sqlanalyse as PXW.DEV.BNF.Analyse.SQL
$$$DEBUGMethodBegin
Set sqlanalyse=##class(PXW.DEV.BNF.Analyse.analyser).NewForLanguage(..ThisType,"SQL")
Set sqlanalyse.ClassServer=..ClassServer
Set sqlanalyse.This=..This
Do sqlanalyse.checkElement(element)
Set columnNameE=""
While sqlanalyse.NextColumnReference(.columnNameE,.fulltable,.fieldname) {
    If fulltable'="" {
        Do ..wrapElementHTML(columnNameE,"<a class="""_$$$classObjectMember_""" href="""_..HREFToSQLTable(fulltable,columnNameE.ToString(0))_""">","</a>")            
    } Else {
        ; should always be a name
    }
}    
$$$DEBUGMethodEnd
Quit ""

;Set sqlanalyse=##class(PXW.DEV.BNF.Analyse.SQL).%New(..ClassServer)
#dim sqlanalyse as PXW.DEV.BNF.Analyse.SQL
$$$DEBUGMethodBegin
Set sqlanalyse=##class(PXW.DEV.BNF.Analyse.analyser).NewForLanguage(..ThisType,"SQL")
Set sqlanalyse.ClassServer=..ClassServer
Set sqlanalyse.This=..This
Do sqlanalyse.checkElement(element)
Set columnNameE=""
While sqlanalyse.NextColumnReference(.columnNameE,.fulltable,.fieldname) {
    If fulltable'="" {
        Do ..wrapElementHTML(columnNameE,"<a class="""_$$$classObjectMember_""" href="""_..HREFToSQLTable(fulltable,columnNameE.ToString(0))_""">","</a>")            
    } Else {
        ; should always be a name
    }
}    
$$$DEBUGMethodEnd
Quit ""

$$$DEBUGMethodBegin
Set direct=element
If $ISOBJECT(direct) {
    Set tablenameE=direct.findFirstElementByType("TableName",0)
    If $ISOBJECT(tablenameE) {
        Set tablename=tablenameE.ToString(0)
        ; is it a reference to a WITH?
        If tablename'="", tablename'[".", $ISOBJECT(..SqlProgramAnalyser), $GET(..SqlProgramAnalyser.withReferences(tablename))'="" {
            Set aliasname="alias"_tablename
            Do ..wrapElementHTML(tablenameE,"<span class='SQLTableAlias' title='show alias usage' fetchid="""_$$$UPPER(aliasname)_""" onclick=""HiliteSets('"_$$$UPPER(aliasname)_"');"">","</span>")
        } Else {
            ; Carry through bookmark. 
            ; This is so that if there is something like 
            ;  SELECT X FROM VIEW 
            ; and the view says 
            ;  SELECT * FROM OTHERVIEW 
            ; we carry through that X is going to be the interesting thing in the OTHERVIEW
            Do ..wrapAtomHTML(tablenameE,"<a class="_$$$classProgramName_" href="""_..HREFToSQLTable(tablename,..BookMark)_""">","</a>")
        }
    }
}    
$$$DEBUGMethodEnd
Quit ""

