/*
method writeSQL(element As PXW.DEV.BNF.Elements.SQL) AS PXW.DEV.BNF.Compilers.elementHandler(Type="")
{

    q ""
}
*/

Method.Implementation:
#dim atom as PXW.DEV.Atom

$$$DEBUGMethodBegin
Set akey=""
For  {
    Set atom=element.partsGetNext(.akey)
    Quit:akey=""

    If atom.IsAtom {
        Set type=$PIECE(atom.type,":",1)
        If type="Identifier" {
            Set varname=atom.value
            Set cssclass=$$$classVariable
            If $ISOBJECT(..Analyser),..Analyser.IsParameterVariable(varname) Set cssclass=$$$classVariableParameter
            If $ISOBJECT(..PythonAnalyser),..PythonAnalyser.IsParameterVariable(varname) Set cssclass=$$$classVariableParameter
            Do ..wrapAtomHTML(atom,"<span class="""_cssclass_""" fetchid="""_varname_""" onclick=""HiliteSets('"_varname_"');"">","</span>")
        } 
    }
}    
$$$DEBUGMethodEnd
Quit ""

UDLText.Content:
/*
method writePY(element As PXW.DEV.BNF.Elements.Python) AS PXW.DEV.BNF.Compilers.elementHandler(Type="")
{

    q ""
}
*/

Method.Implementation:
#dim atom as PXW.DEV.Atom

$$$DEBUGMethodBegin
If (ParentElement.type="ThisObject") || (ParentElement.type="ThisObjectSet") {
    Set this=ParentElement.findFirstElementByType("ThisObjectSelf",0) ; ..property
    If $ISOBJECT(this) {
        Set objectchain=this.findFirstElementByType("ObjectChainNoDot",0)
    } Else {
        Set this=ParentElement.findFirstElementByType("ThisObjectThis",0) ; $this.property
        If $ISOBJECT(this) {
            Set objectchain=this.findFirstElementByType("ObjectChain",0)
        }
    }
} ElseIf (ParentElement.type="ThisObjectDirectProperty") || (ParentElement.type="ThisObjectDirectPropertySet") {
    Set objectchain=ParentElement.findFirstElementByType("ObjectChainItem",0) ; i%property
} Else {
    Set objectchain=ParentElement.findFirstElementByType("ObjectChain",1) ; var.property
}
Set toclass=StartClassName
Set path=""
While $ISOBJECT(objectchain) {

    Set propertyatom="",akey=""
    ; the objectchain has the "." and the name
    For  {
        Set atom=objectchain.partsGetNext(.akey)
        Quit:akey=""

        If atom.IsAtom,atom.value'="." {
            Set propertyatom=atom
        }
    }
    ; If we have an analyser then use it's results otherwise work it out the old way:
    ; The old way is to build a "path" and put that into the href and work out the
    ; final class when the link is clicked.
    if $ISOBJECT(..Analyser) {
        Do ..wrapAtomHTML(propertyatom,"<a class="""_$$$classObjectMember_""" href="""_..HREFToClass(toclass,propertyatom.value)_""">","</a>")
        Set toclass=$GET(..Analyser.VariablesTypesElement(+objectchain))
    } else {
        Set path=path_"."_propertyatom.value
        Do ..wrapAtomHTML(propertyatom,"<a class="""_$$$classObjectMember_""" href="""_..HREFToClass(toclass,path)_""">","</a>")
    }
    Do ..writeCOSParameterChecks(StartClassName,path,objectchain)

    Set objectchain=objectchain.findFirstElementByType("ObjectChain",0) 
}

$$$DEBUGMethodEnd

	#dim a as PXW.DEV.Atom
	#dim e as PXW.DEV.Element

    $$$DEBUGMethodBegin
    If '$ISOBJECT($GET(AtomList)) Set AtomList=##class(%Library.ListOfObjects).%New()

 	Set akey=""
	Set list=""
    If Element.partsCount()=1 {
        Set single=1
    } Else {
        Set single=0
    }
	If 'single {
        ;Set list=list_$lb(Element.type)
    }
	For  {
		Set a=Element.partsGetNext(.akey)
		Quit:akey=""

        If a.IsElement {
            Set list=list_..flattenlist(a,.AtomList)
        } ElseIf $PIECE(a.type,":",1)="punctuation" {
            ; forget punctuation for the timebeing
            ;Set list=list_$lb($lb("punctuation",a.value))
            ;do AtomList.Insert(a)

            ; Unless the thing truely IS punctuation. Due to complexity deep in the parser $this counts as punctuation, which is wrong.
            If a.value'?1.P {
                Set list=list_$LISTBUILD($LISTBUILD("keyword",a.value))
                Do AtomList.Insert(a)
            }

        } Else {
            Set list=list_$LISTBUILD($LISTBUILD($PIECE(a.type,":",1),a.value))
            Do AtomList.Insert(a)
        }		
	}
	If 'single {
        ;Set str=str_"}"
    }
    $$$DEBUGMethodEnd
	Quit list

UDLText.Content:
/*
/// Here is line 1 of the description
/// Here is line 2 
/// below is a comment block that is not related 
Method wrapCommentBlock(Element As PXW.DEV.Element, preValue As %String = "", postValue As %String = "", subAtom As PXW.DEV.Atom)
{
    $$$DEBUGMethodBegin
    Set isFirstCall=0
    ; atom is what is being wrapped
    ; subatom is what we are currently processing
    ;i '$d(subAtom) { s subAtom=Element.partsGetAt(1),isFirstCall=1 }
    If '$DATA(subAtom) { Set subAtom=Element.FirstAtom(),isFirstCall=1 }
    If 
    ; this is going it do a load of inserts of the comment block as PRE the first atom
    Do ..wrapElementHTML(Element,preValue,"")
	If $ISOBJECT(subAtom.whitespace) {
		Do ..wrapCommentBlock(Element,,,subAtom.whitespace)
        ; clear the whitespace as we are don't want it out again
        Set subAtom.whitespace=""
	}
	If $ISOBJECT(subAtom.comment) {
		Do ..wrapCommentBlock(Element,,,subAtom.comment)
        ; clear the comment as we are don't want it out again
        Set subAtom.comment=""
	}


    ; don't forget ALL of this is PRE the atom, including the post value!
    Do ..wrapAtomHTML(Element,postValue,"")
    $$$DEBUGMethodEnd
}
*/

/*/// Does this need things like the PRE tags?
Property Embedded As %Boolean [ InitialExpression = 0 ];
*/

Method.Implementation:
If Name'="" {
    Set data=$LISTBUILD(Error)
    Set ..IndexError("Name",Name)=data
}
Quit $$$OK

Method.Description:
Call in a loop using byref parameters to get the index out
while x.NextIndexItem(.name,.type) {

}

Method.Implementation:
;$$$DEBUGMethodBegin
;If ..WriteMode {
	Write html
	;s %outputhtml=$g(%outputhtml)_html
	;i $l(%outputhtml)>100000 w %outputhtml s %outputhtml=""
	;s ^PXW("out",$i(^PXW))=html
;} Else {
;	Set ..htmlout=..htmlout_html	
;}
;$$$DEBUGMethodEnd

	$$$DEBUGMethodBegin
    Do ..processSpecificElement(.element)

	;For i=1:1:+$GET(..pre(+element)) Do ..output($GET(..pre(+element,i)))
	Set e=+element
	;If $DATA(..pre(e),n) {
	;	Set out=""
	;	For i=1:1:n Set out=out_..pre(e,i)
	;	Do ..output(.out)
	;}
	If $DATA(..pre(e),out) {
		Do ..output(out)
	}

	Set akey=""
	For {
		; nexting through because the element count may change if the outputter wants to add/remove elements as we go
		;Set a=element.partsGetNext(.akey)
		set akey=$$$ElementPartsNext(element,akey,a)
		Quit:akey=""

		If a.IsElement {
			Do ..writeElement(.a)
		} Else {
			Do ..writeAtom(.a)
		}
	}

	;For i=+$GET(..post(+element)):-1:1 Do ..output($GET(..post(+element,i)))
	;If $DATA(..post(e)) {
	;	Set out=""
	;	For i=n:-1:1 Set out=out_..post(e,i)
	;	Do ..output(.out)
	;}
	If $DATA(..post(e),out) {
		Do ..output(out)
	}

	$$$DEBUGMethodEnd

	$$$DEBUGMethodBegin
	If $ISOBJECT(atom.whitespace) {
		Do ..writeAtom(atom.whitespace,"<span class=whitespace>","</span>")
	}
	If $ISOBJECT(atom.comment) {
		Do ..writeAtom(atom.comment,"<span class='"_$$$classComment_"'>","</span>")
	}

	; add hilite on whitespace (OR ANYTHING) that is NOT going over more than 1 line
	If ..HiLiteLine'="",atom.line=..HiLiteLine,atom.value'[$CHAR(13) {
		If ..BookMark?1"+"1.N {
			Set ..BookMark=""
			Set preValue="<a id=Bookmark></a><span class='hilite'>"_preValue
			Set postValue=postValue_"</span>"
		} Else {
			Set preValue="<span class='hilite'>"_preValue
			Set postValue=postValue_"</span>"
		}
	}

    ; some very basic atoms we can deal with in a common way across all languages
 	Set type=$PIECE(atom.type,":",1)
	If type="Keyword" {
		Do ..wrapAtomHTML(.atom,"<span class="""_$$$classKeyword_""">","</span>")
	} ElseIf type="CDEFKeyword" {
		Do ..wrapAtomHTML(.atom,"<span class="""_$$$classProgramKeyword_""">","</span>")
	} ElseIf type="String" {
		Do ..wrapInnerAtomHTML(.atom,"<span class="""_$$$classString_""">","</span>")
	} ElseIf type="Number" {
		Do ..wrapAtomHTML(.atom,"<span class="""_$$$classNumber_""">","</span>")
	} ElseIf type="ERROR" {
		Do ..wrapAtomHTML(.atom,"<span class="""_$$$classError_""">","</span>")
		Do ..AddToIndexError(..ThisMethod,atom.value)
	}
	Do:..showPaths ..wrapAtomHTML(atom,"<span title="""_+atom_":"_atom.type_""">","</span>")

	Set a=+atom
    Set out=preValue_$ZCONVERT(atom.start,"O","HTML")_$GET(..pre(a))_$ZCONVERT(atom.value,"O","HTML")_$GET(..post(a))_$ZCONVERT(atom.end,"O","HTML")_postValue

	Write out
	$$$DEBUGMethodEnd

	Do ..HREFFrom(.inc,.cc,.macro,.debug)

	If inc["*" Do ..WriteIncludeDir(inc) Quit
    If inc="",cc'="" {
		Set inc=..GetIncludeFileName(.macro)
    }
    If inc'="" {
	    Do ..WriteInclude(inc,macro,debug,.scratch)
    }

	Do ..HREFFrom(.inc,.cc,.macroname)
    If inc="",cc'="" {
        Set cs=##class(PXW.DEV.Dictionary.ClassDefinitionObject).OpenNamespace(%NS)
		Set macroname=$PIECE(macroname,"(",1)
		If macroname?1"$$$" Set macroname=$PIECE(macroname,"$$$",2)
        If cs.GetMacroLocation(cc,macroname,.inc,.line) {
            ;w !,"Macro "_macro_" for "_cc_" found "_inc
            If $PIECE(inc,".",*)="inc" Set inc=$PIECE(inc,".",1,*-1)
        } Else {
        }
    }
	Quit inc


	If $ISOBJECT($GET(scratch)) {
		Set output=scratch
		While output.NextIndexItemByName(.name,.type,.anchor,.error) {
				If error="" {
					Write "<a class='"_"CDEF"_type_"' href=#"_anchor_">"_..EscapeHTML(name)_"</a>"
				} Else {
					Write "<a class='"_$$$classWarning_"' href=#"_anchor_">"_..EscapeHTML(name)_"</a>"
				}
		}
		Write "<hr>"
	}
    Write "<span class=button href=# onclick='MakeStringsInteresting(); '>Strings</span>"

	Set href=##super()
	Set sep="&"
