        Write "OK"
    } Else {
        Do $SYSTEM.Status.DecomposeStatus(sc,.err)
		;w "<pre>" zw err w "</pre>"
        ;s code=$g(err(1,"code"))
        Set caller=$GET(err(1,"caller"))
        Set txt=..EscapeHTML(err(1))
        If caller'="" {
			Set alink="<a class='"_$$$classLabel_"' href="""_##class(PXW.Tools.DEV.Routine).HREFTo(caller)_""">"_..EscapeHTML(caller)_"</a>"
            If txt[caller {
				Set txt=$REPLACE(txt,caller,alink)
			} Else {
				Set txt=txt_" goto: "_alink
			}
        } 
        Write "<pre style='color:red;'>" Write txt Write "</pre>"	
    }

Set rs=##class(PXW.Tools.Queries).SelectToolsForNamespaceFunc(%NS)
While rs.%Next() {
	Set classname=rs.%Get("ClassName")
	Set headform=##class(%Dictionary.MethodDefinition).%OpenId(classname_"||WriteHeadForm")
	If $ISOBJECT(headform) {
		Set order=$SELECT(classname?1"PXW.Tools"1.E:1,1:2)
		Set index(order,classname)=classname
	}
}
Set k1="",k2=""
For  {
	Set k1=$ORDER(index(k1))
	Quit:k1=""

	For  {
		Set k2=$ORDER(index(k1,k2),1,classname)
		Quit:k2=""
		Try {
			Do $CLASSMETHOD(classname,"WriteHeadForm",..%ClassName(1))
		} Catch e {
			Do ..WriteStatus(e.AsStatus())
		}
	}
}
Quit ""

Write "<div id='toolsMainTLRContainer'>"
    ; page
    Write "<div id='toolsMainTLR'>"
        ; top
        Write "<div id='toolsMainTop'>"
            Write "<div>"
            Try {
                Do ..WriteMainTop(.scratch)
            } Catch e {
                Do ..WriteStatus(e.AsStatus())
            }
            Write "</div>"
        ; /top
        Write "</div>"
        ; main
        ; left
        Write "<div id='toolsMainLeft'>"
            Write "<h2>"_..GetMainLeftTitle()_"</h2>"
            Write "<div>"
            Try {
                Do ..WriteMainLeft(.scratch)
            } Catch e {
                Do ..WriteStatus(e.AsStatus())
            }
            Write "</div>"
        Write "</div>"
        ; /left
        ; right
        Write "<div id='toolsMainRight'>"
            Write "<h2>"_..GetMainRightTitle()_"</h2>"
            Write "<div>"
            Try {
                Do ..WriteMainRight(.scratch)
            } Catch e {
                Do ..WriteStatus(e.AsStatus())
            }
            Write "</div>"
        ; /right
        Write "</div>"

        ;foot
        Write "<div id='toolsMainFoot'>"
            ;w "<div>"
            Try {
                Do ..WriteMainFoot(.scratch)
            } Catch e {
                Do ..WriteStatus(e.AsStatus())
            }
            ;w "</div>"
        ;/foot
        Write "</div>" 
    ;/page
    Write "</div>"
Write "</div>"

