        +----------------------------------------------+
    */
	#toolsHead form fieldset { display:inline; border:none; }
	#toolsHead legend { display: none;}
    #toolsHead {
        margin:10px;
        padding: 10px;
        border-radius: 20px;
        border:2px solid var(--glowColour);
        box-shadow:
            inset 0 0 10px var(--glowColour), 
            0 0 10px var(--glowColour);       
    }

    #toolsTitle {
        margin:10px;
        padding: 10px;
        border-radius: 20px;
        border:2px solid var(--glowColour);
        box-shadow:
            inset 0 0 10px var(--glowColour), 
            0 0 10px var(--glowColour);       
    }

    #toolsMainBodyNav {
        margin:10px;
        padding: 10px;
