Method.Implementation:
$$$DEBUGMethodBegin
$$$DEBUG("Build:"_Namespace_":"_Type_":"_SearchName)
Kill ^||PXWXrefBuild
Set sc=$$$OK
Try {
	; if the name has a * that means do everything starting with that string, not true wildcard, just counts as a package
	; * is valid on its own (it means build all)
	Set buildmany=(SearchName["*")
	Set package=$SELECT(buildmany:$PIECE(SearchName,"*",1),1:"")
	If buildmany=1 {
		Set status=##class(PXW.Xref.BuildStatus).%New()
		Set status.RequestNamespace=Namespace
		Set status.RequestType=Type
		Set status.RequestSearchName=SearchName
		Set status.RequestForce=Force
		Do status.Start()
		$$$ThrowOnError(status.%Save())
	}
	Set rs=##class(%Library.ResultSet).%New(..%ClassName(1)_":"_"SelectTypes")
	Set sc=rs.Execute(Namespace,Type)
	Set useTheForce=Force,noDelete=0
	While rs.%Next() {
		Set typ=rs.%Get("Type")

		; do not let anything continue if there is a delete going on
		; This is for when we are being impatient and starting multiple processes off at the same time
		If $DATA(status) {
			Set status.CurrentlyBuilding="Waiting for purge "_Namespace_"||"_typ
			$$$ThrowOnError(status.%Save())
		}

		Lock +^PXWBuild(Namespace_"||"_typ)			
		try {
			If Force,buildmany {
				If $DATA(status) {
					Set status.CurrentlyBuilding="Purging Analysis data: "_Namespace_","_typ_","_package
					$$$ThrowOnError(status.%Save())
				}
				Set:$$$ISOK(sc) sc=..DeleteAnalysisCalledByTypeKey1Package(Namespace,typ,package)

				If $DATA(status) {
					Set status.CurrentlyBuilding="Purging Xref data: "_Namespace_","_typ_","_package
					$$$ThrowOnError(status.%Save())
				}
				Set:$$$ISOK(sc) sc=..DeleteCalledByTypeKey1Package(Namespace,typ,package)

				If $DATA(status) {
					Set status.CurrentlyBuilding="Purging LastUpdate data: "_Namespace_","_typ_","_package
					$$$ThrowOnError(status.%Save())
				}
				Set:$$$ISOK(sc) sc=..DeleteLastUpdateCalledByTypeKey1Package(Namespace,typ,package)
				; We have purged the lastupdate table so no need to force now.
				; Which means we could kick off a Force on *, THEN build PXW package on a second process (because we are impatient)
				; Then when the * build gets to PXW it will see that its already been done!
				Set useTheForce=0,noDelete=1
			}
		} catch e {
			set sc=e.AsStatus()
		}
		Lock -^PXWBuild(Namespace_"||"_typ)

		if $$$ISOK(sc) {
			Set builderClass=rs.%Get("Builder")
			If builderClass'="" {
				Set interface=##class(PXW.DEV.Dictionary.CodeInterface).%OpenId(rs.%Get("ID"))
				If $DATA(status) {
					Set status.CurrentlyBuilding="Searching "_Namespace_" : "_typ_" : "_SearchName
					$$$ThrowOnError(status.%Save())
				}
				Set rs2=interface.List(SearchName)
				While rs2.%Next() {
					Set timechanged=rs2.%Get("TimeChanged")
					Set name=rs2.%Get("Name")
					Set ^||PXWXrefBuild(interface.%Id(),$INCREMENT(count))=$LISTBUILD(typ,name,timechanged,builderClass)
				}
			}
		}
	}

	If $$$ISOK(sc) {
		Set:$DATA(status) status.Total=$GET(count)
		Set iid=""
		For  {
			Set iid=$ORDER(^||PXWXrefBuild(iid))
			Quit:iid=""
			Set interface=##class(PXW.DEV.Dictionary.CodeInterface).%OpenId(iid)
			Set key=""
			For  {
				Set key=$ORDER(^||PXWXrefBuild(iid,key),1,data)
				Quit:key=""
				Set $LISTBUILD(typ,name,timechanged,builderClass)=data
				If builderClass'="" {
					If $DATA(status) {
						Set status.CurrentlyBuilding=Namespace_" : "_typ_" : "_name
						$$$ThrowOnError(status.%Save())
					}
					Set bs=..BuildIfNecessary(interface,Namespace,typ,name,timechanged,builderClass,useTheForce,noDelete,DebugBuild)
					If bs=1 {
						Set:$DATA(status) status.TotalBuilt=status.TotalBuilt+1
					} ElseIf bs="" {
						Set:$DATA(status) status.TotalSkipped=status.TotalSkipped+1
					} Else {
						Set:$DATA(status) status.TotalErrors=status.TotalErrors+1
					}
				}
			}
		}
	}
} Catch except {
	Set sc=except.AsStatus()
}

If $DATA(status) {
	If $$$ISOK(sc) {
		Set status.CurrentlyBuilding=""
	}
	Set status.Status=sc
	Do status.End()
	$$$ThrowOnError(status.%Save())
}
$$$DEBUG("Build:"_Namespace_":"_Type_":"_SearchName_":COMPLETE")
$$$DEBUGMethodEnd
Quit sc

#dim builder as PXW.Xref.Builder
$$$DEBUGMethodBegin
$$$DEBUG("BuildIfNecessary:"_Namespace_":"_Type_":"_Name_", NoDelete="_NoDelete)
$$$DEBUG("Storage:"_$STORAGE_",%atoms="_$GET(%atoms)) 
Set savesc=""
Set built=""
Set text=""

; check this is already building so we can skip
Set locked=1
Lock +^PXWBuild(Namespace_"||"_Type_"||"_Name):0 Else  Set locked=0
If 'locked Quit ""

Try {
	Set builder=$SYSTEM.OBJ.New(BuilderClass)
	Set LastUpdate=##class(PXW.Xref.LastUpdated).OpenOrNew(Namespace,Type,Name)
	If Force || LastUpdate.NeedsUpdate(TimeChanged) {
		Set zh=$ZHOROLOG
		Try {
			Set sc=CodeInterface.Load(Name,.text)
		} Catch e {
			Set sc=e.AsStatus()
		}
		If $$$ISOK(sc) {
			If 'NoDelete {
				Do ..DeleteAnalysisCalledByTypeKey1(Namespace,Type,Name)
				Do ..DeleteCalledByTypeKey1(Namespace,Type,Name)
			}
			If 'DebugBuild $$$DEBUGPause
			Set sc=builder.Build(Namespace,Name,text)
			If 'DebugBuild $$$DEBUGResume
		}
		If $$$ISOK(sc) {
			Do LastUpdate.%SetModified(1) ; because the lastupdate table is cleared via SQL as part of the build so ensure it saves again
			Set LastUpdate.LastUpdate=TimeChanged
			Set LastUpdate.BuildStatus=sc
			Set LastUpdate.BuiltAt=$ZDATETIME($HOROLOG,3)
			Set LastUpdate.CheckedAt=LastUpdate.BuiltAt
			Set LastUpdate.BuildProcessTime=$ZHOROLOG-zh
			$$$DEBUGSC(savesc,LastUpdate.%Save())
			Set built=1
		} Else {
			Do LastUpdate.%SetModified(1)
			Set LastUpdate.LastUpdate=""
			Set LastUpdate.BuildStatus=sc
			Set LastUpdate.CheckedAt=$ZDATETIME($HOROLOG,3)
			Set LastUpdate.BuildProcessTime=$ZHOROLOG-zh
			$$$DEBUGSC(savesc,LastUpdate.%Save())
			Set built=0
			$$$DEBUG("BuildIfNecessary:"_Namespace_":"_Type_":"_Name_":ERROR")
		}
	} Else {
		If 'Force {
			Set built=""
		}
		Set LastUpdate.CheckedAt=$ZDATETIME($HOROLOG,3)
		$$$DEBUGSC(savesc,LastUpdate.%Save())
		Set:$$$ISERR(savesc) built=0
	}
} Catch e {
	Lock -^PXWBuild(Namespace_"||"_Type_"||"_Name)
	Throw e
}
Lock -^PXWBuild(Namespace_"||"_Type_"||"_Name)

$$$DEBUGMethodEnd
Quit built

$$$DEBUGMethodBegin $$$DEBUG("Deleting:"_NameSpace_":"_ItemType_":"_ItemKey1) Set jrnsts=$$CURRENT^%NOJRN() Do $SYSTEM.SQL.Util.SetOption("AutoCommit",0,.acsts) Do DISABLE^%NOJRN Set sc=$$$OK If $$$ISOK(sc) { &SQL(DELETE %NOLOCK FROM PXW_Xref.AnalysisData WHERE (NameSpace=:NameSpace) AND (ItemType=:ItemType) AND (ItemKey1=:ItemKey1)) If SQLCODE<0 $$$DEBUGSC(sc,$$$ERROR(5001,%msg)) }
Do $SYSTEM.SQL.Util.SetOption("AutoCommit",acsts) Do:jrnsts ENABLE^%NOJRN
$$$DEBUGMethodEnd Quit sc

$$$DEBUGMethodBegin $$$DEBUG("Deleting:"_NameSpace_":"_CalledByType_":"_CalledByKey1) Set jrnsts=$$CURRENT^%NOJRN() Do $SYSTEM.SQL.Util.SetOption("AutoCommit",0,.acsts) Do DISABLE^%NOJRN Set sc=$$$OK If $$$ISOK(sc) { &SQL(DELETE %NOLOCK FROM PXW_Xref.Data WHERE NameSpace=:NameSpace AND CalledByType=:CalledByType AND CalledByKey1=:CalledByKey1) If SQLCODE<0 $$$DEBUGSC(sc,$$$ERROR(5001,%msg)) }
If $$$ISOK(sc) { &SQL(DELETE %NOLOCK FROM PXW_Xref.LastUpdated WHERE NameSpace=:NameSpace AND ItemType=:CalledByType AND ItemKey1=:CalledByKey1) If SQLCODE<0 $$$DEBUGSC(sc,$$$ERROR(5001,%msg)) } Do $SYSTEM.SQL.Util.SetOption("AutoCommit",acsts) Do:jrnsts ENABLE^%NOJRN
$$$DEBUGMethodEnd Quit sc

Set isrunning=0
Lock +^PXW.Xref.BuildStatus.Proc(PID):0 
Set locked=$TEST
If locked {
   Lock -^PXW.Xref.BuildStatus.Proc(PID)
} else {
    Set isrunning=1
}
Quit isrunning

Set sc=$$$OK 
Set codetype=..#CodeType
If codetype'="" {
    Set sc=##class(PXW.DEV.Dictionary.CodeTypeIndex).RegisterType("XrefBuilder",codetype,..%ClassName(1))
}
Quit sc

;i ItemKey2["Variables" zw ItemType,ItemKey1,ItemKey2
$$$DEBUG("Saving COS "_ItemType_","_ ItemKey1_","_ItemKey2_","_CalledByCommand)

; for xref to classes set the full spec of the class - maybe a new method needed for CLS and others
; * is a special case where we know the method but not the class (eg $classmethod)
Set ik1=ItemKey1,save=1
If ik1="*" {
	; star is special case
} ElseIf ik1?1"%Exception."1.E {
	; %Exception package does not seem to pull inherited methods into compiled class definition
	; so allow these through without check
} ElseIf ItemType="CLS" {
	Set ik1=..ClassServer.FullClassName(ItemKey1,$PIECE(..CalledByClassName,".",1,*-1))
	If '..ClassServer.GetPropertyDetails(ik1,ItemKey2)
	, '..ClassServer.GetMethodDetails(ik1,ItemKey2)
	, '..ClassServer.GetParameterDetails(ik1,ItemKey2)
	, '..ClassServer.GetIndexDetails(ik1,ItemKey2)
	, '..ClassServer.GetQueryDetails(ik1,ItemKey2)
	, '..ClassServer.GetMethodDetails(ik1,"%DispatchGetProperty")
	, '..ClassServer.GetMethodDetails(ik1,"%DispatchMethod")
	{
		;If ik1="%SQL.StatementResult" {
		;	; probably a dispacth property, don't bother with indexing these
		;	; possibly we could link to the query?
		;	Set save=0
		;
		;}
		$$$DEBUG("ItemKey1 set to UNKNOWN: "_ItemKey1_":"_ItemKey2)
		Set ik1="UNKNOWN ("_ik1_")"
	}
}
If save {
	Set xref=##class(PXW.Xref.Data).%New()
	Set xref.CalledByType=..#CodeType
	Set xref.CalledByKey1=..CalledByClassName
	Set xref.CalledByKey2=..CalledByItemName
	Set xref.CalledByCommand=CalledByCommand
	Set xref.ItemType=ItemType
	;Set xref.ItemKey1=$SELECT(ItemKey1="*":ItemKey1,ItemType="CLS":..ClassServer.FullClassName(ItemKey1,$PIECE(..CalledByClassName,".",1,*-1)),1:ItemKey1)
	Set xref.ItemKey1=ik1
	Set xref.ItemKey2=ItemKey2
	If $ISOBJECT(Atom) {
		Set xref.CalledByKey3=$SELECT(..FixedLineNumber:..FixedLineNumber,1:Atom.line)-..ClassElementLineNumber
		Set xref.LineNumber=$SELECT(..FixedLineNumber:..FixedLineNumber,1:Atom.line)
	} Else {
		Set xref.LineNumber=0
	}

	Set sc=$$$OK
	If 'xref.AlreadyExists() {
		Set sc=xref.%Save()
		If $$$ISERR(sc) {
			$$$DEBUG($EXTRACT($SYSTEM.Status.GetErrorText(sc),1,100))
		} Else {
			$$$DEBUG("Saved "_xref.%Id())
		}
	}
	If $$$ISOK(sc),ItemType="CLS" {
		Set origin="",stub=""
		If ..ClassServer.GetMethodDetails(ItemKey1,ItemKey2,,.origin,.stub),origin'=ItemKey1 {
			; also xref the origin class
			If origin'="" {
				$$$DEBUG("Calling save(method) "_origin_":"_ItemKey2)
				Do ..SaveCOSXref(ItemType,origin,ItemKey2,CalledByCommand,Atom)
			}
		} ElseIf ..ClassServer.GetPropertyDetails(ItemKey1,ItemKey2,,,,.origin),origin'=ItemKey1 {
			; also xref the origin class
			If origin'="" {
				$$$DEBUG("Calling save(property) "_origin_":"_ItemKey2)
				Do:origin'="" ..SaveCOSXref(ItemType,origin,ItemKey2,CalledByCommand,Atom)
			}
		}
		If (stub'="") {
			If ($PIECE(stub,".",*)="q") {
				; if the item is a function based on a query (eg GetFunc) then xref the query
				Set query=$PIECE(stub,".",1)
				If query'="" {
					$$$DEBUG("Calling save(query) "_ItemKey1_":"_query)
					Do ..SaveCOSXref(ItemType,ItemKey1,query,CalledByCommand,Atom)
				}
			} ElseIf $PIECE(stub,".",*)="a" {
				; if the item is a function based on a property (eg ThingGetLogicalToDisplay) then xref the property
				Set prop=$PIECE(stub,".",1)
				If prop'="" {
					$$$DEBUG("Calling save(prop) "_ItemKey1_":"_prop)
					Do ..SaveCOSXref(ItemType,ItemKey1,prop,CalledByCommand,Atom)
				}
			} ElseIf $PIECE(stub,".",*)="i" {
				; if the item is a function based on an index (eg PKOpen) then xref the property
				Set index=$PIECE(stub,".",1)
				If index'="" {
					$$$DEBUG("Calling save(index) "_ItemKey1_":"_index)
					Do ..SaveCOSXref(ItemType,ItemKey1,index,CalledByCommand,Atom)
				}
			}

		}
	}
}

Set sc=$$$OK
$$$DEBUG("Saving SQL "_ItemType_","_ ItemKey1_","_ItemKey2_","_CalledByCommand)
Set xref=##class(PXW.Xref.Data).%New()
Set xref.CalledByType=..#CodeType 
Set xref.CalledByKey1=..CalledByClassName
Set xref.CalledByKey2=$SELECT($GET(CalledByKey2)'="":CalledByKey2,..CalledByItemName'="":..CalledByItemName,1:"unknown")

If $ISOBJECT(Atom) {
	Set xref.CalledByKey3=$SELECT(..FixedLineNumber:..FixedLineNumber,1:Atom.line)-..ClassElementLineNumber
	Set xref.LineNumber=$SELECT(..FixedLineNumber:..FixedLineNumber,1:Atom.line)
} Else {
	Set xref.LineNumber=0
}

Set xref.CalledByCommand=CalledByCommand
Set xref.ItemType=ItemType
Set xref.ItemKey1=ItemKey1
Set xref.ItemKey2=$TRANSLATE(ItemKey2,$CHAR(34),"") ; remove "" from sql names
If 'xref.AlreadyExists() {
	Set sc=xref.%Save()
	If $$$ISERR(sc) {
		$$$DEBUG($EXTRACT($SYSTEM.Status.GetErrorText(sc),1,100))
	}
}


If $$$ISOK(sc),ItemType="CLS" {
	If ..ClassServer.GetMethodDetails(ItemKey1,ItemKey2,,.origin),origin'=ItemKey1 {
		Do ..SaveCOSXref(ItemType,origin,ItemKey2,CalledByCommand,Atom)
	} ElseIf ..ClassServer.GetPropertyDetails(ItemKey1,ItemKey2,,,,.origin),origin'=ItemKey1 {
		Do ..SaveCOSXref(ItemType,origin,ItemKey2,CalledByCommand,Atom)
	}
}

    #dim atom as PXW.DEV.Atom
	#dim ele as PXW.DEV.Element

	$$$DEBUGMethodBegin
    Set oldXMLPath=..XMLPath

	Do ..processSpecificElement(element)

	If element.type="WithClause" {
       Set aliasE=element.findFirstElementByType("AliasName")	
	   Set oldwith=..WithName
	   Set ..WithName=aliasE.ToString(0)
	}
 	; from SQL
	Set oldInView=..InView

	Set akey=""
	For  {
		Set part=element.partsGetNext(.akey)
		Quit:akey=""

	    If part.IsElement {
			Do ..xrefElement(part)
		} ElseIf part.IsAtom {
			Set atom=part
            Set type=$$$UPPER($PIECE(atom.type,":",1))
            ; this is the word "method" or "property" etc
            If type="KEYWORD" {
               Set ..CalledByCommand=atom.value
            }
			If type="CDEFKEYWORD" {
               Set ..CalledByCommand=atom.value
            }

			If $ISOBJECT(..Analyser),$DATA(..Analyser.ElementWarnings(+atom)) {
				Set line=..Analyser.ElementWarnings(+atom)
				Do ..SaveAnalysis(atom,line)
			}

			; type="ERROR" happens when a RECOVERY takes place
			; the part should contain a bit of code up to the point of the error
			If type="ERROR" {
				If ..ERROR="" {
					Set ..ERROR=part.ToString()
				}
			}
		}
	}

	Set ..InView=oldInView
	If $DATA(oldwith) Set ..WithName=oldwith
    Set ..XMLPath=oldXMLPath 

	$$$DEBUGMethodEnd

Set cnameE=element.findFirstElementByType("ClassName")
If $ISOBJECT(cnameE) {
	Set ..CalledByClassName=cnameE.ToString(0)
}
Quit ""

Set name=element.ToString(0)
Set ..CalledByItemName=name        
Set ..ClassElementLineNumber=element.FirstAtom().line
Set overrides=""
If $LISTFIND($LISTBUILD("MethodName"),element.type) {
	Set overrides=..ClassServer.GetMethodOverrides(..CalledByClassName_"||"_name)
}
If $LISTFIND($LISTBUILD("PropertyName"),element.type) {
	Set overrides=..ClassServer.GetPropertyOverrides(..CalledByClassName_"||"_name)
}
If $LISTFIND($LISTBUILD("ClassParameterName"),element.type) {
	Set overrides=..ClassServer.GetParameterOverrides(..CalledByClassName_"||"_name)
}
If overrides'="" {
	Set ..CalledByCommand="Override" 
	Do ..SaveCDEFCref(overrides,..ClassElementLineNumber,name)
}
Quit ""

    #dim ClassItemIdentifierE as PXW.DEV.Element
    Do element.findElementsXPath("IndexProperty/Fieldname/PropertyReference/ClassItemIdentifier",.props)
    If $ISOBJECT(props) {
        For i=1:1:props.Count() {
            Set ClassItemIdentifierE=props.GetAt(i)
            Set name=ClassItemIdentifierE.ToString(0)
			Set atom=ClassItemIdentifierE.FirstAtom()
            Do ..SaveCOSXref("CLS",..CalledByClassName,name,"_index",atom)
        }
    }
	Quit ""

Set nameE=element.findFirstElementByType("XdataName")
If $ISOBJECT(nameE) {
    Set name=nameE.ToString(0)
    Set ..XMLPath=..XMLPath_"/"_name
}
Quit ""

    $$$DEBUGMethodBegin
	$$$DEBUG("XMLPath="_..XMLPath)
    If ..XMLPath="/UrlMap/Routes/Route/Call" {
        Set callname=element.ToString(0)
        Set callname=$TRANSLATE(callname,"'""","") ; get rid of quotes
        ;Do ..wrapElementHTML(element,"<a class="""_$$$classObjectMember_""" href="""_..HREFToClass(..This,callname)_""">","</a>")
		Do ..SaveCOSXref("CLS",..This,callname,"_Call",element.FirstAtom())
    } Else {
        ;Do ..wrapElementHTML(element,"<span class='XMLTag' title="""_..XMLPath_""">","</span>")
    }
    $$$DEBUGMethodEnd
    Quit ""

UDLText.Content:
/*
Method xrefCDEF(element as PXW.DEV.BNF.Elements.ClassDefinition) As PXW.DEV.BNF.Compilers.elementHandler(Type="")
{
	quit ""
}
*/

Method.Implementation:
	$$$DEBUGMethodBegin
    #dim chainE as PXW.DEV.Element
	#dim atom as PXW.DEV.Atom

    Set classname="%SYSTEM"
    Set key="",chainE=""
    For  {
		; DOES THIS WORK!?
        Set part=element.partsGetNext(.key)
        Quit:key=""
        If $PIECE(part.type,":",1)="ObjectMemberIdentifier" {
			Set atom=part
            Set classname=classname_"."_atom.value
        } ElseIf part.type="ObjectChain" {
            Set chainE=part
        }
    }
    ;if $ISOBJECT(firstAtomOfClass),$ISOBJECT(lastAtomOfClass) {
        ;do ..wrapAtomHTML(firstAtomOfClass,"<a class="""_$$$classProgramName_""" href="""_..HREFToClass(classname)_""">","")
        ;do ..wrapAtomHTML(lastAtomOfClass,"","</a>")
    ;}
    Do:$ISOBJECT(chainE) ..FollowObjectChainForType(chainE,classname)
    $$$DEBUGMethodEnd
    Quit ""

	$$$DEBUGMethodBegin
	Set variablename=element.ToStringAtomsOnly(0)
	; variable could be something like {*} or {field}  so the name above (using atoms only) will not find anything
	; don't worry about that at the moment!
	$$$DEBUG("xrefCOSVariable, variablename="_variablename)
	If variablename'="" {
		; when working out a type use the #DIM type if there is one
		Set classname=$GET(..Analyser.DimmedTypes(variablename))
		If classname="" {
			Set classname=$GET(..Analyser.VariablesTypesElement(+element))
			Set:classname="" classname=$GET(..Analyser.VariablesTypes(variablename))
		}
		$$$DEBUG("xrefCOSVariable, variablename="_variablename_", classname="_classname)
		If classname'="" {
			Do ..FollowObjectChainForType(element,classname)
		}

        ; treat %parameter("xxx") as a parameter
        If ..Analyser.CodeMode="OBJECTGENERATOR",variablename="%parameter" {
            Set arrayE=element.findFirstElementByType(("ArrayParameterList"),0)
            If $ISOBJECT(arrayE) {
                Set parameter=..Analyser.SimplifySubscripts(arrayE)
                ; is the paremeter a string
                If parameter?1"""".AN1"""" {
					Set atom=arrayE.FirstAtom()
 					Do ..SaveCOSXref("CLS",..CalledByClassName,$TRANSLATE(parameter,"""",""),"%parameter",atom)
                }
            }
        }

	}
	$$$DEBUGMethodEnd
	Quit ""

	#dim strElement as PXW.DEV.Element
	#dim atom as PXW.DEV.Atom

	$$$DEBUGMethodBegin
	If $ISOBJECT(..Analyser),$DATA(..Analyser.stringVarsElementLast(+element)) {
        Set varname=..Analyser.stringVarsElementLast(+element)
		Set value=$GET(..Analyser.stringVars(varname))
        If value'="" {
			; does it look like it might be sql?
			Set normValue=$$$UPPER($TRANSLATE(value,$CHAR(13,9),"  "))
			Set selectfound=$FIND(normValue,"SELECT ")
			Set fromfound=$FIND(normValue,"FROM ")
			Set bracketFound=$FIND(normValue,"(")
			; want a select followed by a from, but if there is a bracket then the select should be before to exclude partial subquery strings eg "and id in (select id from ...)"
			If selectfound,fromfound>selectfound,((bracketFound=0)||(selectfound<bracketFound)) {
				; its being treated as SQL so format it a bit (the simplify deals with array of strings not quite right for this function)
				; try and format it so its similar to the format in the source code
				Set strElement=..Analyser.stringVarsElement(+element,"element")
				; try and format it so its similar to the format in the source code
				Set formatted="",line=0
				For i=1:1:strElement.partsCount() {
					Set atom=strElement.partsGetAt(i)
					If atom.line>line {
						If line>0 {
							Set formatted=formatted_$CHAR(13)
						}
					}
					Set line=atom.line ; always update the line, its possible to go backwards!
					Set formatted=formatted_atom.value
				}
				;
				Set parser=##class(PXW.DEV.BNF.Run.SQL).%New()
				Set parser.stream=##class(PXW.DEV.InputStream).NewString(formatted)
				Set sqlelement=##class(PXW.DEV.Element).%New()
				Set atom=element.FirstAtom()
				; parsing a made up string as if it COULD be SQL, anything could happen so just try it
				Try {
					If parser.SqlProgram(sqlelement) {
						If sqlelement.partsCount()>0 {
							Set newXrefer=..%New()
							Set newXrefer.CalledByItemName=..CalledByItemName
							Set newXrefer.CalledByClassName=..CalledByClassName
							Set newXrefer.ClassElementLineNumber=..ClassElementLineNumber
							Set newXrefer.Analyser=..Analyser
							Set newXrefer.ClassServer=..ClassServer
							Set newXrefer.FixedLineNumber=atom.line
							Do newXrefer.xrefElement(sqlelement)
							If newXrefer.ERROR'="" {
								Do ..SaveAnalysis(atom,"SQL String parse error "_..ERROR)
							}
							If 'parser.stream.EOF() Do ..SaveAnalysis(atom,"SQL String parse incomplete: "_parser.stream.Peek(0,20))
						} Else {
							Do ..SaveAnalysis(atom,"SQL String found no elements")
						}
					} Else {
						Do ..SaveAnalysis(atom,"SQL String cannot be parsed")
					}
				} Catch e {
					Do ..SaveAnalysis(atom,"SQL String cannot be parsed, error:"_$SYSTEM.Status.GetErrorText(e.AsStatus()))
				}
			}
        }
    }
	$$$DEBUGMethodEnd
	Quit ""

	$$$DEBUGMethodBegin
    If $ISOBJECT(..Analyser) {
        Set expressionE=element.findFirstElementByType("Expression")
        If $ISOBJECT(expressionE) {
            Set simple=..Analyser.SimplifyExpression(expressionE) 
            ; its a string, so its a hard coded method name
            If $EXTRACT(simple,1)="""",$EXTRACT(simple,*)="""" {
                Set mname=$TRANSLATE(simple,"""","")
				Set atom=expressionE.FirstAtom()
				Do ..SaveCOSXref("CLS","*",mname,"$classmethod",atom)
            }
        }
    }
	$$$DEBUGMethodEnd
    Quit ""

    Set method=element.ToString(0)
	Set atom=element.FirstAtom()
    ; method in ..this class
    If method?1".."1.E {
		Do ..SaveCOSXref("CLS",..CalledByClassName,$PIECE(method,"..",2),"JScall",atom)
    } Else {
		Do ..SaveCOSXref("CLS",$PIECE(method,".",1,*-1),$PIECE(method,".",*),"JScall",atom)
    }
	Quit ""

Set setmode="fetch"
If element.type="GlobalRefSet" Set setmode="SET"


Set fullrefE=element.findFirstElementByType("GlobalRefFull",0)
If $ISOBJECT(fullrefE) {
	; On a global clicking on the ^ will take directly to the XREF since we don't
	; have any other details about the global at the moment.
	; Clicking on the name of the global highlights it like a regular variable
	Set globalElement=fullrefE.findFirstElementByType("GlobalName",0)
	Set upa=fullrefE.FirstAtom() ; ^ is always at the start
	Set namea=globalElement
	If $ISOBJECT(namea) {
		Set subsE=fullrefE.findFirstElementByType("SubscriptParameterList",0)
		Set subs=$SELECT($ISOBJECT(subsE):..Analyser.SimplifySubscripts(subsE),1:"_top")
		Do ..SaveCOSXref("GBL",namea.ToStringAtomsOnly(0),subs,setmode,upa)            
	}
} Else {
	; not sure what we can do with naked refs here (other than make them stand out as a bad thing)
}
Quit ""

Set atom=element.FirstAtom()
Set macroname=element.ToString(0)
Set macroname=$PIECE(macroname,"(",1)
If macroname?1"$$$"1.E {
	Set macroname=$PIECE(macroname,"$$$",2)
}
If ..ClassServer.GetMacroLocation(..CalledByClassName,macroname,.source) {
	If source'="" {
		; includename.inc is returned so file as INC and remove this from the name
		;Set type=$$$UPPER($PIECE(source,".",*))
		Set source=$PIECE(source,".",1,*-1)
		Do ..SaveCOSXref("INC",source,macroname,"_macro",atom)
	}
}
Quit ""

UDLText.Content:
/*
Method xrefCOS(element as PXW.DEV.BNF.Elements.COS) As PXW.DEV.BNF.Compilers.elementHandler(Type="")
{
	quit ""
}
*/

Method.Implementation:
	#dim cref as PXW.DEV.Element
	#dim sqlanalyse as PXW.DEV.BNF.Analyse.SQL
	Do ..SQLInternalXREF(element)
    If $ISOBJECT(..SqlProgramAnalyser) {
        Set sqlanalyse=$GET(..SqlProgramAnalyser.SelectCommandAnalysis(+element))
    } Else {
		Set sqlanalyse=""
	} 
	If sqlanalyse="" {
        ; certain types of subquery are not being coverded by the program analyse yet, so treat separately for now
	    Set sqlanalyse=##class(PXW.DEV.BNF.Analyse.analyser).NewForLanguage(..#CodeType,"SQL")
    	Set sqlanalyse.ClassServer=..ClassServer
        Set sqlanalyse.This=..CalledByClassName
        Do sqlanalyse.checkElement(element)
    }
	Set cref=""
	While sqlanalyse.NextColumnReference(.cref,.fulltable,.fieldname) {
		Kill CalledByItem
		If fulltable'="" {
			If ..InView {
				Set CalledByItem=""_$GET(..SQLPaths(+cref),"unk")
			}
			Kill patharray

			If $DATA(sqlanalyse.withReferences(fulltable)) {
				If ..InView {
					Set atom=cref.FirstAtom()
					Set command=element.type					
					; if this is a reference to a field in a "WITH" table then file a xref to it
					Do ..SaveSQLXref("CLS",..CalledByClassName,fulltable_"."_fieldname,command,atom,.CalledByItem)
				}
			} Else {
				Do ..ClassServer.GetClassPathFromTable(fulltable,fieldname,.patharray)			
				Set atom=cref.FirstAtom()
				Set command=element.type
				For i=1:1:$GET(patharray) {
					Set data=patharray(i)
					Set class=$LISTGET(data,1),item=$LISTGET(data,2)
					If class'="",item'="" {
						Do ..SaveSQLXref("CLS",class,item,command,atom,.CalledByItem)
					} 
				}
			}
		} Else {
			If ..InView {
				Set aliasNameE=cref.findFirstElementByType("AliasName",0)
				Set columnNameE=cref.findFirstElementByType("ColumnName",0)
				Set command=element.type
				Set atom=cref.FirstAtom()
				Set CalledByItem=""_$GET(..SQLPaths(+cref),"unk")
				If $ISOBJECT(aliasNameE),$ISOBJECT(columnNameE) {
					Do ..SaveSQLXref("CLS",..CalledByClassName,aliasNameE.ToString(0)_"."_columnNameE.ToString(0),command,atom,.CalledByItem)
				}
			}
		}

	}

	Quit ""

	#dim sqlanalyse as PXW.DEV.BNF.Analyse.SQL
    Set sqlanalyse=##class(PXW.DEV.BNF.Analyse.analyser).NewForLanguage(..#CodeType,"SQL")
    Set sqlanalyse.ClassServer=..ClassServer
	Set sqlanalyse.This=..CalledByClassName
	Do sqlanalyse.checkElement(element)
	Set columnNameE=""
	While sqlanalyse.NextColumnReference(.columnNameE,.fulltable,.fieldname) {
		Kill patharray
		Do ..ClassServer.GetClassPathFromTable(fulltable,fieldname,.patharray)
		Set atom=columnNameE.FirstAtom()
		Set command=element.type
		For i=1:1:$GET(patharray) {
			Set data=patharray(i)
			Set class=$LISTGET(data,1),item=$LISTGET(data,2)
			If class'="",item'="" {
				Do ..SaveSQLXref("CLS",class,item,command,atom)
			}
		}
	}
	Quit ""

	#dim sqlanalyse as PXW.DEV.BNF.Analyse.SQL
    Set sqlanalyse=##class(PXW.DEV.BNF.Analyse.analyser).NewForLanguage(..#CodeType,"SQL")
    Set sqlanalyse.ClassServer=..ClassServer
	Set sqlanalyse.This=..CalledByClassName
	Do sqlanalyse.checkElement(element)
	Set columnNameE=""
	While sqlanalyse.NextColumnReference(.columnNameE,.fulltable,.fieldname) {
		Kill patharray
		Do ..ClassServer.GetClassPathFromTable(fulltable,fieldname,.patharray)
		Set atom=columnNameE.FirstAtom()
		Set command=element.type
		For i=1:1:$GET(patharray) {
			Set data=patharray(i)
			Set class=$LISTGET(data,1),item=$LISTGET(data,2)
			If class'="",item'="" {
				Do ..SaveSQLXref("CLS",class,item,command,atom)
			}
		}
	}
	Quit ""

	#dim sqlanalyse as PXW.DEV.BNF.Analyse.SQL
    Set sqlanalyse=##class(PXW.DEV.BNF.Analyse.analyser).NewForLanguage(..#CodeType,"SQL")
    Set sqlanalyse.ClassServer=..ClassServer
	Set sqlanalyse.This=..CalledByClassName
	Do sqlanalyse.checkElement(element)
	Set columnNameE=""
	Kill tables
	While sqlanalyse.NextColumnReference(.columnNameE,.fulltable,.fieldname) {
		Kill patharray
		Do ..ClassServer.GetClassPathFromTable(fulltable,fieldname,.patharray)
		Set atom=columnNameE.FirstAtom()
		Set command=element.type
		For i=1:1:$GET(patharray) {
			Set data=patharray(i)
			Set class=$LISTGET(data,1),item=$LISTGET(data,2)
			If class'="",item'="" {
				Do ..SaveSQLXref("CLS",class,item,command,atom)
				If '$DATA(tables(class)) {
					Set tabatom=element.FirstAtom()
					Do ..SaveSQLXref("CLS",class,"_table",command,tabatom)
					Set tables(class)=1
				}
			}
		}
	}
	Quit ""

    $$$DEBUGMethodBegin
    Set spnameA=element.FirstAtom()
    If $ISOBJECT(spnameA),..This'="",$ISOBJECT(..ClassServer) {
        Set schema=..ClassServer.GetClassSchemaName(..This)
        If schema'="" {
			Set class=..ClassServer.GetClassNameFromStoredProc(schema_"."_spnameA.ToString(0),.method,..CalledByClassName)
			Set cbk2=$GET(..SQLPaths(+element),"unk")
			If class'="" {
				Set atom=element.FirstAtom()
				Set command=element.type
				Do ..SaveSQLXref("CLS",class,method,command,atom,cbk2)
			}
        }
    }
    $$$DEBUGMethodEnd
    Quit ""

Set spNameE=element
If $ISOBJECT(spNameE) {
	Set spname=spNameE.ToString(0)
	Set class=..ClassServer.GetClassNameFromStoredProc(spname,.method,..CalledByClassName)
	Set cbk2=$GET(..SQLPaths(+element),"unk")
	If class'="" {
		Set atom=element.FirstAtom()
		Set command=element.type
		Do ..SaveSQLXref("CLS",class,method,command,atom,cbk2)
	}
}
Quit ""

UDLText.Content:
/*
Method xrefSQL(element as PXW.DEV.BNF.Elements.SQL) As PXW.DEV.BNF.Compilers.elementHandler(Type="")
{
	quit ""
}
*/

Method.Implementation:
	#dim atom as PXW.DEV.Atom

    If (ParentElement.type="ThisObject") || (ParentElement.type="ThisObjectSet") {
        Set this=ParentElement.findFirstElementByType("ThisObjectSelf",0) ; ..property
        If $ISOBJECT(this) {
            Set objectchain=this.findFirstElementByType("ObjectChainNoDot",0)
        } Else {
            Set this=ParentElement.findFirstElementByType("ThisObjectThis",0) ; $this.property
            If $ISOBJECT(this) {
                Set objectchain=this.findFirstElementByType("ObjectChain",0)
            }
        }
    } ElseIf (ParentElement.type="ThisObjectDirectProperty") || (ParentElement.type="ThisObjectDirectPropertySet") {
        Set objectchain=ParentElement.findFirstElementByType("ObjectChainItem",0) ; i%property
    } Else {
        Set objectchain=ParentElement.findFirstElementByType("ObjectChain",1) ; var.property
    }
    Set path="",sep=""
	Set toclass=StartClassName
    While $ISOBJECT(objectchain) {
		$$$DEBUG("Following chain:"_toclass)

        Set propertyatom="",akey=""
        ; the objectchain has the "." and the name
        For  {
            Set atom=objectchain.partsGetNext(.akey)
            Quit:akey=""

            If atom.IsAtom,atom.value'="." {
                Set propertyatom=atom
            }
        }

		Set command=ParentElement.type
		Do ..SaveCOSXref("CLS",toclass,propertyatom.value,command,propertyatom)
		Set toclass=$GET(..Analyser.VariablesTypesElement(+objectchain))
        Set path=path_sep_propertyatom.value,sep="."
		Do ..xrefCOSParameterChecks(StartClassName,path,objectchain)

        Set objectchain=objectchain.findFirstElementByType("ObjectChain",0) 
    }
	/*If path'="" {
		Do ..ClassServer.GetClassPath(StartClassName,path,.patharray)
		Set atom=ParentElement.FirstAtom()
		Set command=ParentElement.type
		For i=1:1:$GET(patharray) {
			Set data=patharray(i)
			Set class=$LISTGET(data,1),item=$LISTGET(data,2)
			If $EXTRACT(item,1)="#" Set item=$EXTRACT(item,2,*) ; strip the # from parameters
			If class'="",item'="" {
				Do ..SaveCOSXref("CLS",class,item,command,atom)
			}
		}
	}*/

If '$DATA(..SQLPaths(+Element)) {

	If Element.type="SubquerySpecification" {

	}

	If Element.type="DerivedTable" {
		Set TableAsClauseE=Element.findFirstElementByType("TableAsClause",0)
		If $ISOBJECT(TableAsClauseE) {
			Set TableNameE=TableAsClauseE.findFirstElementByType("AliasName",0)
			If $ISOBJECT(TableNameE) {
				Set table=TableNameE.ToString(0)
				Set column=""
			}
		}
	}
	If Element.type="DerivedColumn" {
		Do ##class(PXW.DEV.BNF.Analyse.SQL).GetDerivedColumnInfo(Element,.colname)
		If column="" Set column=colname 
	}
	Set ..SQLPaths(+Element)=$SELECT(column'="":"column:"_$SELECT(table'="":$$$UPPER(table)_".",..WithName'="":$$$UPPER(..WithName)_".",1:"")_$$$UPPER(column),1:"")
	Set ..SQLPaths(+Element,"string")=Element.ToString(0)
	Set akey=""
	For  {
		Set atom=Element.partsGetNext(.akey)
		Quit:akey=""

		If atom.IsElement {
			Do ..SQLInternalXREF(atom,table,column)
		}
	}
}

	#dim a as PXW.DEV.Atom
	#dim e as PXW.DEV.Element

    If '$ISOBJECT($GET(AtomList)) Set AtomList=##class(%Library.ListOfObjects).%New()

 	Set list=""
	Set akey=""
    If Element.partsCount()=1 {
        Set single=1
    } Else {
        Set single=0
    }
	If 'single {
        ;Set list=list_$lb(Element.type)
    }
	For  {
		Set a=Element.partsGetNext(.akey)
		Quit:akey=""

        If a.IsElement {
            Set list=list_..flattenlist(a,.AtomList)
        } ElseIf $PIECE(a.type,":",1)="punctuation" {
            ; forget punctuation for the timebeing
            ;Set list=list_$lb($lb("punctuation",a.value))
            ;do AtomList.Insert(a)

            ; Unless the thing truely IS punctuation. Due to complexity deep in the parser $this counts as punctuation, which is wrong.
            If a.value'?1.P {
                Set list=list_$LISTBUILD($LISTBUILD("keyword",a.value))
                Do AtomList.Insert(a)
            }

        } Else {
            Set list=list_$LISTBUILD($LISTBUILD($PIECE(a.type,":",1),a.value))
            Do AtomList.Insert(a)
        }		
	}
	If 'single {
        ;Set str=str_"}"
    }
	Quit list

	#dim ele as PXW.DEV.Element

	Set sc=$$$OK

    Set ClassServer=##class(PXW.DEV.Dictionary.ClassDefinitionObject).OpenNamespace(Namespace)
	Set text=PreLoadedText

    ;Do ClassServer.CacheClearClassDetails(ItemKey1,1) ; pretend the class is deleted so that it REALLY clears it

	If $$$ISOK(sc) {
        set ..Analyser=##class(PXW.DEV.BNF.Analyse.analyser).NewForLanguage(..#CodeType,"COS")
 		Set ..ClassServer=ClassServer
        Set ..CalledByClassName=ItemKey1
		Set ..This=$s($$$UPPER($p(ItemKey1,".",*))="MAC":$p(ItemKey1,".",1,*-1),1:ItemKey1)

		Try {
			Set parser=##class(PXW.DEV.BNF.Run.COS).%New()
  		    Set parser.stream=##class(PXW.DEV.InputStream).NewString(text)

			Set element=##class(PXW.DEV.Element).%New()
			if parser.CosCodeBlock(element) {
   				Do ..xrefElement(element)
   				If ..ERROR'="" $$$ThrowStatus($$$ERROR(5001,..ERROR))
				Set element=##class(PXW.DEV.Element).%New()
			}
			If 'parser.stream.EOF() Set sc=$$$ERROR(5001,"Not at end:"_parser.stream.line_":"_x.stream.pos_":"_parser.stream.length_":"_$EXTRACT(parser.stream.input,parser.stream.lastPos,parser.stream.lastPos+20))
		} Catch e {
			Set sc=e.AsStatus()
		}
	}
	Quit sc

#dim e as %Exception.SystemException

Set ClassServer=$GET(%PXWClassServer(%NS,CodeType))

If WindowSize=0 Quit ""
Set ws=WindowSize-1
Try {
	If CodeType'="" {
		If '$ISOBJECT(ClassServer) {
			Set ClassServer=##class(PXW.DEV.Dictionary.CodeInterface).OpenForType(%NS,CodeType)
			Set %PXWClassServer(%NS,CodeType)=ClassServer
		}
		If '$DATA(%PXWCacheCode(%NS,CodeType,CodeKey1)) {
			Set sc=ClassServer.LoadAsArray(CodeKey1,.lines)
			If $$$ISOK(sc) {
				Merge %PXWCacheCode(%NS,CodeType,CodeKey1)=lines
			} Else {
				Set %PXWCacheCode(%NS,CodeType,CodeKey1,"ERROR")=$SYSTEM.Status.GetErrorText(sc)
			}
		}
		If '$DATA(%PXWCacheCode(%NS,CodeType,CodeKey1,"ERROR")) {
			Set code="",sep=""
			Set from=LineNumber-ws
			If from<1 Set from=1
			Set to=LineNumber+ws
			If to>%PXWCacheCode(%NS,CodeType,CodeKey1) Set to=%PXWCacheCode(%NS,CodeType,CodeKey1)
			For i=from:1:to Set code=code_sep_%PXWCacheCode(%NS,CodeType,CodeKey1,i),sep=$CHAR(13,10)
		} Else {
			Set code=%PXWCacheCode(%NS,CodeType,CodeKey1,"ERROR")
		}
	}
} Catch e {
	Set code=e.DisplayString()
}
Quit code

Set qHandle=$ORDER(%PXWTree(qHandle),1,Row)
If qHandle="" {
	Set AtEnd=1
	Set Row=""
} 
Quit $$$OK

